/**
 * Сломанные туалеты и автоматы: лужа под предметом и иконка «нужен уборщик»
 * над ним, по которой можно тапнуть, чтобы починить самому.
 *
 * Порт setRoomItemUsageCount (WorldRestaurantPlay.as:1613): у сломанного туалета
 * оригинал показывал объект `ToiletWater` под ним и `CleanerNeeded` на высоте
 * тайла сверху. Оба ассета вытащены из SWF.
 *
 * Лужа лежит в сортируемом слое (её перекрывают персонажи), иконка — в слое
 * эффектов поверх.
 */

import type { engine } from '@rv/shared';
import { Assets, type Container, type FederatedPointerEvent, Rectangle, Sprite } from 'pixi.js';
import { asset } from '../asset-url';
import { DEPTH_BIAS, TILE_H, isoDepth, tileToScreen } from './iso';

/** Зона тапа под палец — та же логика, что у мусора. */
const MIN_HIT_SIZE = 44;

export type FacilityTextures = {
  cleanerNeeded: Sprite['texture'];
  toiletWater: Sprite['texture'];
};

export async function loadFacilityTextures(): Promise<FacilityTextures> {
  const cleanerUrl = asset('fx/cleaner_needed.png');
  const waterUrl = asset('fx/toilet_water.png');
  const assets = (await Assets.load([cleanerUrl, waterUrl])) as Record<string, Sprite['texture']>;
  return {
    cleanerNeeded: assets[cleanerUrl]!,
    toiletWater: assets[waterUrl]!,
  };
}

type FacilityNode = {
  icon: Sprite;
  puddle: Sprite | null;
};

export class FacilityLayer {
  private readonly nodes = new Map<string, FacilityNode>();
  private interactive = true;

  constructor(
    /** Сортируемый слой — для лужи под предметом. */
    private readonly sortLayer: Container,
    /** Слой эффектов — для иконки поверх. */
    private readonly fxLayer: Container,
    private readonly tex: FacilityTextures,
    /** Тап по иконке — сцена передаст id в симуляцию. */
    private readonly onRepair: (itemId: string) => void,
  ) {}

  /** Привести набор индикаторов к списку сломанных предметов из симуляции. */
  sync(broken: readonly engine.PlacedItem[]): void {
    const alive = new Set(broken.map((i) => i.id));
    for (const [id, node] of this.nodes) {
      if (alive.has(id)) continue;
      this.remove(id, node);
    }
    for (const item of broken) {
      if (this.nodes.has(item.id)) continue;
      this.nodes.set(item.id, this.createNode(item));
    }
  }

  private remove(id: string, node: FacilityNode): void {
    this.fxLayer.removeChild(node.icon);
    node.icon.destroy();
    if (node.puddle) {
      this.sortLayer.removeChild(node.puddle);
      node.puddle.destroy();
    }
    this.nodes.delete(id);
  }

  private createNode(item: engine.PlacedItem): FacilityNode {
    const screen = tileToScreen(item.tileX, item.tileY);
    const cx = screen.x;
    const cy = screen.y + TILE_H / 2;

    // Лужа — только у туалетов (в оригинале ToiletWater вешался именно на них).
    let puddle: Sprite | null = null;
    if (item.definition.type.includes('toilet')) {
      puddle = new Sprite(this.tex.toiletWater);
      puddle.anchor.set(0.5, 0.5);
      puddle.position.set(cx, cy + 4);
      // Чуть ниже самого предмета, но выше пола.
      puddle.zIndex = isoDepth(item.tileX, item.tileY) + DEPTH_BIAS.puddle;
      this.sortLayer.addChild(puddle);
    }

    const icon = new Sprite(this.tex.cleanerNeeded);
    icon.anchor.set(0.5, 1);
    icon.position.set(cx, cy - TILE_H - 24);
    const hitW = Math.max(MIN_HIT_SIZE, icon.width);
    const hitH = Math.max(MIN_HIT_SIZE, icon.height);
    // Интерактивен сам спрайт: у Container'а нет геометрии для hit-теста.
    icon.hitArea = new Rectangle(-hitW / 2, -hitH, hitW, hitH);
    icon.eventMode = this.interactive ? 'static' : 'none';
    icon.cursor = 'pointer';
    icon.on('pointertap', (e: FederatedPointerEvent) => {
      e.stopPropagation();
      this.onRepair(item.id);
    });
    this.fxLayer.addChild(icon);

    return { icon, puddle };
  }

  /** Пульсация иконки, чтобы поломку было видно. */
  update(dtMs: number): void {
    if (this.nodes.size === 0) return;
    this.phase = (this.phase + dtMs / 600) % (Math.PI * 2);
    const scale = 1 + Math.sin(this.phase) * 0.08;
    for (const node of this.nodes.values()) node.icon.scale.set(scale);
  }

  private phase = 0;

  setInteractive(on: boolean): void {
    this.interactive = on;
    for (const node of this.nodes.values()) {
      node.icon.eventMode = on ? 'static' : 'none';
      node.icon.cursor = on ? 'pointer' : 'default';
    }
  }

  clear(): void {
    for (const [id, node] of [...this.nodes]) this.remove(id, node);
  }
}
