/**
 * Функциональные предметы: туалеты, раковины, игровые автоматы.
 *
 * Порт того, что в оригинале жило прямо на RoomItem (`toilet`, `sink`,
 * `interactive`, `usageCount`, `isBroken`) плюс `setRoomItemUsageCount`
 * (WorldRestaurantPlay.as:1613) и `fixBreakableItem` (:2303).
 *
 * Логика:
 *   - каждый предмет с `breakCount` считает использования; когда счётчик
 *     достигает breakCount, предмет сломан и больше не работает (у туалета
 *     оригинал рисовал лужу и иконку «нужен уборщик»);
 *   - чинит уборщик, а до его найма — сам игрок тапом;
 *   - за каждое использование ресторан получает COINS_PAYOUT_FUNCTIONAL_ITEMS
 *     монет и gourmet point (`onCustomerPayForFunctional` :1389).
 *
 * Классификация — по флагам `type` из restaurant.xml, а не по захардкоженным
 * спискам: `toilet`, `sink`, `interactive`.
 */

import { Balance } from './balance';
import type { ItemDefinition, PlacedItem } from './types';

export type FacilityKind = 'toilet' | 'sink' | 'interactive';

export function facilityKind(def: ItemDefinition): FacilityKind | null {
  if (def.type.includes('toilet')) return 'toilet';
  if (def.type.includes('sink')) return 'sink';
  if (def.type.includes('interactive')) return 'interactive';
  return null;
}

export function isToilet(def: ItemDefinition): boolean {
  return def.type.includes('toilet');
}

export function isSink(def: ItemDefinition): boolean {
  return def.type.includes('sink');
}

export function isInteractive(def: ItemDefinition): boolean {
  return def.type.includes('interactive');
}

/** Сериализуемое состояние: счётчики использований по id предмета. */
export type FacilitiesState = {
  usage: Record<string, number>;
};

export class Facilities {
  /** itemId → сколько раз предметом воспользовались с последней починки. */
  private readonly usage = new Map<string, number>();

  constructor(state?: Partial<FacilitiesState> | null) {
    for (const [id, count] of Object.entries(state?.usage ?? {})) {
      if (Number.isFinite(count) && count > 0) this.usage.set(id, count);
    }
  }

  usageOf(item: PlacedItem): number {
    return this.usage.get(item.id) ?? 0;
  }

  /** Сколько ещё раз предметом можно воспользоваться. Infinity — не ломается. */
  usesLeft(item: PlacedItem): number {
    const max = item.definition.breakCount;
    if (max == null) return Number.POSITIVE_INFINITY;
    return Math.max(0, max - this.usageOf(item));
  }

  isBroken(item: PlacedItem): boolean {
    const max = item.definition.breakCount;
    if (max == null) return false;
    return this.usageOf(item) >= max;
  }

  /** Отметить использование. Возвращает true, если предмет от этого сломался. */
  use(item: PlacedItem): boolean {
    const next = this.usageOf(item) + 1;
    this.usage.set(item.id, next);
    return this.isBroken(item);
  }

  /** Починить (уборщиком или тапом игрока). */
  repair(item: PlacedItem): void {
    this.usage.delete(item.id);
  }

  /** Забыть предмет — его убрали из зала. */
  forget(itemId: string): void {
    this.usage.delete(itemId);
  }

  /** Выбросить счётчики предметов, которых больше нет в расстановке. */
  prune(existingIds: Iterable<string>): void {
    const alive = new Set(existingIds);
    for (const id of [...this.usage.keys()]) {
      if (!alive.has(id)) this.usage.delete(id);
    }
  }

  toJSON(): FacilitiesState {
    return { usage: Object.fromEntries(this.usage) };
  }
}

/**
 * Доступен ли туалет игроку этого уровня. В оригинале гости начинают ходить
 * в туалет с TOILET_START_LEVEL (8) — и с этого же момента его отсутствие
 * начинает злить (EMOTION_NO_TOILET).
 */
export function toiletsUnlocked(level: number): boolean {
  return level >= Balance.TOILET_START_LEVEL;
}
