/**
 * Каталог ItemDefinition'ов — единый источник правды для контента ресторана.
 *
 * Источник: packages/shared/src/content/data/restaurant-items.json
 * (сгенерирован scripts/import-content.ts из original restaurant.xml).
 *
 * Грузим один раз при инициализации, ставим в Map'ы по id и по className
 * для быстрых lookup'ов из WorldRestaurant.fromLayout и UI шопа.
 */

import restaurantItemsData from '../../content/data/restaurant-items.json';
import { RestaurantItem } from '../../content/schemas';
import type { ItemDefinition } from './types';

const validated = RestaurantItem.array().parse(restaurantItemsData);

const byId = new Map<number, ItemDefinition>();
const byClassName = new Map<string, ItemDefinition>();

for (const raw of validated) {
  const def: ItemDefinition = {
    id: raw.id,
    className: raw.className,
    name: raw.name,
    group: raw.group,
    type: raw.type,
    sizeX: raw.sizeX,
    sizeY: raw.sizeY,
    functions: raw.functions,
    breakCount: raw.breakCount,
    operateTimePercentage: raw.operateTimePercentage,
    cost: raw.cost,
    cash: raw.cash,
    unlockLevel: raw.unlockLevel,
    invisible: raw.invisible,
    isNew: raw.isNew,
  };
  byId.set(def.id, def);
  byClassName.set(def.className, def);
}

export function lookupById(contentId: number): ItemDefinition | null {
  return byId.get(contentId) ?? null;
}

export function lookupByClassName(className: string): ItemDefinition | null {
  return byClassName.get(className) ?? null;
}

export function allDefinitions(): ItemDefinition[] {
  return Array.from(byId.values());
}
