/**
 * Диапазоны кадров анимаций аватара — порт Avatar3D.ANIMATION_FRAME_RANGE.
 *
 * Оригинальная COLLADA-дорожка непрерывна (~14.5с, 146 кадров @ 10 fps).
 * Именованные анимации (idle/walk/sit/…) — это диапазоны кадров внутри неё.
 * three.js AnimationUtils.subclip(clip, name, startFrame, endFrame, fps)
 * нарезает их так же, как делал движок игры.
 */

export const AVATAR_FPS = 10;

export type AvatarAnimation = {
  name: string;
  /** Первый кадр (включительно). */
  start: number;
  /** Последний кадр (включительно). */
  end: number;
  /** Множитель задержки кадра из оригинала (медленнее/быстрее). */
  delay: number;
};

/**
 * Из Avatar3D.ANIMATION_FRAME_RANGE (пары) + ANIMATION_FRAME_DELAY_MULTIPLIER.
 * Берём только осмысленные для демо состояния.
 */
export const AVATAR_ANIMATIONS: Record<string, AvatarAnimation> = {
  walk: { name: 'walk', start: 0, end: 3, delay: 1.75 },
  waiterWalk: { name: 'waiterWalk', start: 10, end: 13, delay: 2 },
  idle: { name: 'idle', start: 20, end: 23, delay: 2 },
  cooking: { name: 'cooking', start: 30, end: 33, delay: 3 },
  sit: { name: 'sit', start: 35, end: 35, delay: 150 },
  eat: { name: 'eat', start: 36, end: 39, delay: 4 },
  /** ANIMATION_DEAD: одиночный кадр 133 — так оригинал показывал выдохшегося. */
  dead: { name: 'dead', start: 133, end: 133, delay: 150 },
};

export const AVATAR_ANIMATION_ORDER = [
  'idle',
  'walk',
  'waiterWalk',
  'cooking',
  'sit',
  'eat',
  'dead',
] as const;
