/**
 * Статичная геометрия зала: задние стены с дверными проёмами, сетка пола и
 * подсветка клетки под курсором. Чистая графика — никакой игровой логики.
 */

import { Graphics } from 'pixi.js';
import { TILE_H, TILE_W, tileToScreen } from './iso';

/**
 * Высота задних стен, px экрана.
 *
 * Не произвольная: ровно столько занимает панель обоев из indoor_asset
 * (`Wall17_1.png` — непрозрачная часть 40×117 px с изо-скосом 1:2). При
 * прежних 120 над оклеенным сегментом оставалась тёмная полоска в три
 * пикселя, и обои читались как отдельная доска, приставленная к стене.
 */
export const WALL_HEIGHT = 117;

/** Высота проёма двери (ниже — ниша, выше остаётся перемычка-стена). */
const DOOR_OPENING_HEIGHT = 88;

/** Проём в задней стене: на какой стене и в какой клетке. */
export type WallGap = { wall: 'left' | 'right'; index: number };

/**
 * Две задние стены — СПЛОШНЫЕ вертикальные плоскости вдоль рёбер tx=0
 * (задняя-левая) и ty=0 (задняя-правая), сходящиеся в верхнем углу комнаты.
 * Без посегментных линий, чтобы стена читалась цельной. Проём двери — тёмная
 * ниша в нижней части клетки двери, над ней остаётся перемычка.
 */
export function drawBackWalls(width: number, height: number, gaps: WallGap[] = []): Graphics {
  const g = new Graphics();
  const A = tileToScreen(0, 0); // общий верхний угол
  const B = tileToScreen(0, height); // низ задней-левой стены
  const C = tileToScreen(width, 0); // низ задней-правой стены

  g.moveTo(A.x, A.y)
    .lineTo(B.x, B.y)
    .lineTo(B.x, B.y - WALL_HEIGHT)
    .lineTo(A.x, A.y - WALL_HEIGHT)
    .closePath()
    .fill({ color: 0x2a3340 });
  g.moveTo(A.x, A.y)
    .lineTo(C.x, C.y)
    .lineTo(C.x, C.y - WALL_HEIGHT)
    .lineTo(A.x, A.y - WALL_HEIGHT)
    .closePath()
    .fill({ color: 0x35404f });

  for (const gap of gaps) {
    const t = gap.wall === 'left' ? tileToScreen(0, gap.index) : tileToScreen(gap.index, 0);
    const b = gap.wall === 'left' ? tileToScreen(0, gap.index + 1) : tileToScreen(gap.index + 1, 0);
    g.moveTo(t.x, t.y)
      .lineTo(b.x, b.y)
      .lineTo(b.x, b.y - DOOR_OPENING_HEIGHT)
      .lineTo(t.x, t.y - DOOR_OPENING_HEIGHT)
      .closePath()
      .fill({ color: 0x10151c });
  }

  // Верхняя кромка — тонкая светлая линия для чёткости силуэта.
  g.moveTo(B.x, B.y - WALL_HEIGHT)
    .lineTo(A.x, A.y - WALL_HEIGHT)
    .lineTo(C.x, C.y - WALL_HEIGHT)
    .stroke({ color: 0x44505f, width: 1.5, alpha: 0.8 });

  return g;
}

export function drawGrid(width: number, height: number): Graphics {
  const g = new Graphics();
  for (let tx = 0; tx < width; tx++) {
    for (let ty = 0; ty < height; ty++) {
      // c — верхний угол клетки; ромб строится ВНИЗ от него (см. iso.ts).
      const c = tileToScreen(tx, ty);
      g.moveTo(c.x, c.y);
      g.lineTo(c.x + TILE_W / 2, c.y + TILE_H / 2);
      g.lineTo(c.x, c.y + TILE_H);
      g.lineTo(c.x - TILE_W / 2, c.y + TILE_H / 2);
      g.lineTo(c.x, c.y);
    }
  }
  g.stroke({ color: 0x3b4a5f, width: 1, alpha: 0.6 });
  return g;
}

export function drawTileHighlight(g: Graphics, tx: number, ty: number, valid: boolean): void {
  g.clear();
  const c = tileToScreen(tx, ty);
  g.moveTo(c.x, c.y);
  g.lineTo(c.x + TILE_W / 2, c.y + TILE_H / 2);
  g.lineTo(c.x, c.y + TILE_H);
  g.lineTo(c.x - TILE_W / 2, c.y + TILE_H / 2);
  g.closePath();
  g.fill({ color: valid ? 0x37d27a : 0xd0463a, alpha: 0.35 });
  g.stroke({ color: valid ? 0x6ce8a4 : 0xff7a6d, width: 2 });
  g.visible = true;
}
