/**
 * Доска заказов ресторана — очереди между гостями, поварами и официантами.
 *
 * Порт трёх массивов WorldRestaurantPlay: orders (ждут повара),
 * completedOrders (готовы, ждут официанта) и emptyPlates (ждут уборки).
 * Уборка пустой тарелки — это момент, когда ресторан получает деньги
 * (clearEmptyPlate → onCustomerPay), поэтому очередь тарелок здесь же.
 */

import type { Customer } from '../customer/Customer';
import { CustomerState } from '../customer/states';
import type { DishOrder, RoomItem } from '../customer/world';

/** Грязная тарелка на столе после того, как гость поел. */
export type EmptyPlate = {
  readonly id: string;
  readonly order: DishOrder;
  readonly table: RoomItem;
  /** Официант уже идёт за ней. */
  claimed: boolean;
};

let plateSeq = 0;

export class OrderBoard {
  /** Гости, сделавшие заказ и ждущие, пока повар возьмётся. */
  private readonly pending: Customer[] = [];
  /** Приготовленные блюда, ждущие официанта. */
  private readonly ready: Customer[] = [];
  /** Грязные тарелки на столах. */
  readonly plates: EmptyPlate[] = [];

  get pendingCount(): number {
    return this.pending.length;
  }

  get readyCount(): number {
    return this.ready.length;
  }

  /** Гость сделал заказ. */
  addOrder(customer: Customer): void {
    if (!this.pending.includes(customer)) this.pending.push(customer);
  }

  /** Блюдо готово — в раздачу. */
  addReady(customer: Customer): void {
    if (!this.ready.includes(customer)) this.ready.push(customer);
  }

  /** Вернуть заказ в раздачу (официант не смог дойти). */
  returnReady(customer: Customer): void {
    this.ready.unshift(customer);
  }

  /**
   * Следующий заказ для повара. Пропускает гостей, которые уже ушли или
   * сменили состояние (ушли злыми, встали из-за стола).
   */
  takePending(isActive: (c: Customer) => boolean): Customer | null {
    while (this.pending.length > 0) {
      const c = this.pending.shift()!;
      if (isActive(c) && c.state === CustomerState.Waiting) return c;
    }
    return null;
  }

  /** Следующее готовое блюдо для официанта. */
  takeReady(isActive: (c: Customer) => boolean): Customer | null {
    while (this.ready.length > 0) {
      const c = this.ready.shift()!;
      if (
        isActive(c) &&
        (c.state === CustomerState.WaitingForFood || c.state === CustomerState.Waiting)
      ) {
        return c;
      }
    }
    return null;
  }

  /** Гость доел — на столе осталась грязная тарелка. */
  addEmptyPlate(order: DishOrder, table: RoomItem): EmptyPlate {
    plateSeq++;
    const plate: EmptyPlate = { id: `plate-${plateSeq}`, order, table, claimed: false };
    this.plates.push(plate);
    return plate;
  }

  /** Первая неразобранная тарелка (официант помечает её claimed). */
  claimPlate(): EmptyPlate | null {
    const plate = this.plates.find((p) => !p.claimed);
    if (!plate) return null;
    plate.claimed = true;
    return plate;
  }

  /** Снять пометку, если официант не дошёл. */
  releasePlate(plate: EmptyPlate): void {
    plate.claimed = false;
  }

  /** Убрать тарелку со стола. */
  removePlate(plate: EmptyPlate): void {
    const i = this.plates.indexOf(plate);
    if (i >= 0) this.plates.splice(i, 1);
  }

  /** Есть ли на столе грязная посуда (для STATE_NO_CLEAN_TABLE). */
  isTableDirty(table: RoomItem): boolean {
    return this.plates.some((p) => p.table.id === table.id);
  }

  /** Выкинуть всё (вход в дизайн-режим / ресет). */
  clear(): void {
    this.pending.length = 0;
    this.ready.length = 0;
    this.plates.length = 0;
  }

  /** Убрать конкретного гостя из всех очередей (он ушёл). */
  forget(customer: Customer): void {
    for (const q of [this.pending, this.ready]) {
      const i = q.indexOf(customer);
      if (i >= 0) q.splice(i, 1);
    }
  }
}
