/**
 * Шагание по тайловому пути с постоянной скоростью — общая часть для повара,
 * официанта и уборщика (в оригинале это был RestaurantActor.moveTo/tick).
 *
 * Скорость задаётся Balance.STEP_MS (мс на тайл) — она же у гостей, поэтому
 * все актёры двигаются в одном темпе.
 */

import type { TileCoord } from '../../grid';
import { Balance } from '../balance';

export class PathMover {
  tileX: number;
  tileY: number;

  private path: TileCoord[] = [];
  private cooldown = 0;
  /** Направление последнего шага — для разворота спрайта. */
  private dirX = 0;
  private dirY = 0;

  constructor(tileX: number, tileY: number) {
    this.tileX = tileX;
    this.tileY = tileY;
  }

  /** Идёт ли актёр прямо сейчас. */
  get moving(): boolean {
    return this.path.length > 0;
  }

  /** Путь пройден (или его не было). */
  get arrived(): boolean {
    return this.path.length === 0;
  }

  /** Направление последнего шага в тайловых координатах. */
  get direction(): { x: number; y: number } {
    return { x: this.dirX, y: this.dirY };
  }

  setPath(path: readonly TileCoord[]): void {
    this.path = path.map((p) => ({ x: p.x, y: p.y }));
    this.cooldown = this.path.length > 0 ? Balance.STEP_MS : 0;
  }

  clear(): void {
    this.path = [];
    this.cooldown = 0;
  }

  /** Телепортировать (сброс задачи). */
  teleport(tileX: number, tileY: number): void {
    this.clear();
    this.tileX = tileX;
    this.tileY = tileY;
  }

  advance(dtMs: number): void {
    if (this.path.length === 0) return;
    this.cooldown -= dtMs;
    while (this.cooldown <= 0 && this.path.length > 0) {
      const next = this.path.shift()!;
      this.dirX = next.x - this.tileX;
      this.dirY = next.y - this.tileY;
      this.tileX = next.x;
      this.tileY = next.y;
      this.cooldown = this.path.length > 0 ? this.cooldown + Balance.STEP_MS : 0;
    }
  }

  /** Дробная позиция между текущим тайлом и следующим — для плавного рендера. */
  interpolated(): { x: number; y: number } {
    const next = this.path[0];
    if (!next) return { x: this.tileX, y: this.tileY };
    const t = Math.max(0, Math.min(1, 1 - this.cooldown / Balance.STEP_MS));
    return {
      x: this.tileX + (next.x - this.tileX) * t,
      y: this.tileY + (next.y - this.tileY) * t,
    };
  }
}
