/**
 * PixiJS-сцена ресторана — ЧИСТЫЙ РЕНДЕР поверх RestaurantSim.
 *
 * Вся игровая логика (спавн по спросу, заказы, повар, официант, экономика,
 * двери) живёт в @rv/shared/engine → RestaurantSim и покрыта тестами. Сцена
 * только читает состояние симуляции, рисует его и передаёт ввод обратно:
 *
 *   play   — sim.tick(dt), рисуем гостей/персонал/эффекты;
 *   design — sim на паузе, мебель становится draggable (см. ItemLayer).
 *
 * Каждая правка расстановки валидируется WorldRestaurant, пересобирает штат
 * (sim.onLayoutChanged) и сохраняется в состояние игрока.
 */

import { engine } from '@rv/shared';
import { Application, Assets, Container, Sprite, Texture } from 'pixi.js';
import { asset } from '../asset-url';
import { AvatarBatch } from '../avatar/avatar-batch';
import { type AvatarConfig, DEFAULT_AVATAR_CONFIG } from '../avatar/avatar-config';
import { telegramState } from '../telegram';
import { ActorView, facingFromRotation } from './actor-view';
import { audio } from './audio';
import { attachCamera } from './camera';
import { ItemLayer } from './editor';
import { FacilityLayer, loadFacilityTextures } from './facility-view';
import { rotationToFrame } from './furniture-sprites';
import { type FxTextures, InteriorFx, type PlateView } from './fx';
import { DEPTH_BIAS, TILE_H, isoDepth, tileToScreen } from './iso';
import { ensureItemTextures, getFrameCount, itemTopHeight, loadItemLibrary } from './item-textures';
import { loadPlayerState, saveSim } from './player-state';
import { TrashLayer, loadTrashTextures } from './trash-view';
import { WALL_HEIGHT, type WallGap, drawBackWalls, drawGrid } from './walls';

export type SceneSnapshot = {
  /** Монеты игрока. */
  coins: number;
  /** Премиум-валюта (аналог Playfish Cash). */
  cash: number;
  /** Уровень и прогресс шкалы 0..1 (LEVEL_THRESHOLDS оригинала). */
  level: number;
  levelProgress: number;
  /** Накопленный опыт и сколько осталось до следующего уровня (null — максимум). */
  gourmetPoints: number;
  pointsToNextLevel: number | null;
  /** Спрос = популярность: задаёт частоту прихода гостей. */
  demand: number;
  maxDemand: number;
  /** Ожидаемый интервал между гостями при текущем спросе, с. */
  spawnEverySec: number;
  /** Сколько гостей в зале и сколько стульев занято. */
  customerCount: number;
  occupancy: { busy: number; total: number };
  /** Грязных тарелок на столах. */
  dirtyPlates: number;
  /** Мусора на полу — гости у входа разворачиваются тем чаще, чем его больше. */
  trash: number;
  /** Сломанных туалетов/автоматов — их чинит уборщик или сам игрок тапом. */
  brokenFacilities: number;
  /** Сколько туалетов в зале (с 8 уровня их отсутствие злит гостей). */
  toilets: number;
  /** Размер зала в клетках: растёт с уровнем (8×8 → 19×19). */
  roomSize: { width: number; height: number };
  /** Текущий штат. */
  staff: {
    chefs: number;
    waiters: number;
    cleaners: number;
    /** Запас сил самого уставшего сотрудника, 0..1. */
    energy: number;
    /** Сколько сотрудников сейчас отдыхает. */
    resting: number;
    /** Сколько выдохлось (workTime = 0) — они не работают вовсе. */
    exhausted: number;
    /** Нанято / можно нанять на текущем уровне. */
    hired: number;
    max: number;
  };
  /** Зал закрыт: нет повара или официанта с силами (isRestaurantClosed). */
  restaurantClosed: boolean;
  /** Соискатели на бирже труда. */
  candidates: engine.Candidate[];
  /** Что заработал ресторан, пока игрока не было (показываем один раз). */
  offline: engine.OfflineReport;
  /** Поимённо весь штат — для панели сотрудников. */
  roster: ReturnType<engine.RestaurantSim['staffRoster']>;
  /** Что уже стоит в зале — для вкладки «В зале» в каталоге. */
  placed: Array<{
    id: string;
    name: string;
    className: string;
    tab: engine.ShopTab;
    def: engine.ItemDefinition;
  }>;
  /** Состояние «представительного» гостя (первого активного), или null. */
  state: engine.CustomerState | null;
  stateName: string;
  emotion: engine.CustomerEmotion | null;
  timer: number;
  itemCount: number;
  designMode: boolean;
};

export type SceneHandle = {
  destroy(): void;
  resetHall(): void;
  setDesignMode(on: boolean): void;
  /** Купить предмет и поставить его на первую свободную клетку. */
  buyItem(contentId: number): Promise<{ ok: boolean; reason?: string }>;
  /** Режим продажи: тап по предмету в зале продаёт его. */
  setSellMode(on: boolean): void;
  /** Продать предмет по id (из каталога «В зале»). */
  sellItem(itemId: string): void;
  /** Отладка: выдать валюту, поставить уровень, накидать мусора. */
  debugGrant(patch: Parameters<engine.RestaurantSim['debugGrant']>[0]): void;
  /** Отправить сотрудника отдыхать или вернуть на смену. */
  setStaffResting(id: string, resting: boolean): void;
  /** Назначить сотруднику должность. */
  setEmployeeJob(id: string, job: engine.JobId): void;
  /** Нанять соискателя с биржи труда. */
  hireEmployee(candidateId: string): { ok: boolean; reason?: string };
  /** Уволить сотрудника (штраф в монетах). */
  fireEmployee(id: string): { ok: boolean; reason?: string };
  /** Купить сотруднику еду — она возвращает силы. */
  feedEmployee(id: string, perkId: number): { ok: boolean; reason?: string };
};

const SNAPSHOT_INTERVAL_MS = 100;
const AUTOSAVE_INTERVAL_MS = 10_000;

/** Слоты батча: гости + весь штат (лимит уровня — 9) с небольшим запасом. */
const AVATAR_SLOTS = engine.Balance.MAX_CONCURRENT_CUSTOMERS + 10;

/**
 * Полосы HUD, на которые камера не целится: сверху строка с монетами и
 * уровнем, снизу ряд кнопок. Значения — высота этих блоков в вёрстке (см.
 * HUD.tsx), к ним прибавляются безопасные отступы клиента Telegram.
 */
const HUD_TOP_PX = 56;
const HUD_BOTTOM_PX = 84;

/** Запас над стеной: высокие предметы у задней стены торчат выше неё. */
const TALL_ITEM_SLACK = 24;

/** Анимация двери. */
const DOOR_ANIM_MS = 200;
/** Ширина створки в открытом состоянии (уезжает в стену). */
const DOOR_OPEN_SCALE_X = 0.12;

export async function startScene(
  mountEl: HTMLDivElement,
  onSnapshot: (s: SceneSnapshot) => void,
): Promise<SceneHandle> {
  const app = new Application();
  await app.init({
    resizeTo: mountEl,
    backgroundAlpha: 0,
    antialias: true,
    resolution: window.devicePixelRatio || 1,
    autoDensity: true,
    preserveDrawingBuffer: true,
  });
  mountEl.appendChild(app.canvas);

  await loadItemLibrary();
  // Звук: контекст создаём сразу, играть он начнёт после первого жеста.
  audio.init();
  void audio.preload(['cash', 'coin-drop', 'coin-pickup', 'cooking', 'eating', 'place-item']);
  const fxTex = await loadFxTextures();
  const trashTex = await loadTrashTextures();
  const facilityTex = await loadFacilityTextures();

  // ── Симуляция ────────────────────────────────────────────────────
  const saved = loadPlayerState();
  const sim = new engine.RestaurantSim({
    layout: saved.layout,
    economy: saved.economy,
    trash: saved.trash,
    facilities: saved.facilities,
    staff: saved.staff,
    // Пока игры не было, зал работал на запасе сил персонала, а в углах
    // копился мусор — как в оригинале.
    offlineMs: Math.max(0, Date.now() - saved.savedAt),
  });
  // Офлайн-доход уже начислен в конструкторе — фиксируем его в сохранении,
  // чтобы повторное открытие не насчитало те же деньги второй раз.
  saveSim(sim);

  // Прогреваем спрайты только тех классов, что реально стоят в зале.
  await ensureItemTextures(sim.restaurant.getAllItems().map((i) => i.definition.className));

  let designMode = false;

  // ── Слои сцены (порядок = порядок отрисовки) ─────────────────────
  const stage = new Container();
  app.stage.addChild(stage);

  let backWalls = drawBackWalls(sim.restaurant.width, sim.restaurant.height, backWallGaps());
  stage.addChild(backWalls);
  let grid = drawGrid(sim.restaurant.width, sim.restaurant.height);
  stage.addChild(grid);

  /** Сортируемый слой: мебель, актёры, тарелки — всё, что перекрывает друг друга. */
  const sortLayer = new Container();
  sortLayer.sortableChildren = true;
  stage.addChild(sortLayer);

  /** Над актёрами: пузыри, дым, свечение плиты. */
  const fxLayer = new Container();
  stage.addChild(fxLayer);

  /** Поверх всего: всплывающие деньги и популярность. */
  const overlayLayer = new Container();
  stage.addChild(overlayLayer);

  const fx = new InteriorFx(fxLayer, sortLayer, overlayLayer, fxTex);
  syncStoveFx();

  // Мусор — в сортируемом слое (его перекрывают персонажи), тап убирает.
  const trashLayer = new TrashLayer(sortLayer, trashTex, (trashId) => {
    if (designMode) return;
    // Протяжка камеры, начатая с мусора, заканчивается pointertap по нему же —
    // такой «тап» не считается (см. camera.tapSuppressed).
    if (camera.tapSuppressed()) return;
    sim.cleanTrashAt(trashId);
  });

  // Сломанные туалеты/автоматы: лужа + иконка «нужен уборщик», тап чинит.
  const facilityLayer = new FacilityLayer(sortLayer, fxLayer, facilityTex, (itemId) => {
    if (designMode) return;
    if (camera.tapSuppressed()) return;
    sim.repairFacility(itemId);
  });

  // ── Предметы и дизайн-режим ──────────────────────────────────────
  const items = new ItemLayer({
    world: sim.restaurant,
    sortLayer,
    stage,
    onLayoutChanged: (changed) => {
      // SfxPlaceItem — WorldRestaurantEditor.as:57, на каждую расстановку.
      audio.play('place-item', 0.8);
      // Дверь переехала — пересобрать проёмы в стене.
      if (changed && engine.classifyItem(changed.definition) === 'door') rebuildBackWalls();
      sim.onLayoutChanged();
      syncStoveFx();
      saveSim(sim);
    },
    onSellItem: (itemId) => {
      const item = sim.restaurant.getItem(itemId);
      const res = sim.sellItem(itemId);
      if (!res.ok) return;
      items.removeItem(itemId);
      if (item && engine.classifyItem(item.definition) === 'door') rebuildBackWalls();
      syncStoveFx();
      saveSim(sim);
    },
  });
  // Подсветка клетки должна лежать под мебелью, но над полом.
  stage.setChildIndex(items.highlightGraphics, stage.getChildIndex(sortLayer));

  app.stage.eventMode = 'static';
  app.stage.hitArea = app.screen;
  items.attach(app.stage);

  // ── Аватары ──────────────────────────────────────────────────────
  const batch = new AvatarBatch(AVATAR_SLOTS);
  const avatarBaseTex = Texture.from(batch.canvas);

  /** Вид гостя по id; повара и официанты — по индексу в своих массивах. */
  const customerViews = new Map<string, ActorView>();
  const chefViews = new Map<string, ActorView>();
  const waiterViews = new Map<string, ActorView>();
  const cleanerViews = new Map<string, ActorView>();
  const idleViews = new Map<string, ActorView>();

  function viewFor(map: Map<string, ActorView>, key: string): ActorView {
    let view = map.get(key);
    if (!view) {
      view = new ActorView(batch, avatarBaseTex, sortLayer);
      map.set(key, view);
    }
    return view;
  }

  function dropView(map: Map<string, ActorView>, key: string): void {
    const view = map.get(key);
    if (!view) return;
    view.destroy();
    map.delete(key);
  }

  // ── Реакция на события симуляции ─────────────────────────────────
  const unsubscribe = sim.on((event) => {
    switch (event.type) {
      case 'customer-left': {
        dropView(customerViews, event.customer.id);
        fx.removeBubble(event.customer.id);
        if (event.happy) {
          const p = event.customer.getInterpolatedPosition();
          const s = tileToScreen(p.x, p.y);
          fx.spawnPopularity(s.x, s.y + TILE_H / 2 - 120);
        }
        break;
      }
      case 'paid': {
        const s = tileToScreen(event.tile.x, event.tile.y);
        fx.spawnMoney(s.x, s.y + TILE_H / 2 - 40, event.payment.coins);
        // SfxCash — как в clearEmptyPlate оригинала (:2976).
        audio.play('cash');
        saveSim(sim);
        break;
      }
      case 'trash-cleaned': {
        // Монеты за мусор — это оригинальная россыпь MoneyBill.
        const s = tileToScreen(event.item.tileX, event.item.tileY);
        fx.spawnCoinBurst(s.x, s.y + TILE_H / 2 - 8, event.coins);
        audio.play('coin-drop');
        saveSim(sim);
        break;
      }
      case 'facility-paid': {
        // Автомат отработал — всплывашка «+$N», как MoneyFunctional оригинала.
        const s = tileToScreen(event.item.tileX, event.item.tileY);
        fx.spawnMoney(s.x, s.y + TILE_H / 2 - 40, event.coins);
        audio.play('cash', 0.7);
        break;
      }
      case 'facility-repaired':
        audio.play('place-item', 0.8);
        saveSim(sim);
        break;
      case 'cooking-started':
        // SfxCooking — ChefActor.as:160, в момент начала готовки.
        audio.play('cooking', 0.6);
        break;
      case 'dish-served':
        // SfxEating — Customer.as:764, когда гость принимается за блюдо.
        audio.play('eating', 0.6);
        break;
      case 'level-up':
        audio.play('level-up');
        break;
      case 'room-grown':
        // Зал раздвинулся: стены стали длиннее, появились новые ряды пола.
        rebuildBackWalls();
        rebuildGrid();
        // Камера держала прежние границы — показываем зал целиком заново.
        camera.fit();
        saveSim(sim);
        break;
      case 'item-bought':
        audio.play('place-item');
        break;
      case 'item-sold':
        audio.play('cash', 0.6);
        break;
      default:
        break;
    }
  });

  // ── Двери ────────────────────────────────────────────────────────
  /** Текущая степень открытия каждой двери, 0..1 (сглаживание к состоянию sim). */
  const doorAmount = new Map<string, number>();
  /** Закрытая X-позиция спрайта двери — база для свинга вокруг петли. */
  const doorBaseX = new WeakMap<Container, number>();

  function backWallGaps(): WallGap[] {
    const gaps: WallGap[] = [];
    for (const d of sim.restaurant.getDoors()) {
      if (d.tileX === 0 && d.rotation === 0) gaps.push({ wall: 'left', index: d.tileY });
      else if (d.tileY === 0 && d.rotation === 90) gaps.push({ wall: 'right', index: d.tileX });
    }
    return gaps;
  }

  function rebuildBackWalls(): void {
    const idx = stage.getChildIndex(backWalls);
    stage.removeChild(backWalls);
    backWalls.destroy();
    backWalls = drawBackWalls(sim.restaurant.width, sim.restaurant.height, backWallGaps());
    stage.addChildAt(backWalls, idx);
  }

  function rebuildGrid(): void {
    const idx = stage.getChildIndex(grid);
    stage.removeChild(grid);
    grid.destroy();
    grid = drawGrid(sim.restaurant.width, sim.restaurant.height);
    stage.addChildAt(grid, idx);
  }

  /**
   * Створка «уезжает» сжатием по X вокруг ПЕТЛИ (крайней стороны), а не центра:
   * масштабируем и компенсируем сдвиг так, чтобы точка петли осталась на месте.
   */
  function applyDoorSprite(doorId: string, amount: number): void {
    const sprite = items.getSprite(doorId);
    if (!(sprite instanceof Sprite)) return;
    if (!doorBaseX.has(sprite)) doorBaseX.set(sprite, sprite.position.x);
    const base = doorBaseX.get(sprite)!;
    const door = sim.restaurant.getItem(doorId);
    const hingeNorm = door && door.rotation === 90 ? 0.6 : 0.4;
    const sx = 1 - amount * (1 - DOOR_OPEN_SCALE_X);
    const hingeOffset = (hingeNorm - sprite.anchor.x) * sprite.texture.width;
    sprite.scale.x = sx;
    sprite.position.x = base + hingeOffset * (1 - sx);
  }

  function updateDoors(dtMs: number): void {
    const step = dtMs / DOOR_ANIM_MS;
    for (const door of sim.restaurant.getDoors()) {
      const target = sim.isDoorOpen(door.id) ? 1 : 0;
      const current = doorAmount.get(door.id) ?? 0;
      if (current === target) continue;
      const next = Math.max(0, Math.min(1, current + Math.sign(target - current) * step));
      doorAmount.set(door.id, next);
      applyDoorSprite(door.id, next);
    }
  }

  function closeAllDoors(): void {
    for (const door of sim.restaurant.getDoors()) {
      doorAmount.set(door.id, 0);
      applyDoorSprite(door.id, 0);
    }
  }

  // ── Эффекты плиты ────────────────────────────────────────────────
  function syncStoveFx(): void {
    const stove = sim.restaurant.getKitchens()[0];
    fx.setStove(stove ? { x: stove.tileX, y: stove.tileY } : null);
  }

  // ── Камера ───────────────────────────────────────────────────────
  /**
   * Габариты зала в координатах сцены: ромб пола плюс задние стены сверху.
   * Левый угол ромба — клетка (0,H), правый — (W,0), нижний — (W,H).
   */
  function hallBounds(): { minX: number; minY: number; maxX: number; maxY: number } {
    const W = sim.restaurant.width;
    const H = sim.restaurant.height;
    return {
      minX: tileToScreen(0, H).x,
      maxX: tileToScreen(W, 0).x,
      minY: tileToScreen(0, 0).y - WALL_HEIGHT - TALL_ITEM_SLACK,
      maxY: tileToScreen(W, H).y,
    };
  }

  const camera = attachCamera({
    app,
    world: stage,
    root: app.stage,
    bounds: hallBounds,
    insets: () => {
      const safe = telegramState().safeArea;
      return { top: HUD_TOP_PX + safe.top, bottom: HUD_BOTTOM_PX + safe.bottom };
    },
  });

  // Фоновая музыка зала. Заиграет, как только игрок коснётся экрана.
  void audio.playMusic('music-restaurant');

  // ── Отрисовка кадра ──────────────────────────────────────────────

  function drawCustomers(): void {
    const seen = new Set<string>();
    for (const customer of sim.customers) {
      seen.add(customer.id);
      const pos = customer.getInterpolatedPosition();
      const idleFacing = customer.chair ? facingFromRotation(customer.chair.rotation) : null;
      viewFor(customerViews, customer.id).update(pos, animForState(customer.state), idleFacing);

      const screen = tileToScreen(pos.x, pos.y);
      fx.setBubble(
        customer.id,
        screen.x,
        screen.y + TILE_H / 2,
        isoDepth(pos.x, pos.y) + DEPTH_BIAS.plate,
        bubbleIconFor(customer),
      );
    }
    // Подчистить виды гостей, которых уже нет (страховка к событию customer-left).
    for (const id of [...customerViews.keys()]) {
      if (seen.has(id)) continue;
      dropView(customerViews, id);
      fx.removeBubble(id);
    }
  }

  function drawStaff(): void {
    for (const chef of sim.chefs) {
      const pos = chef.mover.interpolated();
      const view = viewFor(chefViews, chef.id);
      view.setLook(lookOf(chef.employee));
      // Без сил повар не готовит, а стоит в позе ANIMATION_DEAD.
      const anim = chef.workTime <= 0 ? 'dead' : chef.state === 'cooking' ? 'cooking' : 'idle';
      view.update(pos, anim, facingFromRotation(chef.facing));
    }
    for (const waiter of sim.waiters) {
      const pos = waiter.mover.interpolated();
      const view = viewFor(waiterViews, waiter.id);
      view.setLook(lookOf(waiter.employee));
      // Поднос в руках, пока несёт блюдо или убирает тарелку со стола.
      view.setProp(waiter.carrying || waiter.state === 'clearing' ? 'tray' : null);
      view.update(pos, waiter.workTime <= 0 ? 'dead' : waiterAnim(waiter), null);
    }
    for (const cleaner of sim.cleaners) {
      const pos = cleaner.mover.interpolated();
      const view = viewFor(cleanerViews, cleaner.id);
      view.setLook(lookOf(cleaner.employee));
      // Щётка с ведром — пока идёт к мусору и пока убирает.
      view.setProp(cleaner.state === 'idle' ? null : 'cleaning');
      view.update(pos, cleanerAnim(cleaner), null);
    }
    drawIdleStaff();
  }

  /**
   * Сотрудники без рабочего места: отдыхающие (в оригинале — SleepingEmployee
   * на кровати), нанятые без должности и повара без плиты (IdleEmployee).
   * Выдохшийся стоит в позе ANIMATION_DEAD прямо там, где его застало.
   */
  function drawIdleStaff(): void {
    const seen = new Set<string>();
    for (const idle of sim.idleStaff) {
      const id = idle.employee.id;
      seen.add(id);
      const view = viewFor(idleViews, id);
      view.setLook(lookOf(idle.employee));
      view.setProp(null);
      const sleeping = idle.reason === 'resting' || idle.employee.workTime <= 0;
      view.update({ x: idle.tile.x, y: idle.tile.y }, sleeping ? 'dead' : 'idle', 0);
    }
    for (const id of [...idleViews.keys()]) {
      if (!seen.has(id)) dropView(idleViews, id);
    }
  }

  /**
   * Внешность сотрудника для 3D-аватара — движок хранит её вместе с ним.
   *
   * Результат кэшируется по объекту `look`: ActorView сравнивает конфигурацию
   * по ссылке, и новый объект на каждом кадре заставлял бы батч перекрашивать
   * всю модель шестьдесят раз в секунду.
   */
  const lookCache = new WeakMap<engine.EmployeeLook, AvatarConfig>();
  function lookOf(employee: engine.Employee): AvatarConfig {
    let cfg = lookCache.get(employee.look);
    if (!cfg) {
      cfg = { ...DEFAULT_AVATAR_CONFIG, ...employee.look };
      lookCache.set(employee.look, cfg);
    }
    return cfg;
  }

  /** Тарелки: полная у того, кто ест, и грязные, которые ждут официанта. */
  /**
   * Высота столешницы над полом — тарелка кладётся на неё, а не в центр клетки
   * (порт getTileTopHeight). Считается по метаданным спрайта того кадра,
   * которым стол сейчас нарисован.
   */
  function tableLift(tableId: string): number {
    const item = sim.restaurant.getItem(tableId);
    if (!item) return 0;
    const className = item.definition.className;
    const frame = rotationToFrame(item.rotation, getFrameCount(className));
    return itemTopHeight(className, frame, item.definition.sizeY);
  }

  function drawPlates(): void {
    const views: PlateView[] = [];
    for (const customer of sim.customers) {
      if (customer.state !== engine.CustomerState.Eating || !customer.chair) continue;
      const table = sim.getTableForChair(customer.chair);
      if (!table) continue;
      views.push({
        key: `eat-${customer.id}`,
        tileX: table.tileX,
        tileY: table.tileY,
        dirty: false,
        lift: tableLift(table.id),
      });
    }
    for (const plate of sim.orders.plates) {
      views.push({
        key: plate.id,
        tileX: plate.table.tileX,
        tileY: plate.table.tileY,
        dirty: true,
        lift: tableLift(plate.table.id),
      });
    }
    fx.syncPlates(views);
  }

  function clearHallVisuals(): void {
    for (const id of [...customerViews.keys()]) dropView(customerViews, id);
    for (const id of [...chefViews.keys()]) dropView(chefViews, id);
    for (const id of [...waiterViews.keys()]) dropView(waiterViews, id);
    for (const id of [...cleanerViews.keys()]) dropView(cleanerViews, id);
    for (const id of [...idleViews.keys()]) dropView(idleViews, id);
    facilityLayer.clear();
    fx.clear();
    closeAllDoors();
  }

  // ── Tick ─────────────────────────────────────────────────────────
  let snapshotTimer = 0;
  let autosaveTimer = AUTOSAVE_INTERVAL_MS;

  const tickFn = (ticker: { deltaMS: number }): void => {
    const dtMs = ticker.deltaMS;

    if (!designMode) {
      sim.tick(dtMs);

      drawCustomers();
      drawStaff();
      drawPlates();
      trashLayer.sync(sim.trash.items);
      facilityLayer.sync(sim.brokenFacilities());
      facilityLayer.update(dtMs);

      const cooking = sim.chefs.some((c) => c.state === 'cooking');
      fx.update(dtMs, cooking);
      updateDoors(dtMs);

      // Один проход рендера всех 3D-аватаров → обновляем общий источник текстуры.
      if (batch.ready) {
        batch.update(dtMs / 1000);
        avatarBaseTex.source.update();
      }

      autosaveTimer -= dtMs;
      if (autosaveTimer <= 0) {
        autosaveTimer = AUTOSAVE_INTERVAL_MS;
        saveSim(sim);
      }
    }

    snapshotTimer -= dtMs;
    if (snapshotTimer <= 0) {
      snapshotTimer = SNAPSHOT_INTERVAL_MS;
      onSnapshot(makeSnapshot());
    }
  };
  app.ticker.add(tickFn);

  // Dev-хук: симуляция под рукой в консоли браузера (window.__rv.sim).
  if (import.meta.env.DEV) {
    (window as unknown as { __rv?: unknown }).__rv = { sim, app, items, batch, audio };
  }

  /**
   * Куда поставить только что купленный предмет. Настенные ищем по стенам с
   * подходящим поворотом, остальные — по любой валидной клетке; дальше игрок
   * перетащит их куда захочет.
   */
  function findFreeSpot(
    def: engine.ItemDefinition,
  ): { x: number; y: number; rotation: engine.Rotation } | null {
    const W = sim.restaurant.width;
    const H = sim.restaurant.height;
    const wall = engine.isWallCategory(engine.classifyItem(def));
    const rotations: engine.Rotation[] = wall ? [0, 90, 180, 270] : [0];
    // Обычную мебель ставим ближе к центру зала (там её видно и удобно тащить),
    // настенную — по стенам: перебираем клетки по удалённости от центра.
    const cx = (W - 1) / 2;
    const cy = (H - 1) / 2;
    const tiles: { x: number; y: number }[] = [];
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) tiles.push({ x, y });
    tiles.sort((a, b) => Math.hypot(a.x - cx, a.y - cy) - Math.hypot(b.x - cx, b.y - cy));
    for (const rotation of rotations) {
      for (const t of tiles) {
        if (sim.restaurant.isValidPlacement(def, t.x, t.y, rotation)) {
          return { x: t.x, y: t.y, rotation };
        }
      }
    }
    return null;
  }

  /** Силы самого уставшего работающего сотрудника — по нему и встанет смена. */
  function staffEnergy(): number {
    const working = sim.roster.list.filter((e) => engine.isWorkingJob(e.job));
    if (working.length === 0) return 0;
    return Math.min(...working.map((e) => engine.energyOf(e.workTime)));
  }

  /**
   * Расставленные предметы для каталога. Пересчитываем только в дизайн-режиме:
   * в игре список никому не нужен, а перебирать его каждый снимок незачем.
   */
  function placedItems(): SceneSnapshot['placed'] {
    if (!designMode) return [];
    const result: SceneSnapshot['placed'] = [];
    for (const item of sim.restaurant.getAllItems()) {
      const tab = engine.shopTabFor(item.definition);
      if (!tab) continue;
      result.push({
        id: item.id,
        name: item.definition.name,
        className: item.definition.className,
        tab,
        def: item.definition,
      });
    }
    return result;
  }

  function makeSnapshot(): SceneSnapshot {
    const rep = sim.customers[0] ?? null;
    return {
      coins: Math.round(sim.economy.coins),
      cash: Math.round(sim.economy.cash),
      level: sim.economy.level,
      levelProgress: sim.economy.levelProgress,
      gourmetPoints: sim.economy.gourmetPoints,
      pointsToNextLevel: sim.economy.pointsToNextLevel,
      roster: sim.staffRoster(),
      placed: placedItems(),
      demand: Math.round(sim.economy.demandPoints),
      maxDemand: sim.economy.maxDemand,
      spawnEverySec: Math.round(sim.economy.nextCustomerDelayMs() / 100) / 10,
      customerCount: sim.customers.length,
      occupancy: sim.occupancy(),
      dirtyPlates: sim.orders.plates.length,
      trash: sim.trashCount,
      brokenFacilities: sim.brokenFacilities().length,
      toilets: sim.restaurant.getToilets().length,
      roomSize: { width: sim.restaurant.width, height: sim.restaurant.height },
      staff: {
        chefs: sim.chefs.length,
        waiters: sim.waiters.length,
        cleaners: sim.cleaners.length,
        /** Доля сил самого уставшего из смены — им ограничен офлайн-доход. */
        energy: staffEnergy(),
        resting: sim.roster.byJob(engine.Job.Rest).length,
        exhausted: sim.roster.list.filter((e) => e.workTime <= 0).length,
        hired: sim.roster.size,
        max: sim.maxEmployees,
      },
      restaurantClosed: sim.restaurantClosed,
      candidates: sim.candidates(),
      offline: sim.offline,
      state: rep ? rep.state : null,
      stateName: rep ? (engine.CustomerState[rep.state] ?? String(rep.state)) : '—',
      emotion: rep ? rep.currentEmotion : null,
      timer: rep ? rep.currentTimer : 0,
      itemCount: sim.restaurant.getAllItems().length,
      designMode,
    };
  }

  function setDesignMode(on: boolean): void {
    if (designMode === on) return;
    designMode = on;
    items.setDesignMode(on);
    trashLayer.setInteractive(!on);
    // MusicEditor в дизайне, MusicRestaurant в игре — как в оригинале.
    void audio.playMusic(on ? 'music-editor' : 'music-restaurant');
    facilityLayer.setInteractive(!on);
    if (on) {
      sim.setRunning(false);
      clearHallVisuals();
      // Перестановка мебели начинается с общего плана: показываем зал целиком,
      // даже если игрок до этого приблизил угол.
      camera.fit();
      saveSim(sim);
    } else {
      rebuildBackWalls();
      sim.setRunning(true);
    }
  }

  const canvasRef = app.canvas;
  let destroyed = false;

  return {
    destroy(): void {
      if (destroyed) return;
      destroyed = true;
      saveSim(sim);
      audio.stopMusic();
      try {
        unsubscribe();
        app.ticker.remove(tickFn);
        camera.destroy();
        items.detach(app.stage);
        batch.dispose();
        app.destroy(true, { children: true, texture: true });
      } catch {
        // PixiJS может ругаться при повторном destroy.
      }
      if (canvasRef && mountEl.contains(canvasRef)) mountEl.removeChild(canvasRef);
    },
    resetHall(): void {
      if (destroyed) return;
      sim.clearHall();
      clearHallVisuals();
    },
    async buyItem(contentId: number): Promise<{ ok: boolean; reason?: string }> {
      if (destroyed) return { ok: false, reason: 'destroyed' };
      const def = engine.lookupById(contentId);
      if (!def) return { ok: false, reason: 'unknown' };

      // Спрайт может быть ещё не скачан — дотягиваем до постановки.
      await ensureItemTextures([def.className]);

      const spot = findFreeSpot(def);
      if (!spot) return { ok: false, reason: 'no-space' };

      const res = sim.buyItem(contentId, spot.x, spot.y, spot.rotation);
      if (!res.ok) return { ok: false, reason: res.reason };

      items.addItem(res.item);
      if (engine.classifyItem(def) === 'door') rebuildBackWalls();
      syncStoveFx();
      saveSim(sim);
      return { ok: true };
    },
    setSellMode(on: boolean): void {
      items.setSellMode(on);
    },
    debugGrant(patch): void {
      if (destroyed) return;
      sim.debugGrant(patch);
      saveSim(sim);
    },
    sellItem(itemId: string): void {
      if (destroyed) return;
      const item = sim.restaurant.getItem(itemId);
      if (!sim.sellItem(itemId).ok) return;
      items.removeItem(itemId);
      if (item && engine.classifyItem(item.definition) === 'door') rebuildBackWalls();
      syncStoveFx();
      audio.play('cash', 0.6);
      saveSim(sim);
    },
    setStaffResting(id: string, resting: boolean): void {
      if (destroyed) return;
      if (sim.setStaffResting(id, resting)) saveSim(sim);
    },
    setEmployeeJob(id: string, job: engine.JobId): void {
      if (destroyed) return;
      if (sim.setEmployeeJob(id, job)) saveSim(sim);
    },
    hireEmployee(candidateId: string): { ok: boolean; reason?: string } {
      if (destroyed) return { ok: false, reason: 'destroyed' };
      const res = sim.hireEmployee(candidateId);
      if (!res.ok) return res;
      audio.play('cash', 0.5);
      saveSim(sim);
      return { ok: true };
    },
    fireEmployee(id: string): { ok: boolean; reason?: string } {
      if (destroyed) return { ok: false, reason: 'destroyed' };
      const res = sim.fireEmployee(id);
      if (!res.ok) return res;
      saveSim(sim);
      return { ok: true };
    },
    feedEmployee(id: string, perkId: number): { ok: boolean; reason?: string } {
      if (destroyed) return { ok: false, reason: 'destroyed' };
      const res = sim.feedEmployee(id, perkId);
      if (!res.ok) return res;
      audio.play('cash', 0.6);
      saveSim(sim);
      return { ok: true };
    },
    setDesignMode,
  };
}

// ──────────────────────────────────────────────────────────────────────────
// Соответствия «состояние симуляции → визуал»
// ──────────────────────────────────────────────────────────────────────────

/** Состояние FSM гостя → ключ анимации аватара. */
function animForState(state: engine.CustomerState): string {
  const S = engine.CustomerState;
  switch (state) {
    case S.Walking:
    case S.WalkingToEntrance:
    case S.WalkingToToilet:
    case S.WalkingToSink:
    case S.Leaving:
      return 'walk';
    case S.Eating:
      return 'eat';
    case S.Waiting:
    case S.WaitingForFood:
    case S.Deciding:
    case S.NoTable:
    case S.NoCleanTable:
    case S.OnToilet:
      return 'sit';
    default:
      return 'idle';
  }
}

function waiterAnim(waiter: engine.WaiterActor): string {
  switch (waiter.state) {
    case 'toCustomer':
      return 'waiterWalk'; // несёт поднос
    case 'pickup':
    case 'clearing':
      return 'cooking'; // «работает» руками
    case 'toKitchen':
    case 'toPlate':
    case 'back':
      return 'walk';
    default:
      return 'idle';
  }
}

function cleanerAnim(cleaner: engine.CleanerActor): string {
  switch (cleaner.state) {
    case 'walking':
      return 'walk';
    case 'cleaning':
      return 'cooking'; // «работает» руками — отдельной анимации уборки в наборе нет
    default:
      return 'idle';
  }
}

let fxTexturesCache: FxTextures | null = null;

/** FX-ассеты интерьера (game_asset.swf): пузырь, эмоции, популярность, тарелка, монета. */
async function loadFxTextures(): Promise<FxTextures> {
  if (fxTexturesCache) return fxTexturesCache;
  const emoUrls = Array.from({ length: 8 }, (_, i) => asset(`fx/emo${i}.png`));
  const coinUrls = Array.from({ length: 15 }, (_, i) => asset(`coins/c${i + 1}.png`));
  const bubbleUrl = asset('fx/bubble.png');
  const popularityUrl = asset('fx/popularity.png');
  const plateUrl = asset('fx/plate.png');
  const urls = [...emoUrls, ...coinUrls, bubbleUrl, popularityUrl, plateUrl];
  const assets = (await Assets.load(urls)) as Record<string, Texture>;
  fxTexturesCache = {
    bubble: assets[bubbleUrl]!,
    plate: assets[plateUrl]!,
    popularity: assets[popularityUrl]!,
    coin: assets[coinUrls[0] as string]!,
    coinFrames: coinUrls.map((u) => assets[u]!),
    emotions: emoUrls.map((u) => assets[u]!),
  };
  return fxTexturesCache;
}

/** Иконка пузыря: эмоция, если есть, иначе «жду еду». null — пузыря нет. */
function bubbleIconFor(customer: engine.Customer): Texture | null {
  const tex = fxTexturesCache;
  if (!tex) return null;
  const emotion = customer.currentEmotion;
  if (emotion !== engine.CustomerEmotion.None) return tex.emotions[emotion] ?? null;
  const s = customer.state;
  if (
    s === engine.CustomerState.Deciding ||
    s === engine.CustomerState.Waiting ||
    s === engine.CustomerState.WaitingForFood
  ) {
    return tex.plate;
  }
  return null;
}
