/**
 * Стартовый layout 8×8 — копия DEFAULT_RESTAURANT_ITEMS из оригинала.
 *
 * Это начальная расстановка, которую игрок видит при первом входе в игру.
 * Дальше он покупает мебель и переставляет её сам. Сохраняем тот же контент,
 * чтобы UX был узнаваемо «как было».
 *
 * Координаты и ротации идентичны оригиналу:
 *   - 3 стула вдоль (2,3), (2,5), (5,5)
 *   - 3 стола за ними (3,3), (3,5), (6,5)
 *   - дверь по западному краю (0,4)
 *   - плита (6,2) повёрнута на 270°
 *   - два окна в стене (0,2), (0,6)
 *   - два кусочка обоев у углов
 *   - три декоративных куста по углам
 *   - бонусные плашки (Achievement, Menu Holder, Letter Box)
 */

import type { EntranceInfo, RestaurantLayout, Rotation } from './types';

type DefaultEntry = {
  contentId: number;
  tileX: number;
  tileY: number;
  rotation: Rotation;
};

const ENTRIES: DefaultEntry[] = [
  // Кухня
  { contentId: 3070000, tileX: 6, tileY: 2, rotation: 270 }, // Stove

  // Дверь
  { contentId: 3010000, tileX: 0, tileY: 4, rotation: 0 }, // Simple Door

  // Окна
  { contentId: 3000011, tileX: 0, tileY: 2, rotation: 0 }, // Basic Window
  { contentId: 3000011, tileX: 0, tileY: 6, rotation: 0 },

  // Столы
  { contentId: 3030010, tileX: 3, tileY: 3, rotation: 0 }, // White Cloth Table
  { contentId: 3030010, tileX: 3, tileY: 5, rotation: 0 },
  { contentId: 3030010, tileX: 6, tileY: 5, rotation: 0 },

  // Стулья (смотрят вправо/+x на столы)
  { contentId: 3040001, tileX: 2, tileY: 3, rotation: 0 }, // Classic Chair
  { contentId: 3040001, tileX: 2, tileY: 5, rotation: 0 },
  { contentId: 3040001, tileX: 5, tileY: 5, rotation: 0 },

  // Обои на двух задних стенах: (0,1) — стена tx=0 (rotation 0, смотрит SE),
  // (1,0) — стена ty=0 (rotation 90, смотрит SW). Так панели «прислонены» к своим стенам.
  { contentId: 3060016, tileX: 0, tileY: 1, rotation: 0 }, // Neutral Blue, NW-стена
  { contentId: 3060016, tileX: 1, tileY: 0, rotation: 90 }, // Neutral Blue, NE-стена

  // Awards / служебные UI-объекты — оставляем для функциональной полноты, хоть
  // в визуальном демо они просто рендерятся как небольшие иконки.
  { contentId: 3200000, tileX: 2, tileY: 0, rotation: 90 }, // Achievement Panel
  { contentId: 3300000, tileX: 1, tileY: 7, rotation: 0 }, // Letter Box
  { contentId: 3100000, tileX: 4, tileY: 0, rotation: 90 }, // Menu Holder

  // Санузел. ОТСТУПЛЕНИЕ ОТ ОРИГИНАЛА: в DEFAULT_RESTAURANT_ITEMS их не было,
  // игрок покупал туалет и раковину в магазине. Магазина у нас пока нет (R5),
  // а без них не работает целая ветка FSM (гости ходят в туалет с 8 уровня и
  // злятся, если его нет). Убрать отсюда, когда появится покупка предметов.
  { contentId: 3500017, tileX: 7, tileY: 3, rotation: 270 }, // Toilet01
  { contentId: 3020053, tileX: 7, tileY: 4, rotation: 270 }, // WhiteSink

  // Декор
  { contentId: 3020003, tileX: 1, tileY: 1, rotation: 0 }, // DelicateBush
  { contentId: 3020003, tileX: 7, tileY: 1, rotation: 0 },
  { contentId: 3020003, tileX: 7, tileY: 7, rotation: 0 },
];

export const defaultLayout: RestaurantLayout = {
  width: 8,
  height: 8,
  items: ENTRIES,
};

/**
 * Вход. Customer спавнится сразу за дверью (на тайле двери) и уходит туда же.
 * inside — следующий тайл внутрь, куда он направится после появления.
 */
export const defaultEntrance: EntranceInfo = {
  doorTile: { x: 0, y: 4 },
  insideTile: { x: 1, y: 4 },
};
