/**
 * Конфигурация экстерьера здания игрока + персистентность (localStorage).
 * Используется сценой улицы и редактором экстерьера.
 */

export type RoofKind =
  | 'good'
  | 'cupcake'
  | 'saloon'
  | 'spooky'
  | 'egyptian'
  | 'nest'
  | 'classic'
  | 'modern';

export const ROOF_KINDS: RoofKind[] = [
  'good',
  'cupcake',
  'saloon',
  'spooky',
  'egyptian',
  'nest',
  'classic',
  'modern',
];

export const ROOF_LABELS: Record<RoofKind, string> = {
  good: 'Кирпич',
  cupcake: 'Кекс',
  saloon: 'Салун',
  spooky: 'Жуть',
  egyptian: 'Египет',
  nest: 'Гнездо',
  classic: 'Классик',
  modern: 'Модерн',
};

export type FacadeConfig = {
  roof: RoofKind;
  bodyColor: number;
  accentColor: number;
  name: string;
};

export const DEFAULT_FACADE: FacadeConfig = {
  roof: 'good',
  bodyColor: 0xf3ead6,
  accentColor: 0x2f9ac8,
  name: 'Твой ресторан',
};

/** Палитры для редактора. */
export const BODY_SWATCHES = [0xf3ead6, 0xfbe8d3, 0xe8efe0, 0xe6e1f0, 0xfdeaea, 0xe2eff5, 0xfff6d6];
export const ACCENT_SWATCHES = [
  0x2f9ac8, 0xe07a5f, 0x81b29a, 0xc77dff, 0xf0a202, 0xe84855, 0x3a4250, 0x2c8c5a,
];

const STORAGE_KEY = 'rv:facade:v1';

export function loadFacadeConfig(): FacadeConfig {
  if (typeof window === 'undefined') return DEFAULT_FACADE;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw) return { ...DEFAULT_FACADE, ...(JSON.parse(raw) as Partial<FacadeConfig>) };
  } catch {
    /* ignore */
  }
  return DEFAULT_FACADE;
}

export function saveFacadeConfig(cfg: FacadeConfig): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(cfg));
  } catch {
    /* ignore */
  }
}
