/**
 * Customer FSM — порт com/playfish/games/cooking/actors/Customer.as.
 *
 * Дизайн отличий от оригинала:
 *
 * 1. Полная декомпозиция от рендера. В оригинале tick() переключал анимации,
 *    эмоции и звуки прямо тут же. Здесь — только мутации стейта; визуальные
 *    эффекты эмиттятся как события (CustomerEvent), и подписчик (PixiJS-сцена
 *    или Colyseus-syncer) их применяет.
 *
 * 2. CustomerWorld — единственный канал в окружение. Тестируется на стабах
 *    без всего ресторана.
 *
 * 3. Состояние посетителя описано полями класса. Сериализация — простой
 *    snapshot() для Colyseus state + восстановление через restore().
 *
 * 4. Сохранена логическая структура switch-блока из оригинала: каждое
 *    состояние получает свой handle*-метод. Имена соответствуют комментариям
 *    AS3-исходника.
 *
 * Не портированы пока (TODO):
 *   - addInviteFriendBadge / addPlayingFriendBadge (UI-only)
 *   - звуки eating, открытие дверей (events)
 *   - анимации Avatar3D (события setAnimation)
 *   - расчёт PEDESTRIAN-режима (отдельный спавн pedestrian'ов)
 */

import type { TileCoord } from '../grid';
import { Balance } from '../restaurant/balance';
import { CustomerEmotion, CustomerState, CustomerTiming, isTimerExtendable } from './states';
import type {
  CustomerEvent,
  CustomerEventListener,
  CustomerWorld,
  DishOrder,
  RoomItem,
} from './world';

/** Бонусы карме (DEMAND_BONUS_*). */
const DEMAND_BONUS_HAPPY = 2;
const DEMAND_BONUS_UNHAPPY = -1;

/** Параметры конструктора. */
export type CustomerInit = {
  id: string;
  /** Позиция спавна — обычно тайл прямо за входной дверью. */
  spawnTile: TileCoord;
  /** Дверь, через которую посетитель войдёт и уйдёт. null — без двери (visit-режим). */
  door?: RoomItem | null;
  /** Внутренняя клетка у двери — куда гость приходит и откуда ищет стул (= insideTile). */
  entranceTile: TileCoord;
  /** Клетка самой двери на стене (гость проходит сквозь неё). Опц. — иначе legacy-вход. */
  doorTile?: TileCoord | null;
  /** Клетка снаружи (off-grid) — спавн и финальный уход. Опц. — иначе legacy-вход. */
  outsideTile?: TileCoord | null;
  /** Желаемый заказ (создаётся снаружи — в createOrderForCustomer оригинала). */
  order: DishOrder;
  /** Мир. */
  world: CustomerWorld;
};

export class Customer {
  readonly id: string;

  // Позиция (тайловые координаты целевой клетки; обновляется при движении).
  tileX: number;
  tileY: number;

  // Целевой путь — массив тайлов от текущего до цели; пустой = стоит.
  private movePath: TileCoord[] = [];
  // Сколько мс осталось до следующего шага по path (упрощение, в оригинале — пиксельная скорость).
  private stepCooldownMs = 0;

  // Текущее состояние и таймер.
  state: CustomerState = CustomerState.Initial;
  private timer = 0;
  private emotion: CustomerEmotion = CustomerEmotion.None;

  // Объекты, ассоциированные с фсм.
  chair: RoomItem | null = null;
  sinkItem: RoomItem | null = null;
  interactiveItem: RoomItem | null = null;
  door: RoomItem | null;
  order: DishOrder | null;
  /**
   * Заказ, который гость только что доел. Тарелка от него остаётся на столе,
   * пока её не уберёт официант — это и есть момент оплаты (см. OrderBoard).
   */
  finishedOrder: DishOrder | null = null;

  /**
   * Чем закончился визит: true — ушёл довольным, false — недовольным,
   * null — ещё не ушёл.
   *
   * Отдельное поле, а не эмоция: при переходе в Left эмоция гасится (иконка над
   * головой должна исчезнуть), поэтому судить по ней об исходе нельзя — так и
   * получалось, что «палец вверх» всплывал даже над сбежавшими гостями.
   */
  leftHappy: boolean | null = null;
  /** Почему ушёл недовольным (wait-too-long, trash, no-seat…). */
  leaveReason: string | null = null;

  readonly entranceTile: TileCoord;
  /** Клетка двери и клетка снаружи (для входа/выхода сквозь дверь). null = legacy. */
  private readonly doorTile: TileCoord | null;
  private readonly outsideTile: TileCoord | null;
  private readonly world: CustomerWorld;
  private readonly listeners = new Set<CustomerEventListener>();

  /**
   * Время прохождения одного тайла пути (мс/тайл) = скорость ходьбы.
   *
   * Откалибровано под оригинал. В RestaurantActor.as актёр двигался с
   * moveSpeedX=0.06, moveSpeedY=0.03 px/мс; шаг на соседний тайл = смещение
   * экрана (±40, ±20) px (полтайла при TILE_W=80/TILE_H=40), то есть
   * 40/0.06 = 20/0.03 ≈ 667 мс на тайл. Это «неспешный» темп оригинала.
   * Уменьшить число — ходит быстрее, увеличить — медленнее.
   */
  private static readonly STEP_MS = Balance.STEP_MS;

  constructor(init: CustomerInit) {
    this.id = init.id;
    this.tileX = init.spawnTile.x;
    this.tileY = init.spawnTile.y;
    this.door = init.door ?? null;
    this.entranceTile = init.entranceTile;
    this.doorTile = init.doorTile ?? null;
    this.outsideTile = init.outsideTile ?? null;
    this.order = init.order;
    this.world = init.world;
  }

  // ─────────────────────────────────────────────────────────────────────
  // Публичный API
  // ─────────────────────────────────────────────────────────────────────

  on(listener: CustomerEventListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /** Запустить посетителя: пошёл от двери ко входу. Один раз после создания. */
  enter(): void {
    this.emit({ type: 'enter', customerId: this.id });
    this.transition(CustomerState.WalkingToEntrance);
    if (this.outsideTile) {
      // Через дверь: tileX/Y уже на outsideTile (spawn) → дверь → внутрь.
      const path: TileCoord[] = [];
      if (this.doorTile) path.push(this.doorTile);
      path.push(this.entranceTile);
      this.setMovePath(path);
    } else {
      // Legacy: путь — предтайл за краем + вход.
      const entranceLeadIn =
        this.entranceTile.y === 0
          ? { x: this.entranceTile.x, y: -1 }
          : { x: -1, y: this.entranceTile.y };
      this.setMovePath([entranceLeadIn, this.entranceTile]);
    }
  }

  /**
   * Главный тик. dtMs — миллисекунды с прошлого тика.
   * Возвращает true, пока посетитель «жив» (state !== Left).
   */
  tick(dtMs: number): boolean {
    if (this.state === CustomerState.Left) return false;

    // Шаги по пути идут параллельно state-логике (как в оригинале).
    this.advanceAlongPath(dtMs);

    switch (this.state) {
      case CustomerState.WalkingToEntrance:
        this.handleWalkingToEntrance();
        break;
      case CustomerState.WaitingToSit:
        this.handleWaitingToSit();
        break;
      case CustomerState.TooMuchTrash:
        this.handleTooMuchTrash();
        break;
      case CustomerState.RestaurantClosed:
        if (this.timer <= 0) this.leave();
        break;
      case CustomerState.NoTable:
        this.handleNoTable();
        break;
      case CustomerState.NoCleanTable:
        this.handleNoCleanTable();
        break;
      case CustomerState.Walking:
        this.handleWalking();
        break;
      case CustomerState.PlayingInteractiveItem:
        this.handlePlayingInteractiveItem();
        break;
      case CustomerState.Deciding:
        this.handleDeciding();
        break;
      case CustomerState.Waiting:
      case CustomerState.WaitingForFood:
        this.handleWaitingForFood();
        break;
      case CustomerState.Eating:
        this.handleEating();
        break;
      case CustomerState.Paying:
        this.handlePaying();
        break;
      case CustomerState.Leaving:
        this.handleLeaving();
        break;
      case CustomerState.Angry:
        if (this.timer <= 0) this.leaveUnhappy('angry');
        break;
      case CustomerState.WalkingToToilet:
        this.handleWalkingToToilet();
        break;
      case CustomerState.OnToilet:
        this.handleOnToilet();
        break;
      case CustomerState.WalkingToSink:
        this.handleWalkingToSink();
        break;
      case CustomerState.UsingSink:
        if (this.timer <= 0) this.leaveHappy();
        break;
      default:
        break;
    }

    if (this.timer > 0) this.timer -= dtMs;
    // Каст нужен: TS не отслеживает мутацию this.state через handle* / transition.
    return (this.state as CustomerState) !== CustomerState.Left;
  }

  /**
   * Внешний вызов: повар принял заказ в готовку. Waiting → WaitingForFood.
   * Соответствует Customer.waitForFood() в оригинале (таймер ожидания блюда).
   */
  waitForFood(): void {
    if (this.state !== CustomerState.Waiting) return;
    this.timer = CustomerTiming.WaitingForFood + this.world.customerWaitTimeModifier;
    this.transition(CustomerState.WaitingForFood);
  }

  /**
   * Внешний вызов: повар прислал готовое блюдо. Соответствует Customer.eatOrder() в оригинале.
   */
  eatOrder(): void {
    if (this.state !== CustomerState.Waiting && this.state !== CustomerState.WaitingForFood) {
      return; // защита от двойного сервиса
    }
    this.timer = CustomerTiming.Eating;
    this.transition(CustomerState.Eating);
    if (this.order) {
      this.emit({ type: 'eating', customerId: this.id, orderId: this.order.id });
    }
  }

  // ─────────────────────────────────────────────────────────────────────
  // Обработчики состояний (порядок и логика повторяют tick() оригинала).
  // ─────────────────────────────────────────────────────────────────────

  private handleWalkingToEntrance(): void {
    if (!this.reachedPathEnd()) return;
    if (this.world.restaurantClosed) {
      this.onRestaurantClosed();
      return;
    }
    // Грязный зал отпугивает: чем больше мусора, тем выше шанс развернуться
    // (порт Customer.as:315 — rnd(0,20) < trashCount).
    const trash = this.world.trashCount;
    if (trash > 0 && this.world.rand(0, Balance.TRASH_TURN_AWAY_ROLL) < trash) {
      this.onTooMuchTrash();
      return;
    }
    if (!this.checkForFreeSeatOrInteractive(/*requireClean*/ true)) {
      this.onNoSeat();
    }
  }

  /** Развернулся из-за грязи: потоптался у входа и ушёл недовольным. */
  private onTooMuchTrash(): void {
    this.timer = Balance.TRASH_LEAVE_DELAY_MS;
    this.transition(CustomerState.TooMuchTrash);
  }

  private handleWaitingToSit(): void {
    if (this.timer <= 0) {
      this.leaveUnhappy('no-seat');
      return;
    }
    if (this.reachedPathEnd() && this.emotion === CustomerEmotion.None) {
      // Пытаемся ещё раз найти место.
      if (!this.checkForFreeSeatOrInteractive(true)) {
        this.setEmotion(CustomerEmotion.NoSeat);
      }
    }
  }

  private handleTooMuchTrash(): void {
    if (this.timer <= 0) {
      this.leaveUnhappy('trash');
      return;
    }
    if (this.reachedPathEnd() && this.emotion === CustomerEmotion.None) {
      this.setEmotion(CustomerEmotion.Dirty);
    }
  }

  private handleNoTable(): void {
    if (this.timer <= 0) {
      this.leaveUnhappy('no-table');
      return;
    }
    // В оригинале head очереди ждёт чтобы освободился стол.
    // Тут пока упрощаем: каждый тик пробуем найти.
    this.checkForFreeSeatOrInteractive(true);
  }

  private handleNoCleanTable(): void {
    if (this.timer <= 0) {
      this.leaveUnhappy('no-clean-table');
      return;
    }
    if (!this.chair) return;
    const table = this.world.getTableForChair(this.chair);
    if (table && this.world.isTableFree(table)) {
      this.setEmotion(CustomerEmotion.None);
      this.world.addOrderFromCustomer(this);
      if (this.order) {
        this.order.table = table;
        this.emit({ type: 'order-placed', customerId: this.id, orderId: this.order.id });
      }
      this.transition(CustomerState.Waiting);
      this.timer = CustomerTiming.WaitingForOrder + this.world.customerWaitTimeModifier;
    }
  }

  private handleWalking(): void {
    if (!this.reachedPathEnd()) return;
    if (this.chair) {
      this.sitOnChair(this.chair);
      this.timer = CustomerTiming.Decision;
      this.transition(CustomerState.Deciding);
      this.emit({ type: 'sit', customerId: this.id, chairId: this.chair.id });
    } else if (this.interactiveItem) {
      this.timer = CustomerTiming.InteractiveItem;
      this.transition(CustomerState.PlayingInteractiveItem);
    }
  }

  private handlePlayingInteractiveItem(): void {
    if (this.timer > 0) return;
    // Порт Customer.as:449 — автомат изнашивается и приносит ресторану монету.
    if (this.interactiveItem) {
      this.emit({
        type: 'facility-used',
        customerId: this.id,
        itemId: this.interactiveItem.id,
        kind: 'interactive',
      });
    }
    this.interactiveItem = null;
    this.leave();
  }

  private handleDeciding(): void {
    if (this.timer > 0) return;
    if (!this.chair) {
      this.leaveUnhappy('lost-chair');
      return;
    }
    const table = this.world.getTableForChair(this.chair);
    if (table == null) {
      this.setEmotion(CustomerEmotion.NoTable);
      this.timer = CustomerTiming.WaitingForTable + this.world.customerWaitTimeModifier;
      this.transition(CustomerState.NoTable);
      this.world.waitingChairQueue.push(this);
    } else if (!this.world.isTableFree(table)) {
      this.setEmotion(CustomerEmotion.NoCleanTable);
      this.timer = CustomerTiming.WaitingForOrder + this.world.customerWaitTimeModifier;
      this.transition(CustomerState.NoCleanTable);
    } else {
      this.world.addOrderFromCustomer(this);
      if (this.order) {
        this.order.table = table;
        this.emit({ type: 'order-placed', customerId: this.id, orderId: this.order.id });
      }
      this.timer = CustomerTiming.WaitingForOrder + this.world.customerWaitTimeModifier;
      this.transition(CustomerState.Waiting);
    }
  }

  private handleWaitingForFood(): void {
    if (this.timer <= 0) {
      this.setEmotion(
        this.order?.isDrink ? CustomerEmotion.WaitTooLongForDrink : CustomerEmotion.WaitTooLong,
      );
      this.leaveUnhappy('wait-too-long');
    }
  }

  private handleEating(): void {
    if (this.timer <= 0) {
      // Тарелку оставляем на столе — её уберёт официант, и в этот момент
      // ресторан получит деньги (порт clearEmptyPlate → onCustomerPay).
      this.finishedOrder = this.order;
      this.order = null;
      this.timer = CustomerTiming.Paying;
      this.transition(CustomerState.Paying);
    }
  }

  private handlePaying(): void {
    if (this.timer > 0) return;
    // Порт Customer.as:525 — с TOILET_START_LEVEL каждый четвёртый гость идёт в
    // туалет. Если туалета нет, gotoToilet сам поставит эмоцию «нет туалета» и
    // уведёт гостя недовольным: с этого уровня туалет становится обязательным.
    const wantsToilet =
      this.world.playerLevel >= Balance.TOILET_START_LEVEL &&
      this.world.rand(0, Balance.TOILET_CHANCE_ONE_IN - 1) === 0;
    if (wantsToilet) this.gotoToilet();
    else this.leaveHappy();
  }

  private handleLeaving(): void {
    if (this.reachedPathEnd()) {
      this.transition(CustomerState.Left);
      this.emotion = CustomerEmotion.None;
      this.world.removeCustomer(this);
      this.emit({ type: 'left', customerId: this.id });
    }
  }

  private handleWalkingToToilet(): void {
    if (this.reachedPathEnd() && this.chair) {
      this.sitOnChair(this.chair);
      this.transition(CustomerState.OnToilet);
      this.timer = CustomerTiming.Toilet;
    }
  }

  private handleOnToilet(): void {
    if (this.timer > 0) return;
    // Порт Customer.as:582 — использование засчитывается в момент, когда гость
    // встаёт. Туалет от этого изнашивается (breakCount), денег он не приносит.
    if (this.chair) {
      this.emit({
        type: 'facility-used',
        customerId: this.id,
        itemId: this.chair.id,
        kind: 'toilet',
      });
    }
    if (!this.gotoSink()) this.leaveHappy();
  }

  private handleWalkingToSink(): void {
    if (this.reachedPathEnd() && this.sinkItem) {
      this.transition(CustomerState.UsingSink);
      this.timer = CustomerTiming.Sink;
    }
  }

  // ─────────────────────────────────────────────────────────────────────
  // Логика поиска места и переходы
  // ─────────────────────────────────────────────────────────────────────

  private checkForFreeSeatOrInteractive(requireCleanFirst: boolean): boolean {
    // Сначала пробуем чистый стол → если ничего → грязный → если ничего → интерактив.
    const tryChairs = (clean: boolean): boolean => {
      const chairs = this.world.getEmptyChairs(clean);
      if (chairs.length === 0) return false;
      // Random pick — заметим что оригинал делал getPathToRandomRoomItem.
      const target = chairs[this.world.rand(0, chairs.length - 1)]!;
      // stopNextToDestination=false: путь заканчивается НА клетке стула (она
      // проходима как пункт назначения) — гость садится на стул, а не рядом.
      const path = this.world.findPathTo(this.tileX, this.tileY, target.tileX, target.tileY, false);
      if (!path) return false;
      this.walkToChair(target, path);
      this.setEmotion(CustomerEmotion.None);
      return true;
    };

    if (requireCleanFirst && tryChairs(true)) return true;
    if (tryChairs(false)) return true;

    const interactive = this.world.getEmptyInteractiveItems();
    if (interactive.length > 0) {
      const target = interactive[this.world.rand(0, interactive.length - 1)]!;
      const path = this.world.findPathTo(this.tileX, this.tileY, target.tileX, target.tileY, true);
      if (path) {
        this.walkToInteractiveItem(target, path);
        this.setEmotion(CustomerEmotion.None);
        return true;
      }
    }
    return false;
  }

  private walkToChair(chair: RoomItem, path: TileCoord[]): void {
    this.leaveCurrentChair();
    this.chair = chair;
    this.setMovePath(path);
    this.transition(CustomerState.Walking);
  }

  private walkToInteractiveItem(item: RoomItem, path: TileCoord[]): void {
    this.leaveCurrentChair();
    this.interactiveItem = item;
    this.setMovePath(path);
    this.transition(CustomerState.Walking);
  }

  private sitOnChair(_chair: RoomItem): void {
    // В оригинале: смена направления + анимация SIT.
    // Здесь только событие сидения уже эмиттится в handleWalking.
  }

  private leaveCurrentChair(): void {
    this.chair = null;
  }

  private gotoToilet(): boolean {
    const seats = this.world.getEmptyToiletSeats();
    if (seats.length === 0) {
      this.setEmotion(CustomerEmotion.NoToilet);
      this.leaveUnhappy('no-toilet');
      return false;
    }
    // Берём ближайший.
    seats.sort(
      (a, b) =>
        Math.abs(a.tileX - this.tileX) +
        Math.abs(a.tileY - this.tileY) -
        (Math.abs(b.tileX - this.tileX) + Math.abs(b.tileY - this.tileY)),
    );
    for (const seat of seats) {
      const path = this.world.findPathTo(this.tileX, this.tileY, seat.tileX, seat.tileY, false);
      if (path) {
        this.leaveCurrentChair();
        this.chair = seat;
        this.setMovePath(path);
        this.transition(CustomerState.WalkingToToilet);
        return true;
      }
    }
    this.setEmotion(CustomerEmotion.NoToilet);
    this.leaveUnhappy('no-toilet');
    return false;
  }

  private gotoSink(): boolean {
    const sinks = this.world.getEmptySinks();
    if (sinks.length === 0) return false;
    sinks.sort(
      (a, b) =>
        Math.abs(a.tileX - this.tileX) +
        Math.abs(a.tileY - this.tileY) -
        (Math.abs(b.tileX - this.tileX) + Math.abs(b.tileY - this.tileY)),
    );
    for (const sink of sinks) {
      const path = this.world.findPathTo(this.tileX, this.tileY, sink.tileX, sink.tileY, true);
      if (path) {
        this.leaveCurrentChair();
        this.sinkItem = sink;
        this.setMovePath(path);
        this.transition(CustomerState.WalkingToSink);
        return true;
      }
    }
    return false;
  }

  private onNoSeat(): void {
    this.timer = CustomerTiming.WaitingForChair + this.world.customerWaitTimeModifier;
    this.transition(CustomerState.WaitingToSit);
    // Идём в очередь перед входом.
    this.setMovePath([{ x: this.entranceTile.x + 1, y: this.entranceTile.y }]);
  }

  private onRestaurantClosed(): void {
    this.transition(CustomerState.RestaurantClosed);
    this.timer = CustomerTiming.ClosedLeaveDelay;
  }

  private leave(): void {
    if (this.sinkItem) {
      this.sinkItem = null;
    }
    this.leaveCurrentChair();
    const path = this.world.findPathTo(
      this.tileX,
      this.tileY,
      this.entranceTile.x,
      this.entranceTile.y,
      false,
    );
    // Путь до внутренней клетки двери, затем сквозь дверь наружу (если есть дверь).
    const exit: TileCoord[] = (path ?? [this.entranceTile]).slice();
    if (this.doorTile) exit.push(this.doorTile);
    if (this.outsideTile) exit.push(this.outsideTile);
    this.setMovePath(exit);
    this.transition(CustomerState.Leaving);
  }

  private leaveHappy(): void {
    this.leftHappy = true;
    this.world.addDemand(DEMAND_BONUS_HAPPY);
    this.emit({ type: 'leave-happy', customerId: this.id });
    this.leave();
  }

  private leaveUnhappy(reason: string): void {
    this.leftHappy = false;
    this.leaveReason = reason;
    this.world.addDemand(DEMAND_BONUS_UNHAPPY);
    this.emit({ type: 'leave-unhappy', customerId: this.id, reason });
    this.leave();
  }

  // ─────────────────────────────────────────────────────────────────────
  // Движение
  // ─────────────────────────────────────────────────────────────────────

  /**
   * Установить новый путь. tileX/Y остаются на текущей точке (откуда идём),
   * movePath[0] становится первой целью, cooldown заводится на полный сегмент —
   * это даёт рендеру STEP_MS на плавную интерполяцию между прошлой и следующей клеткой.
   */
  private setMovePath(path: ReadonlyArray<TileCoord>): void {
    this.movePath = path.slice();
    this.stepCooldownMs = path.length > 0 ? Customer.STEP_MS : 0;
  }

  private advanceAlongPath(dtMs: number): void {
    if (this.movePath.length === 0) return;
    this.stepCooldownMs -= dtMs;
    while (this.stepCooldownMs <= 0 && this.movePath.length > 0) {
      // Прибыли на следующий тайл сегмента. tileX/Y становится последним достигнутым.
      const arrived = this.movePath.shift()!;
      this.tileX = arrived.x;
      this.tileY = arrived.y;
      if (this.movePath.length > 0) {
        this.stepCooldownMs += Customer.STEP_MS; // стартуем следующий сегмент
      } else {
        this.stepCooldownMs = 0;
      }
    }
  }

  private reachedPathEnd(): boolean {
    return this.movePath.length === 0;
  }

  /**
   * Сглаженная позиция для рендера: интерполирует между tileX/Y (где находимся)
   * и movePath[0] (куда идём) по доле прошедшего времени сегмента.
   * Когда путь пуст — возвращает текущий тайл.
   */
  getInterpolatedPosition(): { x: number; y: number } {
    if (this.movePath.length === 0) {
      return { x: this.tileX, y: this.tileY };
    }
    const next = this.movePath[0]!;
    const t = Math.max(0, Math.min(1, 1 - this.stepCooldownMs / Customer.STEP_MS));
    return {
      x: this.tileX + (next.x - this.tileX) * t,
      y: this.tileY + (next.y - this.tileY) * t,
    };
  }

  // ─────────────────────────────────────────────────────────────────────
  // Эмоции, события
  // ─────────────────────────────────────────────────────────────────────

  private setEmotion(emotion: CustomerEmotion): void {
    this.emotion = emotion;
  }

  private transition(to: CustomerState): void {
    if (this.state === to) return;
    const from = this.state;
    this.state = to;
    this.emit({ type: 'state-change', customerId: this.id, from, to });
  }

  private emit(evt: CustomerEvent): void {
    for (const l of this.listeners) l(evt);
  }

  // ─────────────────────────────────────────────────────────────────────
  // Снимки состояния (для Colyseus / сохранения)
  // ─────────────────────────────────────────────────────────────────────

  snapshot(): CustomerSnapshot {
    return {
      id: this.id,
      tileX: this.tileX,
      tileY: this.tileY,
      state: this.state,
      emotion: this.emotion,
      timer: this.timer,
      stepCooldownMs: this.stepCooldownMs,
      movePath: this.movePath.map((t) => ({ x: t.x, y: t.y })),
      chairId: this.chair?.id ?? null,
      sinkId: this.sinkItem?.id ?? null,
      interactiveItemId: this.interactiveItem?.id ?? null,
      orderId: this.order?.id ?? null,
    };
  }

  // Утилитарные геттеры (для подписчиков, чтоб не лезть в приватку).
  get currentEmotion(): CustomerEmotion {
    return this.emotion;
  }
  get currentTimer(): number {
    return this.timer;
  }
  get isTimerExtendable(): boolean {
    return isTimerExtendable(this.state);
  }
}

export type CustomerSnapshot = {
  id: string;
  tileX: number;
  tileY: number;
  state: CustomerState;
  emotion: CustomerEmotion;
  timer: number;
  stepCooldownMs: number;
  movePath: { x: number; y: number }[];
  chairId: string | null;
  sinkId: string | null;
  interactiveItemId: string | null;
  orderId: string | null;
};
