export type LevelInfo = {
  /** Номер уровня (индекс в таблице; 0 — стартовый, до первого порога). */
  readonly level: number;
  /** Сколько gourmet points нужно, чтобы войти в этот уровень. */
  readonly points: number;
  readonly roomSizeX: number;
  readonly roomSizeY: number;
  /** Максимум нанятых сотрудников (повара + официанты + уборщики). */
  readonly employees: number;
  /** Сколько блюд можно держать в меню на каждую категорию. */
  readonly numDishes: number;
  readonly gardenPlots: number;
  readonly layouts: number;
  /** Разовая награда монетами при достижении уровня. */
  readonly coinReward: number;
};

function toInfo(level: number, row: LevelRow): LevelInfo {
  return {
    level,
    points: row[0],
    roomSizeX: row[1],
    roomSizeY: row[2],
    employees: row[3],
    numDishes: row[4],
    gardenPlots: row[5],
    layouts: row[6],
    coinReward: row[7],
  };
}

/** Всего уровней в таблице. */
export const MAX_LEVEL = LEVEL_ROWS.length - 1;

/** Уровень по накопленным gourmet points (порт GameWorld.getLevel). */
export function getLevel(points: number): number {
  for (let i = LEVEL_ROWS.length - 1; i >= 0; i--) {
    if (points >= LEVEL_ROWS[i]![0]) return i;
  }
  return 0;
}

/** Параметры уровня. Значения вне таблицы зажимаются к границам. */
export function getLevelInfo(level: number): LevelInfo {
  const i = Math.max(0, Math.min(MAX_LEVEL, Math.floor(level)));
  return toInfo(i, LEVEL_ROWS[i]!);
}

/**
 * Размер зала на уровне — порт `LEVEL_THRESHOLDS[level].roomSizeX/Y`
 * (WorldRestaurant.init :481, onLevelUp :922). От 8×8 на старте до 19×19 к
 * 32 уровню; дальше не растёт.
 */
export function roomSizeForLevel(level: number): [width: number, height: number] {
  const info = getLevelInfo(level);
  return [info.roomSizeX, info.roomSizeY];
}

/** Порог следующего уровня, или null если уровень последний. */
export function nextLevelPoints(level: number): number | null {
  const next = Math.floor(level) + 1;
  if (next > MAX_LEVEL) return null;
  return LEVEL_ROWS[next]![0];
}

/**
 * На каком уровне откроется следующий слот сотрудника, или null — если лимит
 * уже максимальный. Нужен панели персонала, чтобы объяснить закрытый слот.
 */
export function nextEmployeeSlotLevel(level: number): number | null {
  const current = getLevelInfo(level).employees;
  for (let i = Math.max(0, Math.floor(level)) + 1; i <= MAX_LEVEL; i++) {
    if (LEVEL_ROWS[i]![3] > current) return i;
  }
  return null;
}

/** Прогресс внутри текущего уровня, 0..1 (для шкалы уровня в UI). */
export function levelProgress(points: number): number {
  const level = getLevel(points);
  const from = getLevelInfo(level).points;
  const to = nextLevelPoints(level);
  if (to === null || to <= from) return 1;
  return Math.max(0, Math.min(1, (points - from) / (to - from)));
}
