/**
 * Звук — оригинальные MP3 из sound_asset.swf.
 *
 * В оригинале был класс GameSound с двумя типами: TYPE_SOUND (короткие эффекты)
 * и музыка, которую можно было переключать музыкальным автоматом. Здесь то же
 * разделение: пул коротких эффектов + один зацикленный фоновый трек.
 *
 * WebAudio, без сторонних библиотек. Особенности мобильных браузеров и Telegram
 * WebView, из-за которых всё написано именно так:
 *   - AudioContext стартует в состоянии suspended, пока не будет жеста
 *     пользователя, поэтому есть unlock() на первый тап;
 *   - вкладка в фоне продолжала бы «играть» в никуда, поэтому на
 *     visibilitychange музыка ставится на паузу;
 *   - эффекты декодируются один раз и переиспользуются: BufferSource одноразовый,
 *     а буфер — нет.
 */

import { asset } from '../asset-url';

/** Короткие эффекты. Имя файла = ключ. */
export type SfxName =
  | 'cash'
  | 'coin-drop'
  | 'coin-pickup'
  | 'cooking'
  | 'eating'
  | 'level-up'
  | 'place-item'
  | 'message'
  | 'gift'
  | 'watering'
  | 'camera';

/** Фоновые треки. Первые три — залы игры, остальные для музыкального автомата. */
export type MusicName =
  | 'music-restaurant'
  | 'music-editor'
  | 'music-street'
  | 'music-classical'
  | 'music-irish'
  | 'music-mexican'
  | 'music-oriental';

const BASE = asset('sounds');
const STORAGE_KEY = 'rv:audio:v1';

type AudioPrefs = { muted: boolean; sfxVolume: number; musicVolume: number };

const DEFAULT_PREFS: AudioPrefs = { muted: false, sfxVolume: 0.7, musicVolume: 0.35 };

function loadPrefs(): AudioPrefs {
  if (typeof window === 'undefined') return DEFAULT_PREFS;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw) return { ...DEFAULT_PREFS, ...(JSON.parse(raw) as Partial<AudioPrefs>) };
  } catch {
    /* ignore */
  }
  return DEFAULT_PREFS;
}

function savePrefs(prefs: AudioPrefs): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
  } catch {
    /* ignore */
  }
}

class AudioEngine {
  private ctx: AudioContext | null = null;
  private sfxGain: GainNode | null = null;
  private musicGain: GainNode | null = null;

  private readonly buffers = new Map<string, AudioBuffer>();
  private readonly loading = new Map<string, Promise<AudioBuffer | null>>();

  private musicSource: AudioBufferSourceNode | null = null;
  private currentMusic: MusicName | null = null;
  /** Трек, который должен играть; включится, как только разрешат звук. */
  private wantedMusic: MusicName | null = null;

  private prefs = loadPrefs();
  private unlocked = false;
  private readonly listeners = new Set<() => void>();

  get muted(): boolean {
    return this.prefs.muted;
  }

  /** Подписка на изменение настроек — для кнопки в HUD. */
  subscribe(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private notify(): void {
    for (const fn of this.listeners) fn();
  }

  /**
   * Создать контекст и повесить разблокировку на первый жест.
   * Вызывать при старте сцены — до жеста звука всё равно не будет.
   */
  init(): void {
    if (this.ctx || typeof window === 'undefined') return;
    const Ctor =
      window.AudioContext ??
      (window as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;

    this.ctx = new Ctor();
    this.sfxGain = this.ctx.createGain();
    this.musicGain = this.ctx.createGain();
    this.sfxGain.connect(this.ctx.destination);
    this.musicGain.connect(this.ctx.destination);
    this.applyVolumes();

    const unlock = (): void => void this.unlock();
    for (const evt of ['pointerdown', 'keydown', 'touchstart'] as const) {
      window.addEventListener(evt, unlock, { once: true, passive: true });
    }
    document.addEventListener('visibilitychange', this.onVisibility);
  }

  private readonly onVisibility = (): void => {
    // Вкладка ушла в фон — глушим музыку, чтобы не играла в никуда.
    if (document.hidden) this.stopMusic();
    else if (this.wantedMusic) void this.playMusic(this.wantedMusic);
  };

  /** Разбудить AudioContext после жеста пользователя. */
  async unlock(): Promise<void> {
    if (!this.ctx || this.unlocked) return;
    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
    }
    this.unlocked = true;
    if (this.wantedMusic) void this.playMusic(this.wantedMusic);
  }

  private applyVolumes(): void {
    const on = !this.prefs.muted;
    if (this.sfxGain) this.sfxGain.gain.value = on ? this.prefs.sfxVolume : 0;
    if (this.musicGain) this.musicGain.gain.value = on ? this.prefs.musicVolume : 0;
  }

  setMuted(muted: boolean): void {
    this.prefs = { ...this.prefs, muted };
    savePrefs(this.prefs);
    this.applyVolumes();
    if (muted) this.stopMusic();
    else if (this.wantedMusic) void this.playMusic(this.wantedMusic);
    this.notify();
  }

  toggleMuted(): void {
    this.setMuted(!this.prefs.muted);
  }

  /** Загрузить и раскодировать файл один раз. */
  private async buffer(name: string): Promise<AudioBuffer | null> {
    const cached = this.buffers.get(name);
    if (cached) return cached;
    const inFlight = this.loading.get(name);
    if (inFlight) return inFlight;

    const job = (async (): Promise<AudioBuffer | null> => {
      const ctx = this.ctx;
      if (!ctx) return null;
      try {
        const res = await fetch(`${BASE}/${name}.mp3`);
        const raw = await res.arrayBuffer();
        const decoded = await ctx.decodeAudioData(raw);
        this.buffers.set(name, decoded);
        return decoded;
      } catch (err) {
        console.warn(`audio: не загрузился ${name}`, err);
        return null;
      } finally {
        this.loading.delete(name);
      }
    })();
    this.loading.set(name, job);
    return job;
  }

  /** Прогреть эффекты, которые понадобятся сразу. */
  async preload(names: readonly (SfxName | MusicName)[]): Promise<void> {
    await Promise.all(names.map((n) => this.buffer(n)));
  }

  /** Короткий эффект. volume — множитель поверх общей громкости эффектов. */
  play(name: SfxName, volume = 1): void {
    if (this.prefs.muted || !this.ctx || !this.sfxGain || !this.unlocked) return;
    void this.buffer(name).then((buf) => {
      const ctx = this.ctx;
      if (!buf || !ctx || !this.sfxGain || this.prefs.muted) return;
      const src = ctx.createBufferSource();
      src.buffer = buf;
      if (volume === 1) {
        src.connect(this.sfxGain);
      } else {
        const gain = ctx.createGain();
        gain.gain.value = volume;
        gain.connect(this.sfxGain);
        src.connect(gain);
      }
      src.start();
    });
  }

  /** Включить фоновый трек (зациклен). Тот же трек второй раз не перезапускается. */
  async playMusic(name: MusicName): Promise<void> {
    this.wantedMusic = name;
    if (this.prefs.muted || !this.ctx || !this.musicGain || !this.unlocked) return;
    if (this.currentMusic === name && this.musicSource) return;

    const buf = await this.buffer(name);
    const ctx = this.ctx;
    if (!buf || !ctx || !this.musicGain) return;
    // Пока грузили, могли передумать.
    if (this.wantedMusic !== name || this.prefs.muted) return;

    this.stopMusic();
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    src.connect(this.musicGain);
    src.start();
    this.musicSource = src;
    this.currentMusic = name;
  }

  stopMusic(): void {
    if (!this.musicSource) return;
    try {
      this.musicSource.stop();
    } catch {
      /* уже остановлен */
    }
    this.musicSource.disconnect();
    this.musicSource = null;
    this.currentMusic = null;
  }

  dispose(): void {
    this.stopMusic();
    this.wantedMusic = null;
    document.removeEventListener('visibilitychange', this.onVisibility);
    void this.ctx?.close();
    this.ctx = null;
    this.sfxGain = null;
    this.musicGain = null;
    this.buffers.clear();
    this.unlocked = false;
  }
}

/** Единственный движок на приложение. */
export const audio = new AudioEngine();
