/**
 * Визуальное представление одного актёра (гость / повар / официант).
 *
 * Вся тройка рисуется одинаково: 3D-аватар из общего батча (под-текстура
 * стрипа) плюс 2D-плейсхолдер на время загрузки модели или когда свободных
 * слотов батча не осталось. Класс знает только про позицию в тайлах, ключ
 * анимации и направление — игровое состояние живёт в симуляции.
 */

import { type Container, Graphics, Rectangle, Sprite, Texture } from 'pixi.js';
import type { AvatarBatch } from '../avatar/avatar-batch';
import type { AvatarConfig } from '../avatar/avatar-config';
import type { AvatarProp } from '../avatar/avatar-model';
import { DEPTH_BIAS, TILE_H, TILE_W, isoDepth, tileToScreen } from './iso';

/** Экранный угол «лицом» по направлению в тайловых координатах. */
export function screenFacing(dtx: number, dty: number): number {
  const dsx = (dtx - dty) * (TILE_W / 2);
  const dsy = (dtx + dty) * (TILE_H / 2);
  return Math.atan2(dsx, dsy);
}

/** Экранный угол «лицом» по повороту предмета (стул смотрит на стол). */
export function facingFromRotation(rotation: 0 | 90 | 180 | 270): number {
  switch (rotation) {
    case 0:
      return screenFacing(1, 0);
    case 90:
      return screenFacing(0, 1);
    case 180:
      return screenFacing(-1, 0);
    default:
      return screenFacing(0, -1);
  }
}

/** 2D-заглушка на случай, если 3D-модель ещё не загрузилась. */
export function makePlaceholderSprite(): Graphics {
  const g = new Graphics();
  g.ellipse(0, 4, 10, 4).fill({ color: 0x000000, alpha: 0.25 });
  g.roundRect(-7, -18, 14, 18, 3).fill({ color: 0x3aa1d8 });
  g.circle(0, -22, 6).fill({ color: 0xf2cf9b });
  g.circle(-2, -23, 0.9).fill({ color: 0x000000 });
  g.circle(2, -23, 0.9).fill({ color: 0x000000 });
  return g;
}

export class ActorView {
  private slot: number | null = null;
  private sprite: Sprite | null = null;
  private readonly gfx: Graphics;
  private prev: { x: number; y: number } | null = null;
  /** Предмет в руках — запоминаем, чтобы выставить его при получении слота. */
  private prop: AvatarProp | null = null;
  /** Индивидуальная внешность (у сотрудников своя, у гостей — наряд по умолчанию). */
  private look: AvatarConfig | null = null;

  constructor(
    private readonly batch: AvatarBatch,
    private readonly baseTex: Texture,
    private readonly layer: Container,
  ) {
    this.gfx = makePlaceholderSprite();
    this.gfx.visible = false;
    this.layer.addChild(this.gfx);
  }

  /**
   * Обновить кадр. pos — дробная позиция в тайлах, animKey — ключ анимации,
   * idleFacing — куда смотреть, когда актёр стоит (null = сохранить прежнее).
   */
  update(
    pos: { x: number; y: number },
    animKey: string,
    idleFacing: number | null = null,
    depthBias: number = DEPTH_BIAS.actor,
  ): void {
    const screen = tileToScreen(pos.x, pos.y);
    const cx = screen.x;
    const cy = screen.y + TILE_H / 2; // центр клетки
    const depth = isoDepth(pos.x, pos.y) + depthBias;

    // Ленивый апгрейд на 3D-слот, когда батч догрузился и слот освободился.
    if (this.slot === null && this.batch.ready) {
      const slot = this.batch.acquire(this.look);
      if (slot !== null) {
        this.slot = slot;
        this.sprite = this.makeAvatarSprite(slot);
        this.layer.addChild(this.sprite);
      }
    }

    if (this.slot !== null && this.sprite) {
      this.batch.setAnim(this.slot, animKey);
      this.batch.setProp(this.slot, this.prop);
      const moved = this.prev ? screenFacing(pos.x - this.prev.x, pos.y - this.prev.y) : null;
      const dist = this.prev ? Math.abs(pos.x - this.prev.x) + Math.abs(pos.y - this.prev.y) : 0;
      if (moved !== null && dist > 0.001) this.batch.setFacing(this.slot, moved);
      else if (idleFacing !== null) this.batch.setFacing(this.slot, idleFacing);
      this.sprite.position.set(cx, cy);
      this.sprite.zIndex = depth;
      this.sprite.visible = true;
      this.gfx.visible = false;
    } else {
      this.gfx.position.set(cx, cy);
      this.gfx.zIndex = depth;
      this.gfx.visible = true;
    }
    this.prev = { x: pos.x, y: pos.y };
  }

  /** Предмет в руках: поднос официанта, щётка уборщика. null — пустые руки. */
  setProp(prop: AvatarProp | null): void {
    this.prop = prop;
  }

  /** Внешность актёра. Выставляется до первого update, дальше не меняется. */
  setLook(look: AvatarConfig | null): void {
    if (this.look === look) return;
    this.look = look;
    if (this.slot !== null) this.batch.setLook(this.slot, look);
  }

  /** Спрятать актёра и вернуть слот батча в пул. */
  hide(): void {
    if (this.slot !== null) {
      this.batch.release(this.slot);
      this.slot = null;
    }
    if (this.sprite) {
      this.layer.removeChild(this.sprite);
      this.sprite.destroy();
      this.sprite = null;
    }
    this.gfx.visible = false;
    this.prev = null;
  }

  destroy(): void {
    this.hide();
    this.layer.removeChild(this.gfx);
    this.gfx.destroy();
  }

  /** Под-спрайт стрипа батча: ячейка слота как отдельный frame текстуры. */
  private makeAvatarSprite(slot: number): Sprite {
    const r = this.batch.cellRect(slot);
    const tex = new Texture({
      source: this.baseTex.source,
      frame: new Rectangle(r.x, r.y, r.w, r.h),
    });
    const s = new Sprite(tex);
    s.anchor.set(0.5, 0.92); // ступни в точке тайла
    s.scale.set(0.7);
    return s;
  }
}
