/**
 * Слой предметов + дизайн-режим (порт WorldRestaurantEditor).
 *
 * Отвечает за спрайты мебели, их привязку к изометрии (включая настенные
 * предметы, которые крепятся к ребру клетки) и за перетаскивание/поворот.
 * Валидацию размещения делает WorldRestaurant — здесь только ввод и графика.
 *
 * Жест: тап без смещения — поворот на 90°, протяжка — перенос. Настенные
 * предметы авто-ориентируются под ближайшую стену, чтобы их плоскость с ней
 * совпадала.
 */

import { engine } from '@rv/shared';
import { type Container, type FederatedPointerEvent, Graphics, Sprite } from 'pixi.js';
import {
  itemDepth,
  makeItemSprite,
  makeItemSpriteFromAtlas,
  wallDecorLift,
} from './furniture-sprites';
import { screenToTile, snapToTile, tileToScreen, wallEdgeOffset } from './iso';
import { drawTileHighlight } from './walls';

/** Меньше — считаем тапом (поворот), больше — перетаскиванием. */
const TAP_THRESHOLD_PX = 6;

type DragState = {
  sprite: Container;
  itemId: string;
  /** Смещение курсора от origin спрайта в момент захвата. */
  pointerOffset: { x: number; y: number };
  /** Глобальная точка начала — чтобы отличить тап от переноса. */
  startGlobal: { x: number; y: number };
  moved: boolean;
  /** Для настенных: клетка и поворот под текущей стеной. */
  wallTarget: { tile: { x: number; y: number }; rotation: engine.Rotation } | null;
};

export type ItemLayerOptions = {
  world: engine.WorldRestaurant;
  /** Сортируемый слой, куда кладутся спрайты предметов. */
  sortLayer: Container;
  /** Корневой контейнер сцены — в его координатах считается позиция курсора. */
  stage: Container;
  /** Вызывается после любой успешной правки расстановки. */
  onLayoutChanged: (changed: engine.PlacedItem | null) => void;
  /** Тап по предмету в режиме продажи. */
  onSellItem: (itemId: string) => void;
};

export class ItemLayer {
  private readonly sprites = new Map<string, Container>();
  private readonly highlight = new Graphics();
  private drag: DragState | null = null;
  private designMode = false;
  /** В режиме продажи тап по предмету не крутит его, а продаёт. */
  private sellMode = false;

  constructor(private readonly opts: ItemLayerOptions) {
    this.highlight.visible = false;
    this.opts.stage.addChild(this.highlight);
    for (const item of this.opts.world.getAllItems()) this.addSprite(item);
  }

  /** Подсветка клетки живёт под предметами — вернуть, чтобы вставить в нужный слой. */
  get highlightGraphics(): Graphics {
    return this.highlight;
  }

  /** Режим продажи: курсор-«крестик», тап по предмету отдаёт его в sellItem. */
  setSellMode(on: boolean): void {
    this.sellMode = on;
    for (const sprite of this.sprites.values()) {
      sprite.cursor = this.designMode ? (on ? 'crosshair' : 'move') : 'default';
    }
  }

  /** Показать только что купленный предмет и сразу дать его подвигать. */
  addItem(item: engine.PlacedItem): void {
    this.addSprite(item);
  }

  setDesignMode(on: boolean): void {
    this.designMode = on;
    for (const sprite of this.sprites.values()) {
      sprite.eventMode = on ? 'static' : 'none';
      sprite.cursor = on ? 'move' : 'default';
    }
    if (!on) {
      this.drag = null;
      this.highlight.visible = false;
    }
  }

  /** Подключить глобальные pointer-события (нужно, чтобы drag не терялся). */
  attach(stageRoot: Container): void {
    stageRoot.on('pointermove', this.onPointerMove);
    stageRoot.on('pointerup', this.onPointerUp);
    stageRoot.on('pointerupoutside', this.onPointerUp);
  }

  detach(stageRoot: Container): void {
    stageRoot.off('pointermove', this.onPointerMove);
    stageRoot.off('pointerup', this.onPointerUp);
    stageRoot.off('pointerupoutside', this.onPointerUp);
  }

  getSprite(itemId: string): Container | undefined {
    return this.sprites.get(itemId);
  }

  // ── Геометрия предмета ────────────────────────────────────────────

  /** Настенный предмет крепится к ребру клетки, а не стоит в центре пола. */
  static isWallItem(item: engine.PlacedItem): boolean {
    const cat = engine.classifyItem(item.definition);
    return cat === 'wall' || cat === 'door' || cat === 'wall-decor' || cat === 'wallpaper';
  }

  /** Экранная точка, в которую ставится origin спрайта (с учётом стен). */
  private anchorScreen(item: engine.PlacedItem): { x: number; y: number } {
    const t = tileToScreen(item.tileX, item.tileY);
    if (!ItemLayer.isWallItem(item)) return t;
    const off = wallEdgeOffset(item.rotation);
    const lift = wallDecorLift(engine.classifyItem(item.definition));
    return { x: t.x + off.dx, y: t.y + off.dy - lift };
  }

  /** Обратно: из экранной точки origin → тайл. */
  private tileFromAnchor(x: number, y: number, item: engine.PlacedItem): { x: number; y: number } {
    if (!ItemLayer.isWallItem(item)) return snapToTile(x, y);
    const off = wallEdgeOffset(item.rotation);
    const lift = wallDecorLift(engine.classifyItem(item.definition));
    return snapToTile(x - off.dx, y - off.dy + lift);
  }

  /**
   * Ближайшая стена под экранной точкой → клетка на ней и поворот, при котором
   * плоскость предмета совпадёт со стеной.
   */
  private wallTargetForPoint(
    screenX: number,
    screenY: number,
    item?: engine.PlacedItem,
  ): { tile: { x: number; y: number }; rotation: engine.Rotation } {
    const W = this.opts.world.width;
    const H = this.opts.world.height;
    const raw = screenToTile(screenX, screenY);
    const clamp = (v: number, lo: number, hi: number): number =>
      Math.max(lo, Math.min(hi, Math.round(v)));

    // Дверь ходит только по левой стене: к ней пристраивается наружная
    // площадка, и расширение зала идёт в ту же сторону (см. isValidPlacement).
    if (item && engine.classifyItem(item.definition) === 'door') {
      return { tile: { x: 0, y: clamp(raw.y, 0, H - 1) }, rotation: 0 };
    }

    const dLeft = raw.x;
    const dTop = raw.y;
    const dRight = W - 1 - raw.x;
    const dBottom = H - 1 - raw.y;
    const min = Math.min(dLeft, dTop, dRight, dBottom);
    if (min === dLeft) return { tile: { x: 0, y: clamp(raw.y, 0, H - 1) }, rotation: 0 };
    if (min === dTop) return { tile: { x: clamp(raw.x, 0, W - 1), y: 0 }, rotation: 90 };
    if (min === dRight) return { tile: { x: W - 1, y: clamp(raw.y, 0, H - 1) }, rotation: 180 };
    return { tile: { x: clamp(raw.x, 0, W - 1), y: H - 1 }, rotation: 270 };
  }

  // ── Спрайты ───────────────────────────────────────────────────────

  private addSprite(item: engine.PlacedItem): Container {
    const sprite: Container = makeItemSpriteFromAtlas(item) ?? makeItemSprite(item);
    const p = this.anchorScreen(item);
    sprite.position.set(p.x, p.y);
    sprite.zIndex = itemDepth(item);
    sprite.eventMode = this.designMode ? 'static' : 'none';
    sprite.cursor = this.designMode ? (this.sellMode ? 'crosshair' : 'move') : 'default';
    this.opts.sortLayer.addChild(sprite);
    this.sprites.set(item.id, sprite);
    sprite.on('pointerdown', (e: FederatedPointerEvent) =>
      this.onItemPointerDown(e, sprite, item.id),
    );
    return sprite;
  }

  /** Убрать спрайт проданного предмета. */
  removeItem(itemId: string): void {
    const sprite = this.sprites.get(itemId);
    if (!sprite) return;
    this.opts.sortLayer.removeChild(sprite);
    sprite.destroy();
    this.sprites.delete(itemId);
  }

  /** Пересоздать спрайт (после поворота меняются кадр и якорь). */
  private refreshSprite(itemId: string): void {
    const old = this.sprites.get(itemId);
    if (old) {
      this.opts.sortLayer.removeChild(old);
      old.destroy();
      this.sprites.delete(itemId);
    }
    const item = this.opts.world.getItem(itemId);
    if (item) this.addSprite(item);
  }

  /** Сменить текстуру существующего спрайта под новый поворот, без пересоздания. */
  private previewRotation(
    sprite: Container,
    item: engine.PlacedItem,
    rotation: engine.Rotation,
  ): void {
    const fresh = makeItemSpriteFromAtlas({ ...item, rotation });
    if (fresh instanceof Sprite && sprite instanceof Sprite) {
      sprite.texture = fresh.texture;
      sprite.anchor.set(fresh.anchor.x, fresh.anchor.y);
      fresh.destroy();
    }
  }

  // ── Ввод ──────────────────────────────────────────────────────────

  private onItemPointerDown(e: FederatedPointerEvent, sprite: Container, itemId: string): void {
    if (!this.designMode || this.drag) return;
    if (this.sellMode) {
      e.stopPropagation();
      this.opts.onSellItem(itemId);
      return;
    }
    const item = this.opts.world.getItem(itemId);
    if (!item) return;
    const local = this.opts.stage.toLocal(e.global);
    this.drag = {
      sprite,
      itemId,
      pointerOffset: { x: local.x - sprite.position.x, y: local.y - sprite.position.y },
      startGlobal: { x: e.global.x, y: e.global.y },
      moved: false,
      wallTarget: null,
    };
    sprite.alpha = 0.7;
    sprite.zIndex = 100_000;
    e.stopPropagation();
  }

  private readonly onPointerMove = (e: FederatedPointerEvent): void => {
    const drag = this.drag;
    if (!drag) return;
    if (!drag.moved) {
      const dx = e.global.x - drag.startGlobal.x;
      const dy = e.global.y - drag.startGlobal.y;
      if (Math.hypot(dx, dy) <= TAP_THRESHOLD_PX) return;
      drag.moved = true;
    }

    const local = this.opts.stage.toLocal(e.global);
    const x = local.x - drag.pointerOffset.x;
    const y = local.y - drag.pointerOffset.y;
    drag.sprite.position.set(x, y);

    const item = this.opts.world.getItem(drag.itemId);
    if (!item) return;

    if (ItemLayer.isWallItem(item)) {
      const target = this.wallTargetForPoint(x, y, item);
      drag.wallTarget = target;
      if (item.rotation !== target.rotation) {
        this.previewRotation(drag.sprite, item, target.rotation);
      }
      const valid = this.opts.world.isValidPlacement(
        item.definition,
        target.tile.x,
        target.tile.y,
        target.rotation,
        item.id,
      );
      drawTileHighlight(this.highlight, target.tile.x, target.tile.y, valid);
      return;
    }

    const tile = this.tileFromAnchor(x, y, item);
    const valid = this.opts.world.isValidPlacement(
      item.definition,
      tile.x,
      tile.y,
      item.rotation,
      item.id,
    );
    drawTileHighlight(this.highlight, tile.x, tile.y, valid);
  };

  private readonly onPointerUp = (): void => {
    const drag = this.drag;
    if (!drag) return;
    this.drag = null;
    this.highlight.visible = false;
    drag.sprite.alpha = 1;

    const { itemId } = drag;

    if (!drag.moved) {
      // Тап без переноса → поворот на 90°.
      if (this.opts.world.rotate(itemId)) {
        this.refreshSprite(itemId);
        this.opts.onLayoutChanged(this.opts.world.getItem(itemId));
      }
      return;
    }

    const item = this.opts.world.getItem(itemId);
    if (item) {
      if (ItemLayer.isWallItem(item) && drag.wallTarget) {
        const { tile, rotation } = drag.wallTarget;
        this.opts.world.move(itemId, tile.x, tile.y, rotation);
      } else {
        const tile = this.tileFromAnchor(drag.sprite.position.x, drag.sprite.position.y, item);
        this.opts.world.move(itemId, tile.x, tile.y);
      }
    }
    this.refreshSprite(itemId);
    this.opts.onLayoutChanged(item);
  };

  destroy(): void {
    for (const sprite of this.sprites.values()) sprite.destroy();
    this.sprites.clear();
    this.highlight.destroy();
  }
}
