/**
 * Штат ресторана — порт GameUserEmployee.as, GameUser.tick (:857),
 * GameUser.refreshBedStatusForRestingEmployees (:372) и группы «Employee» из
 * perk.xml.
 *
 * В оригинале сотрудник — это НЕ безликий юнит, а конкретный человек, которого
 * вы наняли и которому назначили должность. У него есть:
 *   - job: JOB_NONE / JOB_COOK / JOB_WAITOR / JOB_REST / JOB_CLEANER;
 *   - workTime: запас сил на 4 часа работы, тратится 1:1 на смене и
 *     восстанавливается втрое быстрее на отдыхе (кровать ускоряет ещё);
 *   - перки: еда из магазина, мгновенно возвращающая часть сил.
 *
 * Нанимали друзей из Facebook (WorldHire.as). Друзей у нас нет, поэтому вместо
 * ленты друзей — биржа труда: детерминированный по seed'у пул кандидатов.
 * Всё остальное (лимит по уровню, бесплатный найм с +10 опыта, увольнение за
 * 200 монет) сохранено как в оригинале.
 */

import { Balance } from './balance';
import type { ItemDefinition, PlacedItem } from './types';

/** Должность — значения совпадают с GameUserEmployee.JOB_* оригинала. */
export const Job = {
  /** Нанят, но не назначен: не работает и сил не тратит (JOB_NONE). */
  None: 0,
  Cook: 1,
  Waiter: 2,
  Rest: 3,
  Cleaner: 4,
} as const;

export type JobId = (typeof Job)[keyof typeof Job];

export const JOB_LABELS: Record<JobId, string> = {
  [Job.None]: 'Без дела',
  [Job.Cook]: 'Повар',
  [Job.Waiter]: 'Официант',
  [Job.Rest]: 'Отдых',
  [Job.Cleaner]: 'Уборщик',
};

/** Должности, которые можно назначить кнопками (порядок как в попапе оригинала). */
export const ASSIGNABLE_JOBS: readonly JobId[] = [Job.Cook, Job.Waiter, Job.Cleaner, Job.Rest];

/** Работает ли сотрудник на этой должности (тратит силы). */
export function isWorkingJob(job: JobId): boolean {
  return job === Job.Cook || job === Job.Waiter || job === Job.Cleaner;
}

/**
 * Внешность сотрудника. Поля повторяют AvatarConfig клиента — движок про
 * three.js не знает, но хранит и сериализует облик вместе с сотрудником.
 */
export type EmployeeLook = {
  hair: string;
  hat: string;
  body: 'pants' | 'dress';
  skin: number;
  hairColor: number;
  shirtColor: number;
  pantsColor: number;
};

/** Соискатель на бирже труда — сотрудник до найма. */
export type Candidate = {
  readonly id: string;
  readonly name: string;
  readonly look: EmployeeLook;
};

export type Employee = Candidate & {
  job: JobId;
  /** Куда вернуть, когда отдых закончится (в оригинале должность выбирали заново). */
  prevJob: JobId;
  /** Запас сил, мс (GameUserEmployee.workTime). */
  workTime: number;
  /** id кровати, за которой закреплён отдыхающий (GameUserEmployee.bedItem). */
  bedItemId: string | null;
};

/**
 * Еда для сотрудников — группа «Employee» из perk.xml. `workTime` в файле
 * задан в секундах, здесь сразу в миллисекундах.
 */
export type EmployeePerk = {
  readonly id: number;
  readonly className: string;
  readonly name: string;
  readonly cost: number;
  readonly workTimeMs: number;
};

export const EMPLOYEE_PERKS: readonly EmployeePerk[] = [
  { id: 6000000, className: 'RubyJuice', name: 'Рубиновый сок', cost: 80, workTimeMs: 3_600_000 },
  { id: 6000001, className: 'HeartLolly', name: 'Леденец', cost: 150, workTimeMs: 7_200_000 },
  { id: 6000002, className: 'Sundae', name: 'Мороженое', cost: 200, workTimeMs: 10_800_000 },
  { id: 6000003, className: 'Sweets', name: 'Сладости', cost: 280, workTimeMs: 14_400_000 },
];

export function lookupPerk(id: number): EmployeePerk | null {
  return EMPLOYEE_PERKS.find((p) => p.id === id) ?? null;
}

/** Кровать ли это (restaurant.xml, type="bed"). */
export function isBed(def: ItemDefinition): boolean {
  return def.type.includes('bed');
}

/**
 * Множитель восстановления сил на отдыхе — порт GameUser.tick (:878-883).
 *
 *   base = REST_WORK_TIME_INCREASE_MULTIPLYER (3)
 *   если у кровати operateTimePercentage != 100:
 *     base += base × (100 − percentage) / 100
 *
 * То есть чем МЕНЬШЕ operateTimePercentage, тем лучше кровать: 50% даёт ×4.5,
 * 75% — ×3.75. Без кровати — ровно ×3.
 */
export function restMultiplier(bed: ItemDefinition | null): number {
  const base = Balance.REST_WORK_TIME_MULTIPLIER;
  const pct = bed?.operateTimePercentage;
  if (bed == null || pct == null || pct === 100) return base;
  return base + (base * (100 - pct)) / 100;
}

// ── Биржа труда ─────────────────────────────────────────────────────

const MALE_NAMES = [
  'Борис',
  'Глеб',
  'Егор',
  'Захар',
  'Кирилл',
  'Марк',
  'Олег',
  'Рома',
  'Тимур',
  'Фёдор',
  'Яков',
];

const FEMALE_NAMES = [
  'Аня',
  'Вера',
  'Дина',
  'Жанна',
  'Инга',
  'Лада',
  'Нина',
  'Полина',
  'Соня',
  'Ульяна',
  'Юля',
];

/** Фамилии парами [мужская, женская] — иначе получится «Соня Ушаков». */
const LAST_NAMES: ReadonlyArray<readonly [string, string]> = [
  ['Ковалёв', 'Ковалёва'],
  ['Лебедев', 'Лебедева'],
  ['Мороз', 'Мороз'],
  ['Носов', 'Носова'],
  ['Орлов', 'Орлова'],
  ['Панов', 'Панова'],
  ['Рыбак', 'Рыбак'],
  ['Соколов', 'Соколова'],
  ['Тихонов', 'Тихонова'],
  ['Ушаков', 'Ушакова'],
  ['Фомин', 'Фомина'],
  ['Царёв', 'Царёва'],
];

/** Причёски из модели аватара (те же меши, что в редакторе внешности). */
const HAIRS = ['hair01', 'hair02', 'hair03', 'hair05', 'hair08', 'hair13', 'hair17'];
const SKINS = [0xf2cf9b, 0xe8bd8a, 0xc98e63, 0x8d5a3b, 0xfadfc0];
const HAIR_COLORS = [0x2b1d13, 0x5a3a22, 0x8c5a2b, 0xb98b4a, 0x3a3a3a];
const SHIRT_COLORS = [0x3aa1d8, 0xd8533a, 0x4bb85c, 0xd8a53a, 0x8a5cd8, 0xd83a8a];
const PANTS_COLORS = [0x394a5f, 0x2f2f36, 0x5f4a39, 0x3b5f4a];

/** mulberry32 — крошечный детерминированный PRNG, чтобы биржа не прыгала. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pick<T>(rng: () => number, list: readonly T[]): T {
  return list[Math.floor(rng() * list.length)] as T;
}

/** Сгенерировать одного соискателя по seed'у — облик и имя стабильны. */
export function makeCandidate(seed: number): Candidate {
  const rng = mulberry32(seed);
  const female = rng() < 0.5;
  const first = pick(rng, female ? FEMALE_NAMES : MALE_NAMES);
  const last = pick(rng, LAST_NAMES)[female ? 1 : 0];
  const name = `${first} ${last}`;
  return {
    id: `emp-${seed.toString(36)}`,
    name,
    look: {
      hair: pick(rng, HAIRS),
      hat: 'none',
      body: female ? 'dress' : 'pants',
      skin: pick(rng, SKINS),
      hairColor: pick(rng, HAIR_COLORS),
      shirtColor: pick(rng, SHIRT_COLORS),
      pantsColor: pick(rng, PANTS_COLORS),
    },
  };
}

/** Сколько соискателей висит на бирже одновременно. */
export const CANDIDATE_POOL_SIZE = 6;

// ── Сохранение ──────────────────────────────────────────────────────

export type RosterState = {
  employees: Employee[];
  /** Следующий seed для новой вакансии на бирже. */
  nextSeed: number;
  /** Seed'ы текущего пула соискателей. */
  candidateSeeds: number[];
};

// ── Штат ────────────────────────────────────────────────────────────

export type HireResult =
  | { ok: true; employee: Employee }
  | { ok: false; reason: 'no-slots' | 'not-found' };

/**
 * Нанятый штат + биржа труда.
 *
 * Лимит сотрудников задаёт уровень заведения (GameWorld.as:1251,
 * `LEVEL_THRESHOLDS[level].employees`) — сам Roster его не знает, лимит
 * передаётся в hire().
 */
export class Roster {
  private employees: Employee[] = [];
  private nextSeed: number;
  private candidateSeeds: number[] = [];

  constructor(state?: Partial<RosterState> | null) {
    this.nextSeed = state?.nextSeed ?? Math.floor(Math.random() * 0xffffff) + 1;
    if (state?.employees) {
      for (const raw of state.employees) this.employees.push(normalize(raw));
    }
    this.candidateSeeds = [...(state?.candidateSeeds ?? [])];
    this.refillCandidates();
  }

  /**
   * Стартовый штат: двое, повар и официант, полные сил. В оригинале первых
   * сотрудников нанимал туториал (Tutorial2 ждёт employeeUsers.length == 0),
   * у нас с них начинается игра — иначе пустой зал вообще не работает.
   */
  static withStarters(): Roster {
    const roster = new Roster();
    const first = roster.candidates()[0];
    if (first) {
      const cook = roster.hire(first.id, 2);
      if (cook.ok) roster.setJob(cook.employee.id, Job.Cook);
    }
    const second = roster.candidates()[0];
    if (second) {
      const waiter = roster.hire(second.id, 2);
      if (waiter.ok) roster.setJob(waiter.employee.id, Job.Waiter);
    }
    return roster;
  }

  get list(): readonly Employee[] {
    return this.employees;
  }

  get size(): number {
    return this.employees.length;
  }

  get(id: string): Employee | null {
    return this.employees.find((e) => e.id === id) ?? null;
  }

  byJob(job: JobId): Employee[] {
    return this.employees.filter((e) => e.job === job);
  }

  /** Сотрудники на должности, у которых ещё остались силы. */
  activeByJob(job: JobId): Employee[] {
    return this.employees.filter((e) => e.job === job && e.workTime > 0);
  }

  // ── Биржа ─────────────────────────────────────────────────────────

  candidates(): Candidate[] {
    return this.candidateSeeds.map(makeCandidate);
  }

  private refillCandidates(): void {
    while (this.candidateSeeds.length < CANDIDATE_POOL_SIZE) {
      this.candidateSeeds.push(this.nextSeed++);
    }
  }

  /**
   * Нанять соискателя. В оригинале найм бесплатный (WorldHireEmployeePopUp),
   * ограничен только числом слотов текущего уровня; за него дают
   * GOURMET_POINTS_HIRE_EMPLOYEE опыта — его начисляет вызывающий код.
   */
  hire(candidateId: string, maxEmployees: number): HireResult {
    if (this.employees.length >= maxEmployees) return { ok: false, reason: 'no-slots' };
    const index = this.candidateSeeds.findIndex((s) => makeCandidate(s).id === candidateId);
    if (index === -1) return { ok: false, reason: 'not-found' };

    const seed = this.candidateSeeds.splice(index, 1)[0] as number;
    const employee: Employee = {
      ...makeCandidate(seed),
      job: Job.None,
      prevJob: Job.None,
      workTime: Balance.MAX_WORK_TIME_MS,
      bedItemId: null,
    };
    this.employees.push(employee);
    this.refillCandidates();
    return { ok: true, employee };
  }

  /** Уволить. Штраф в монетах (FIRE_EMPLOYEE_PENALTY) списывает вызывающий код. */
  fire(id: string): Employee | null {
    const index = this.employees.findIndex((e) => e.id === id);
    if (index === -1) return null;
    return this.employees.splice(index, 1)[0] as Employee;
  }

  /** Назначить должность (порт onButtonCookClick и соседей). */
  setJob(id: string, job: JobId): boolean {
    const employee = this.get(id);
    if (!employee || employee.job === job) return false;
    if (employee.job !== Job.Rest) employee.prevJob = employee.job;
    employee.job = job;
    // GameUserEmployee.set job: смена должности всегда освобождает кровать.
    employee.bedItemId = null;
    return true;
  }

  /** Вернуть с отдыха на прежнюю должность (или в официанты, если её не было). */
  backToWork(id: string): boolean {
    const employee = this.get(id);
    if (!employee) return false;
    const job = isWorkingJob(employee.prevJob) ? employee.prevJob : Job.Waiter;
    return this.setJob(id, job);
  }

  /** Скормить перк — порт GameUserEmployee.addPerk (:87). Деньги списывает sim. */
  feed(id: string, perk: EmployeePerk): boolean {
    const employee = this.get(id);
    if (!employee) return false;
    employee.workTime = Math.min(employee.workTime + perk.workTimeMs, Balance.MAX_WORK_TIME_MS);
    return true;
  }

  /**
   * Раздать кровати отдыхающим — порт refreshBedStatusForRestingEmployees.
   * Сначала отбираем кровати у тех, кто уже не отдыхает или чья кровать
   * исчезла, потом раздаём свободные тем, кто отдыхает без кровати.
   */
  refreshBeds(beds: readonly PlacedItem[]): void {
    const available = new Set(beds.map((b) => b.id));
    for (const e of this.employees) {
      if (e.bedItemId && (e.job !== Job.Rest || !available.has(e.bedItemId))) e.bedItemId = null;
    }
    const taken = new Set(
      this.employees.map((e) => e.bedItemId).filter((id): id is string => id !== null),
    );
    for (const e of this.employees) {
      if (e.bedItemId !== null || e.job !== Job.Rest) continue;
      const free = beds.find((b) => !taken.has(b.id));
      if (!free) break;
      e.bedItemId = free.id;
      taken.add(free.id);
    }
  }

  /**
   * Списать/восстановить силы за прошедшее время — порт GameUser.tick (:857).
   * JOB_NONE не меняет ничего: незанятый сотрудник и не устаёт, и не отдыхает.
   */
  tick(dtMs: number, bedFor: (employee: Employee) => ItemDefinition | null): void {
    for (const e of this.employees) {
      if (isWorkingJob(e.job)) {
        e.workTime = Math.max(e.workTime - dtMs, 0);
      } else if (e.job === Job.Rest) {
        const gain = dtMs * restMultiplier(bedFor(e));
        e.workTime = Math.min(e.workTime + gain, Balance.MAX_WORK_TIME_MS);
      }
    }
  }

  /**
   * Закрыт ли ресторан — порт GameUser.isRestaurantClosed (:483).
   * Нужен хотя бы один повар И хотя бы один официант с остатком сил.
   */
  isRestaurantClosed(): boolean {
    const hasCook = this.employees.some((e) => e.job === Job.Cook && e.workTime > 0);
    const hasWaiter = this.employees.some((e) => e.job === Job.Waiter && e.workTime > 0);
    return !(hasCook && hasWaiter);
  }

  /** Отладка: всем полный запас сил. */
  refillEnergy(): void {
    for (const e of this.employees) e.workTime = Balance.MAX_WORK_TIME_MS;
  }

  toJSON(): RosterState {
    return {
      employees: this.employees.map((e) => ({ ...e, look: { ...e.look } })),
      nextSeed: this.nextSeed,
      candidateSeeds: [...this.candidateSeeds],
    };
  }
}

/** Достроить сотрудника из сейва: поля могли появиться позже. */
function normalize(raw: Employee): Employee {
  return {
    id: raw.id,
    name: raw.name,
    look: { ...raw.look },
    job: (raw.job ?? Job.None) as JobId,
    prevJob: (raw.prevJob ?? Job.None) as JobId,
    workTime: Math.max(0, Math.min(Balance.MAX_WORK_TIME_MS, raw.workTime ?? 0)),
    bedItemId: raw.bedItemId ?? null,
  };
}
