/**
 * Zod-схемы описывают форму ТИПИЗИРОВАННОГО JSON, который импортируется
 * из XML оригинала через scripts/import-content.ts. На вход zod получает
 * уже-нормализованные данные, не сырой XML.
 *
 * id-неймспейсы (как в оригинале):
 *   1xxxxxx — avatar items
 *   2xxxxxx — front items (фасад)
 *   3xxxxxx — restaurant items (интерьер)
 *   34xxxxx — awards (наследует category restaurant)
 *   4xxxxxx — ingredients
 *   5xxxxxx — recipes
 *   6xxxxxx — perks
 *   7xxxxxx — appointments (delivery)
 */
import { z } from 'zod';

// ──────────────────────────────────────────────────────────────────────────────
// Общие
// ──────────────────────────────────────────────────────────────────────────────

export const Rarity = z.number().int().min(1).max(5);
export type Rarity = z.infer<typeof Rarity>;

/** 22-символьный стабильный ID из оригинала. Сохраняем для миграционной совместимости и аналитики. */
export const ContentHash = z.string().min(20).max(80);

// ──────────────────────────────────────────────────────────────────────────────
// Ингредиенты (ingredient.xml → 62 шт)
// ──────────────────────────────────────────────────────────────────────────────

export const IngredientFlags = z
  .object({
    foodKingFeed: z.boolean(),
    fanPageFeed: z.boolean(),
    noDaily: z.boolean(),
    noFirstTimeVisit: z.boolean(),
    noQuiz: z.boolean(),
    noCoinShop: z.boolean(),
  })
  .strict();

export const Ingredient = z.object({
  id: z.number().int(),
  name: z.string(),
  /** Имя оригинального ассет-класса (для миграции спрайтов). */
  className: z.string(),
  /** Цена в премиум-валюте, если предмет покупаем за неё. */
  cash: z.number().int().nullable(),
  rarity: Rarity,
  /** Если ингредиент выращиваем в саду — имя 3D-класса растения. */
  plantClassName: z.string().nullable(),
  /** Сколько штук игрок получает в стартовом инвентаре. */
  initialQuantity: z.number().int(),
  hash: ContentHash,
  flags: IngredientFlags,
});
export type Ingredient = z.infer<typeof Ingredient>;

// ──────────────────────────────────────────────────────────────────────────────
// Рецепты (recipe.xml → 94 шт)
// ──────────────────────────────────────────────────────────────────────────────

export const RecipeCategory = z.enum(['Starter', 'Main', 'Dessert', 'Drink']);
export type RecipeCategory = z.infer<typeof RecipeCategory>;

export const Recipe = z.object({
  id: z.number().int(),
  name: z.string(),
  category: RecipeCategory,
  className: z.string(),
  /** Имена ингредиентов (ссылка по name). Длина 1-4. */
  ingredients: z.array(z.string()).min(1).max(4),
  /** Стоимость покупки рецепта (по умолчанию 2 — символическая). */
  cost: z.number().int(),
  hash: ContentHash,
  /** Сезонный рецепт (доступен ограниченное время). */
  isLimited: z.boolean(),
  /** Не показывается в шопе (нагрда / событийный). */
  invisible: z.boolean(),
  /** Дата истечения сезонного рецепта (ISO yyyy-mm-dd). */
  expireDate: z.string().nullable(),
  foodKingFeed: z.boolean(),
});
export type Recipe = z.infer<typeof Recipe>;

// ──────────────────────────────────────────────────────────────────────────────
// Предметы интерьера (restaurant.xml → 720+ шт)
// ──────────────────────────────────────────────────────────────────────────────

export const RestaurantItem = z.object({
  id: z.number().int(),
  name: z.string(),
  className: z.string(),
  /** Имя группы в каталоге (WallDecoration, Door, Decoration, Chair, …). */
  group: z.string(),
  /** Подтипы: tableItem, chairItem, surface, stackable, draggable, musicPlayer, … (CSV). */
  type: z.array(z.string()),
  cost: z.number().int().nullable(),
  cash: z.number().int().nullable(),
  sizeX: z.number().int(),
  sizeY: z.number().int(),
  /** Минимальный уровень игрока для покупки (0 = всегда). */
  unlockLevel: z.number().int(),
  /** Имя класса функции (StreetBubbleGeyser, ClockArms, …) — поведение, не только графика. */
  functions: z.array(z.string()),
  /**
   * Сколько раз предметом можно воспользоваться до поломки (туалеты — 4,
   * аркадные автоматы — 6..12). null — предмет не ломается.
   */
  breakCount: z.number().int().nullable(),
  /**
   * Скорость работы в процентах от базовой: 50 — вдвое быстрее готовит/работает.
   * null — 100%.
   */
  operateTimePercentage: z.number().int().nullable(),
  invisible: z.boolean(),
  isNew: z.boolean(),
  hash: ContentHash,
});
export type RestaurantItem = z.infer<typeof RestaurantItem>;

// ──────────────────────────────────────────────────────────────────────────────
// Предметы фасада (front.xml → ~250 шт)
// ──────────────────────────────────────────────────────────────────────────────

export const FrontItem = z.object({
  id: z.number().int(),
  name: z.string(),
  className: z.string(),
  group: z.string(),
  type: z.array(z.string()),
  cost: z.number().int().nullable(),
  cash: z.number().int().nullable(),
  /** Z-order при отрисовке стены (0 — body, 1 — tile, 2 — wallAttach, 3 — overlay). */
  drawPriority: z.number().int(),
  unlockLevel: z.number().int(),
  invisible: z.boolean(),
  isNew: z.boolean(),
  /** Для билбордов: внешняя ссылка (FB-фанстраница в оригинале). */
  url: z.string().nullable(),
  hash: ContentHash,
});
export type FrontItem = z.infer<typeof FrontItem>;

// ──────────────────────────────────────────────────────────────────────────────
// Аватарские предметы (avatar.xml → ~280 шт)
// ──────────────────────────────────────────────────────────────────────────────

export const AvatarSlot = z.enum([
  'Pants',
  'Skirt',
  'Shirt',
  'Hat',
  'Hair',
  'HairColour',
  'SkinColour',
  'Eyes',
  'Eyebrows',
  'Mouth',
  'Beard',
  'FacialFeature',
]);
export type AvatarSlot = z.infer<typeof AvatarSlot>;

export const AvatarItem = z.object({
  id: z.number().int(),
  name: z.string(),
  slot: AvatarSlot,
  /** 3D-меши, которые этот предмет покрывает: 'pants01', 'dress', 'shirt01', 'armleft', 'armright'… */
  object: z.array(z.string()),
  /** Имя битмап-материала (имя класса в avatar_asset.swf). */
  texture: z.string().nullable(),
  iconName: z.string().nullable(),
  cost: z.number().int().nullable(),
  cash: z.number().int().nullable(),
  invisible: z.boolean(),
  hash: ContentHash,
});
export type AvatarItem = z.infer<typeof AvatarItem>;

// ──────────────────────────────────────────────────────────────────────────────
// Бустеры/расходники (perk.xml)
// ──────────────────────────────────────────────────────────────────────────────

export const PerkGroup = z.enum(['Employee', 'Restaurant', 'CoinReward', 'DemandReward']);
export type PerkGroup = z.infer<typeof PerkGroup>;

export const Perk = z.object({
  id: z.number().int(),
  name: z.string(),
  className: z.string(),
  group: PerkGroup,
  text: z.string().nullable(),
  cost: z.number().int().nullable(),
  /** Продолжительность эффекта в часах (для Restaurant: clean/demand/gourmet). */
  duration: z.number().int(),
  /** Восполнение энергии сотрудника в секундах (для Employee). */
  workTime: z.number().int(),
  /** Целевое значение поля (clean=1..3, demand=20..30, gourmet=2, value для popularity). */
  effectValue: z.number().int(),
  /** Какой статус апгрейдит: 'clean' | 'demand' | 'gourmet' | 'workTime' | 'coins' | 'popularity'. */
  effectKind: z.string(),
  unlockLevel: z.number().int(),
  fanPageFeed: z.boolean(),
  hash: ContentHash,
});
export type Perk = z.infer<typeof Perk>;

// ──────────────────────────────────────────────────────────────────────────────
// Викторина (quiz.xml)
// ──────────────────────────────────────────────────────────────────────────────

export const QuizChoice = z.object({
  text: z.string(),
  /** Имя ассета-картинки рядом с вариантом (опц.). */
  image: z.string().nullable(),
  correct: z.boolean(),
});

export const QuizQuestion = z.object({
  /** Группа сложности 1-5. */
  difficulty: z.number().int().min(1).max(5),
  question: z.string(),
  /** Картинка вопроса (опц.). */
  image: z.string().nullable(),
  /** Имя ингредиента-награды за правильный ответ. */
  reward: z.string().nullable(),
  choices: z.array(QuizChoice).min(2).max(4),
});
export type QuizQuestion = z.infer<typeof QuizQuestion>;

// ──────────────────────────────────────────────────────────────────────────────
// Доставка / напитки (appointment.xml)
// ──────────────────────────────────────────────────────────────────────────────

export const Appointment = z.object({
  id: z.number().int(),
  name: z.string(),
  className: z.string(),
  cost: z.number().int(),
  /** Время приготовления в секундах. */
  duration: z.number().int(),
  hash: ContentHash,
});
export type Appointment = z.infer<typeof Appointment>;

// ──────────────────────────────────────────────────────────────────────────────
// Локализация
// ──────────────────────────────────────────────────────────────────────────────

/** Простой словарь key→строка. CDATA-блоки оригинала сохраняют HTML-разметку для подсветки. */
export const LocalizationDict = z.record(z.string(), z.string());
export type LocalizationDict = z.infer<typeof LocalizationDict>;

// ──────────────────────────────────────────────────────────────────────────────
// Сводка контента (то, что грузит клиент при старте)
// ──────────────────────────────────────────────────────────────────────────────

export const ContentBundle = z.object({
  ingredients: z.array(Ingredient),
  recipes: z.array(Recipe),
  restaurantItems: z.array(RestaurantItem),
  frontItems: z.array(FrontItem),
  avatarItems: z.array(AvatarItem),
  perks: z.array(Perk),
  quiz: z.array(QuizQuestion),
  appointments: z.array(Appointment),
});
export type ContentBundle = z.infer<typeof ContentBundle>;
