/**
 * Магазин предметов — порт правил покупки/продажи оригинала.
 *
 * Цены лежат в restaurant.xml и уже импортированы: `cost` (монеты), `cash`
 * (премиум-валюта, аналог Playfish Cash) и `unlockLevel`.
 *
 * Правила:
 *   - купить можно, если уровень игрока >= unlockLevel (GameWorld.as:2005)
 *     и хватает монет;
 *   - цена продажи — `getItemSellPrice` (GameWorld.as:2508):
 *     за премиум-предмет `cash × 330`, за обычный `floor(cost / 3)`;
 *   - продажа даёт GOURMET_POINTS_SELL_ITEM (2) опыта.
 *
 * Премиум-предметы (cash без cost) в каталоге видны, но купить их пока нельзя —
 * валюты нет, платежи будут через Telegram Stars.
 */

import { allDefinitions } from './catalog';
import { classifyItem } from './classify';
import { isBed } from './employees';
import { facilityKind } from './facilities';
import type { ItemCategory, ItemDefinition } from './types';

/** Группы, которые имеют смысл в магазине интерьера. */
const SHOP_GROUPS = new Set([
  'Chair',
  'Table',
  'Kitchen Appliance',
  'Functional',
  'Decoration',
  'Wall Decoration',
  'Wallpaper',
  'Floor Tile',
  'Door',
  'Wall',
]);

/** Вкладки магазина — по ним группируется каталог. */
export const SHOP_TABS = ['furniture', 'kitchen', 'functional', 'decor', 'wall', 'floor'] as const;

export type ShopTab = (typeof SHOP_TABS)[number];

export const SHOP_TAB_LABELS: Record<ShopTab, string> = {
  furniture: 'Мебель',
  kitchen: 'Кухня',
  functional: 'Удобства',
  decor: 'Декор',
  wall: 'Стены',
  floor: 'Пол',
};

/** Вкладка предмета по его категории. */
export function shopTabFor(def: ItemDefinition): ShopTab | null {
  // Санузел и автоматы — во вкладку «Удобства», даже если у них стоит флаг
  // chairItem (у туалетов он есть: гость садится на них как на стул).
  if (facilityKind(def) !== null) return 'functional';
  const category: ItemCategory = classifyItem(def);
  switch (category) {
    case 'furniture':
      return 'furniture';
    case 'kitchen':
      return 'kitchen';
    case 'functional':
      return 'functional';
    case 'decor':
      return 'decor';
    case 'door':
    case 'wall':
    case 'wallpaper':
    case 'wall-decor':
      return 'wall';
    case 'floor':
      return 'floor';
    default:
      return null;
  }
}

/** Цена продажи предмета (порт GameWorld.getItemSellPrice). */
export function itemSellPrice(def: ItemDefinition): number {
  if (def.cash != null && def.cash > 0) return def.cash * 330;
  return Math.floor((def.cost ?? 0) / 3);
}

/** Продаётся ли предмет за монеты (премиум-предметы пока не купить). */
export function isCoinPurchasable(def: ItemDefinition): boolean {
  return def.cost != null && def.cost > 0;
}

export type ShopEntry = {
  readonly def: ItemDefinition;
  readonly tab: ShopTab;
  /** Цена в монетах, null — предмет только за премиум-валюту. */
  readonly price: number | null;
  /** Цена в премиум-валюте, null — обычный предмет. */
  readonly cash: number | null;
  readonly sellPrice: number;
  readonly unlockLevel: number;
  /** Пометка «новинка» из restaurant.xml — вкладка «Новинки» оригинала. */
  readonly isNew: boolean;
};

/**
 * Разделы каталога — порт вкладок ItemChooser (TAB_NEW / TAB_SHOP / TAB_OWN /
 * TAB_CASH). «Инвентаря» у нас нет: купленный предмет сразу встаёт в зал,
 * поэтому вместо него вкладка «В зале» со списком уже расставленного.
 */
export const CATALOG_SECTIONS = ['shop', 'new', 'cash', 'placed'] as const;
export type CatalogSection = (typeof CATALOG_SECTIONS)[number];

export const CATALOG_SECTION_LABELS: Record<CatalogSection, string> = {
  shop: 'Магазин',
  new: 'Новинки',
  cash: 'Премиум',
  placed: 'В зале',
};

/** Порядок сортировки витрины. */
export type ShopSort = 'price' | 'alpha';

/**
 * Сравнение как в оригинале (`compareShopItems`): сначала бесплатное, затем
 * сезонное, затем новинки, остальное — по цене.
 */
export function compareShopEntries(a: ShopEntry, b: ShopEntry, sort: ShopSort): number {
  if (sort === 'alpha') return a.def.name.localeCompare(b.def.name);
  if (a.isNew !== b.isNew) return a.isNew ? -1 : 1;
  const pa = a.price ?? Number.MAX_SAFE_INTEGER;
  const pb = b.price ?? Number.MAX_SAFE_INTEGER;
  return pa - pb;
}

let catalogCache: ShopEntry[] | null = null;

/**
 * Полный каталог магазина. Отфильтрованы служебные группы (Award, Visit,
 * Outdoor Only) и скрытые предметы — в оригинале они тоже не продавались.
 *
 * Исключение — кровати: в дампе restaurant.xml обе помечены invisible (их
 * продавали ограниченное время), но без кровати отдых персонала работает лишь
 * на базовом ×3. Оставляем их в витрине, иначе механика недостижима.
 */
export function shopCatalog(): readonly ShopEntry[] {
  if (catalogCache) return catalogCache;
  const entries: ShopEntry[] = [];
  for (const def of allDefinitions()) {
    if (def.invisible && !isBed(def)) continue;
    if (!SHOP_GROUPS.has(def.group)) continue;
    const tab = shopTabFor(def);
    if (!tab) continue;
    entries.push({
      def,
      tab,
      price: isCoinPurchasable(def) ? (def.cost ?? 0) : null,
      cash: def.cash && def.cash > 0 ? def.cash : null,
      sellPrice: itemSellPrice(def),
      unlockLevel: def.unlockLevel,
      isNew: def.isNew,
    });
  }
  // Внутри вкладки — от дешёвых к дорогим, как в шопе оригинала.
  entries.sort(
    (a, b) => (a.price ?? Number.MAX_SAFE_INTEGER) - (b.price ?? Number.MAX_SAFE_INTEGER),
  );
  catalogCache = entries;
  return entries;
}

export type ShopFilter = {
  tab?: ShopTab;
  /** Раздел каталога: витрина, новинки или премиум. */
  section?: Exclude<CatalogSection, 'placed'>;
  /** Порядок сортировки. */
  sort?: ShopSort;
  /** Уровень игрока: предметы выше него помечаются заблокированными. */
  level?: number;
  /** Оставить только те, что реально доступны на этом уровне. */
  unlockedOnly?: boolean;
  /** Оставить только покупаемые за монеты. */
  coinsOnly?: boolean;
  /** Дополнительный фильтр — например «есть спрайт в библиотеке клиента». */
  include?: (entry: ShopEntry) => boolean;
};

export function filterCatalog(filter: ShopFilter = {}): ShopEntry[] {
  const {
    tab,
    section,
    sort = 'price',
    level = 0,
    unlockedOnly = false,
    coinsOnly = false,
    include,
  } = filter;
  const result = shopCatalog().filter((e) => {
    if (tab && e.tab !== tab) return false;
    if (section === 'new' && !e.isNew) return false;
    if (section === 'cash' && e.cash === null) return false;
    if (section === 'shop' && e.price === null) return false;
    if (coinsOnly && e.price === null) return false;
    if (unlockedOnly && e.unlockLevel > level) return false;
    if (include && !include(e)) return false;
    return true;
  });
  return result.sort((a, b) => compareShopEntries(a, b, sort));
}

/** Почему предмет нельзя купить. null — можно. */
export type PurchaseBlock = 'locked' | 'premium' | 'no-coins' | 'no-space';

export function purchaseBlock(
  entry: ShopEntry,
  level: number,
  coins: number,
): PurchaseBlock | null {
  if (entry.unlockLevel > level) return 'locked';
  if (entry.price === null) return 'premium';
  if (coins < entry.price) return 'no-coins';
  return null;
}
