import { engine } from '@rv/shared';
import { useState } from 'react';
import { asset } from '../asset-url';
import { haptic } from '../telegram';

const { ASSIGNABLE_JOBS, EMPLOYEE_PERKS, JOB_LABELS, Job } = engine;

type Employee = engine.EmployeeSummary;

type Props = {
  employee: Employee;
  coins: number;
  /** Соседи в списке — кнопки ‹ › как mc_prev / mc_next оригинала. */
  onPrev: () => void;
  onNext: () => void;
  onSetJob: (id: string, job: engine.JobId) => void;
  onFeed: (id: string, perkId: number) => void;
  onFire: (id: string) => void;
  onClose: () => void;
};

/**
 * Иконки должностей — те самые символы из `EmployeeInstructionPanel`:
 * `CookIcon` (колпак), `WaitorIcon` (клош), `CleanerIcon` (ведро со щёткой),
 * `RestIcon` (кровать). Подписи наши, потому что в оригинале текст был вшит
 * в кнопку по-английски.
 *
 * Для JOB_NONE своей иконки в оригинале нет — там незанятого сотрудника просто
 * не было среди кнопок; берём иконку найма как «новичок без работы».
 */
export const JOB_ICON: Record<engine.JobId, string> = {
  [Job.None]: asset('ui/btn-hire.png'),
  [Job.Cook]: asset('ui/job-cook.png'),
  [Job.Waiter]: asset('ui/job-waiter.png'),
  [Job.Cleaner]: asset('ui/job-cleaner.png'),
  [Job.Rest]: asset('ui/job-rest.png'),
};

/** Оставшийся запас сил как «Ч:ММ:СС» — порт GameUserEmployee.getTimeLeft. */
export function formatTimeLeft(workTimeMs: number): string {
  const total = Math.max(0, Math.ceil(workTimeMs / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
}

/** Прибавка сил на кнопке еды: часы, пока их больше одного, иначе минуты. */
function formatGain(ms: number): string {
  if (ms >= 3_600_000) return `${Math.round((ms / 3_600_000) * 10) / 10}ч`;
  return `${Math.round(ms / 60_000)}м`;
}

/** Цвет полосы сил: зелёная → жёлтая → красная, как менялась иконка настроения. */
export function energyColor(energy: number): string {
  if (energy > 0.5) return 'bg-emerald-400';
  if (energy > 0.2) return 'bg-amber-400';
  return 'bg-rose-500';
}

/** Что мешает сотруднику работать — порт табличек EmployeeActor.EMOTION_*. */
export function idleHint(employee: Employee): string | null {
  if (employee.exhausted) return 'Без сил — покормите или отправьте отдыхать';
  switch (employee.idleReason) {
    case 'needs-job':
      return 'Нужна работа';
    case 'needs-stove':
      return employee.job === Job.Cook ? 'Нужна свободная плита' : 'Нужна кухня';
    case 'resting':
      return employee.hasBed ? 'Спит в кровати — силы копятся быстрее' : 'Отдыхает';
    default:
      return null;
  }
}

/**
 * Карточка сотрудника — порт `EmployeeInstructionPanelPopup` из game_asset.swf
 * (логика в ui/WorldEmployeePopUp.as).
 *
 * В оригинале: портрет и 3D-аватар, красные часы с остатком рабочего времени,
 * четыре кнопки должностей (Cook / Waiter / Cleaner / Rest), витрина еды из
 * группы «Employee» перк-базы и кнопка увольнения. Всё это здесь есть; нет
 * только смены наряда и перехода в ресторан друга — им не на что опереться.
 */
export function EmployeePopUp({
  employee,
  coins,
  onPrev,
  onNext,
  onSetJob,
  onFeed,
  onFire,
  onClose,
}: Props): React.ReactElement {
  const [confirmFire, setConfirmFire] = useState(false);
  const penalty = engine.Balance.FIRE_EMPLOYEE_PENALTY;
  const canFire = coins + penalty > 0;
  const hint = idleHint(employee);
  /** Сколько сил ещё влезет: сверх потолка прибавка сгорает. */
  const room = Math.max(0, engine.Balance.MAX_WORK_TIME_MS - employee.workTime);
  const full = room < 60_000;

  return (
    <div className="absolute inset-0 z-30 grid place-items-center bg-black/60 p-4 pointer-events-auto">
      <div className="w-full max-w-sm max-h-[86dvh] overflow-y-auto rounded-2xl bg-[#161c24] border border-white/15 p-3 space-y-3">
        {/* ── Шапка: перелистывание, имя, закрытие ── */}
        <div className="flex items-center gap-2">
          <Arrow dir="prev" onClick={onPrev} />
          <div className="min-w-0 flex-1 text-center">
            <div className="text-sm font-semibold truncate">{employee.name}</div>
            <div className="text-[11px] opacity-60">{JOB_LABELS[employee.job]}</div>
          </div>
          <Arrow dir="next" onClick={onNext} />
          <button
            type="button"
            onClick={onClose}
            aria-label="Закрыть"
            className="rounded-lg w-7 h-7 grid place-items-center border border-white/15 hover:bg-white/5"
          >
            ✕
          </button>
        </div>

        {/* ── Часы рабочего времени: mc_happiness.tf_happiness оригинала ── */}
        <div className="rounded-xl bg-black/30 p-2 space-y-1.5">
          <div className="flex items-baseline gap-2">
            <span
              className={`font-mono text-lg font-bold tabular-nums ${
                employee.exhausted ? 'text-rose-300' : ''
              }`}
            >
              {formatTimeLeft(employee.workTime)}
            </span>
            <span className="text-[11px] opacity-50">до конца смены</span>
          </div>
          <div className="h-2 rounded-full bg-white/10 overflow-hidden">
            <div
              className={`h-full transition-[width] duration-500 ${energyColor(employee.energy)}`}
              style={{ width: `${Math.round(employee.energy * 100)}%` }}
            />
          </div>
          {hint && <div className="text-[11px] leading-snug text-amber-200/80">{hint}</div>}
        </div>

        {/* ── Должности ── */}
        <div>
          <div className="text-[11px] opacity-60 mb-1">Должность</div>
          <div className="grid grid-cols-4 gap-1.5">
            {ASSIGNABLE_JOBS.map((job) => (
              <button
                key={job}
                type="button"
                disabled={employee.job === job}
                onClick={() => {
                  haptic('light');
                  onSetJob(employee.id, job);
                }}
                className={`rounded-xl py-1.5 flex flex-col items-center gap-1 border text-[10px] font-semibold transition ${
                  employee.job === job
                    ? 'bg-white/15 border-white/60'
                    : 'border-white/15 hover:bg-white/5 text-white/70'
                }`}
              >
                <img src={JOB_ICON[job]} alt="" draggable={false} className="w-5 h-5" />
                {JOB_LABELS[job]}
              </button>
            ))}
          </div>
        </div>

        {/* ── Еда: группа «Employee» из perk.xml ── */}
        <div>
          <div className="flex items-center gap-1.5 mb-1">
            <img src={asset('ui/btn-perk.png')} alt="" className="w-5 h-3.5 object-contain" />
            <span className="text-[11px] opacity-60">
              {full ? 'Сотрудник полон сил' : 'Покормить — вернуть силы'}
            </span>
          </div>
          <div className="grid grid-cols-4 gap-1.5">
            {EMPLOYEE_PERKS.map((perk) => {
              // Излишек сверх потолка сгорает (Math.min в addPerk оригинала).
              // Показываем реальную прибавку и гасим перк, когда от него уже
              // почти ничего не останется — иначе монеты уходят впустую.
              const gain = Math.min(perk.workTimeMs, room);
              const usable = coins >= perk.cost && gain >= 60_000;
              // «Урезан» показываем, только пока перк ещё имеет смысл: у сытого
              // сотрудника подпись «+0м» ничего не объясняет, там честнее
              // оставить номинал и погасить кнопку.
              const capped = usable && gain < perk.workTimeMs;
              return (
                <button
                  key={perk.id}
                  type="button"
                  disabled={!usable}
                  title={capped ? `${perk.name}: влезет только ${formatGain(gain)}` : perk.name}
                  onClick={() => {
                    haptic('medium');
                    onFeed(employee.id, perk.id);
                  }}
                  className={`rounded-xl py-1.5 px-1 flex flex-col items-center gap-0.5 border transition ${
                    usable
                      ? 'border-white/15 hover:bg-white/5'
                      : 'border-white/10 opacity-40 cursor-not-allowed'
                  }`}
                >
                  <span
                    className={`text-[11px] font-semibold ${
                      capped ? 'text-amber-200' : 'text-emerald-200'
                    }`}
                  >
                    +{capped ? formatGain(gain) : `${perk.workTimeMs / 3_600_000}ч`}
                  </span>
                  <span className="flex items-center gap-0.5 text-[10px]">
                    <img src={asset('ui/coin.png')} alt="" className="w-3 h-3" />
                    {perk.cost}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* ── Увольнение: порт WorldSackEmployee ── */}
        <div className="pt-1 border-t border-white/10">
          {confirmFire ? (
            <div className="space-y-2">
              <div className="text-[11px] text-rose-200/90 leading-snug">
                Уволить «{employee.name}»? Расчёт обойдётся в {Math.abs(penalty)} монет.
              </div>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => {
                    haptic('medium');
                    onFire(employee.id);
                  }}
                  className="flex-1 rounded-xl py-2 text-xs font-semibold bg-rose-500/25 border border-rose-400/50 text-rose-100"
                >
                  Уволить
                </button>
                <button
                  type="button"
                  onClick={() => setConfirmFire(false)}
                  className="flex-1 rounded-xl py-2 text-xs font-semibold border border-white/20 hover:bg-white/5"
                >
                  Отмена
                </button>
              </div>
            </div>
          ) : (
            <button
              type="button"
              disabled={!canFire}
              onClick={() => setConfirmFire(true)}
              title={canFire ? undefined : 'Не хватает монет на расчёт'}
              className={`w-full rounded-xl py-2 flex items-center justify-center gap-2 text-xs font-semibold border ${
                canFire
                  ? 'border-rose-400/40 text-rose-200 hover:bg-rose-400/10'
                  : 'border-white/10 opacity-40 cursor-not-allowed'
              }`}
            >
              <img src={asset('ui/job-sack.png')} alt="" draggable={false} className="w-4 h-4" />
              Уволить · {Math.abs(penalty)} монет
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function Arrow({
  dir,
  onClick,
}: { dir: 'prev' | 'next'; onClick: () => void }): React.ReactElement {
  return (
    <button
      type="button"
      onClick={() => {
        haptic('light');
        onClick();
      }}
      aria-label={dir === 'prev' ? 'Предыдущий' : 'Следующий'}
      className="shrink-0 rounded-lg w-7 h-7 grid place-items-center border border-white/15 hover:bg-white/5 text-xs"
    >
      {dir === 'prev' ? '‹' : '›'}
    </button>
  );
}
