import { createRoot } from 'react-dom/client';
import App from './App';
import './styles.css';
import { hideBootSplash } from './boot-splash';
import { initTelegram } from './telegram';

// Инициализация Telegram WebApp ДО рендера, чтобы первый кадр уже видел тему/initData.
initTelegram();

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error('Missing #root element');

// Намеренно БЕЗ StrictMode: PixiJS Application плохо переживает двойной mount/unmount
// в dev-режиме (две параллельные WebGL-инициализации на один и тот же DOM-узел приводят
// к гонке). В проде StrictMode не активирует двойной запуск эффектов, так что для prod
// build это безопасно. Если потребуется — обнесём только нерендерные части в StrictMode.
createRoot(rootElement).render(<App />);

/**
 * Заставка из index.html снимается, когда сцена отрисовала первый кадр
 * (`hideBootSplash` зовёт App по первому снимку). Здесь только страховка:
 * если сцена не поднялась — из-за отказа WebGL или сети — крутить спиннер
 * вечно нельзя, показываем то, что есть.
 */
window.setTimeout(hideBootSplash, 15_000);
