/**
 * Кирпичики интерфейса в стиле оригинала.
 *
 * HUD Restaurant City собран из готовых MovieClip-ов: шкала уровня с золотым
 * медальоном (`RoomUiLevelBar`), индикатор популярности с пальцем вверх
 * (`RoomUiPopularity`) и ряд иконочных кнопок внизу. Мы используем те же
 * спрайты — они лежат в public/ui после `pnpm build:ui`.
 *
 * Текст поверх спрайтов позиционируется в процентах от картинки, поэтому HUD
 * тянется под ширину экрана без пиксельной подгонки.
 */

import { asset } from '../asset-url';
import { haptic } from '../telegram';

const UI = asset('ui');

/** Иконочная кнопка нижнего ряда: спрайт оригинала + состояние наведения. */
export function IconButton({
  icon,
  label,
  active = false,
  disabled = false,
  badge,
  onClick,
}: {
  /** Имя файла без расширения, например `btn-redecorate`. */
  icon: string;
  /** Подпись для screen reader и тултипа. */
  label: string;
  active?: boolean;
  disabled?: boolean;
  /** Маленькая плашка в углу — счётчик или «!». */
  badge?: string | number;
  onClick: () => void;
}): React.ReactElement {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      disabled={disabled}
      onClick={() => {
        haptic('light');
        onClick();
      }}
      className={`group relative shrink-0 w-11 h-11 grid place-items-center rounded-xl transition ${
        disabled
          ? 'opacity-35 cursor-not-allowed'
          : 'hover:bg-white/10 active:scale-95 cursor-pointer'
      } ${active ? 'bg-white/15 ring-2 ring-amber-300/70' : ''}`}
    >
      <img
        src={`${UI}/${icon}.png`}
        alt=""
        draggable={false}
        className="max-w-9 max-h-9 object-contain select-none"
      />
      {badge != null && (
        <span className="absolute -top-0.5 -right-0.5 min-w-4 h-4 px-1 grid place-items-center rounded-full bg-rose-500 text-white text-[10px] font-bold leading-none border border-rose-900/40">
          {badge}
        </span>
      )}
    </button>
  );
}

/**
 * Шкала уровня: золотой медальон с номером, тёмная полоса опыта и звёзды.
 * Порт RoomUiLevelBar — цифры в оригинале рисовались поверх того же спрайта.
 */
export function LevelBar({
  level,
  progress,
  points,
  toNext,
}: {
  level: number;
  /** Заполнение шкалы 0..1. */
  progress: number;
  points: number;
  /** Сколько очков до следующего уровня, null — максимум. */
  toNext: number | null;
}): React.ReactElement {
  return (
    <div
      className="relative select-none w-[168px] shrink-0"
      title={
        toNext === null
          ? 'Максимальный уровень'
          : `Гурман-очки: ${Math.round(points)}. До следующего уровня: ${toNext}`
      }
    >
      <img src={`${UI}/level-bar.png`} alt="" draggable={false} className="w-full h-auto" />

      {/*
       * У спрайта внутрь дорожки и в бейдж уровня зашиты рыбные значения
       * («10.000.000» и «99») — в оригинале поверх них лежали текстовые поля
       * tf_point и tf_level. Закрываем их плашками цвета дорожки и рисуем своё.
       */}
      <span className="absolute left-[22%] top-[13%] w-[54%] h-[40%] rounded-[3px] bg-[#141414]" />
      <span
        className="absolute left-[22.5%] top-[16%] h-[34%] rounded-[2px] bg-gradient-to-b from-emerald-300 to-emerald-500 transition-[width] duration-500"
        style={{ width: `${Math.max(0, Math.min(1, progress)) * 53}%` }}
      />
      <span className="absolute left-[22%] top-[13%] w-[54%] h-[40%] grid place-items-center text-[9px] font-bold text-white leading-none drop-shadow-[0_1px_0_rgba(0,0,0,0.8)]">
        {Math.round(points)}
      </span>

      {/* Бейдж уровня справа. */}
      <span className="absolute left-[76%] top-[8%] w-[19%] h-[44%] rounded-full bg-[#8e8e8e]" />
      <span className="absolute left-[76%] top-[8%] w-[19%] h-[44%] grid place-items-center text-[11px] font-bold text-white leading-none drop-shadow-[0_1px_0_rgba(0,0,0,0.5)]">
        {level}
      </span>
    </div>
  );
}

/**
 * Популярность: палец вверх и «спрос / потолок».
 * В оригинале число делилось на 10 — 550 очков показывались как 55.
 */
export function PopularityMeter({
  demand,
  maxDemand,
}: {
  demand: number;
  maxDemand: number;
}): React.ReactElement {
  return (
    <div
      className="flex items-center gap-1 select-none"
      title={`Популярность: ${demand} из ${maxDemand}. От неё зависит, как часто приходят гости.`}
    >
      <img src={`${UI}/popularity-icon.png`} alt="" draggable={false} className="h-6 w-auto" />
      <span className="whitespace-nowrap text-[11px] font-bold text-white drop-shadow-[0_1px_0_rgba(0,0,0,0.6)] tabular-nums">
        {(demand / 10).toFixed(1)} / {(maxDemand / 10).toFixed(0)}
      </span>
    </div>
  );
}

/** Счётчик валюты: спрайт монеты оригинала + число. */
export function CoinCounter({ coins }: { coins: number }): React.ReactElement {
  return (
    <div className="flex items-center gap-1.5 select-none" title="Монеты">
      <img src={`${UI}/coin.png`} alt="" draggable={false} className="w-6 h-6" />
      <span className="text-[13px] font-bold text-amber-100 drop-shadow-[0_1px_0_rgba(0,0,0,0.6)] tabular-nums">
        {coins}
      </span>
    </div>
  );
}

/** Полупрозрачная подложка нижнего ряда кнопок. */
export function ButtonRail({ children }: { children: React.ReactNode }): React.ReactElement {
  return (
    <div className="mx-auto w-fit max-w-full flex items-center gap-0.5 px-2 py-1 rounded-2xl bg-black/45 backdrop-blur-md border border-white/10 overflow-x-auto">
      {children}
    </div>
  );
}
