import { engine } from '@rv/shared';
import { useState } from 'react';
import { asset } from '../asset-url';
import type { SceneSnapshot } from '../game/scene';
import { haptic } from '../telegram';
import { EmployeePopUp, JOB_ICON, energyColor, formatTimeLeft, idleHint } from './EmployeePopUp';

const { JOB_LABELS, Job, nextEmployeeSlotLevel } = engine;

type Employee = engine.EmployeeSummary;

type Props = {
  roster: Employee[];
  candidates: engine.Candidate[];
  coins: number;
  level: number;
  maxEmployees: number;
  restaurantClosed: boolean;
  onSetJob: (id: string, job: engine.JobId) => void;
  onHire: (candidateId: string) => void;
  onFire: (id: string) => void;
  onFeed: (id: string, perkId: number) => void;
  onClose: () => void;
};

/**
 * Панель персонала — порт `EmployeeBar` (game_asset.swf) и логики
 * ui/WorldHiredFriendsPanel.as.
 *
 * В оригинале это лента карточек внизу экрана: занятые слоты показывали
 * портрет, должность и красные часы обратного отсчёта, свободные —
 * `EmployeeContainerEmpty` с кнопкой найма, а недоступные по уровню —
 * `EmployeeContainerUnlock` с замком. Клик по карточке открывал попап
 * назначения (EmployeePopUp), клик по пустому слоту вёл на биржу (WorldHire).
 *
 * Биржа у нас своя: друзей из Facebook заменил детерминированный пул
 * соискателей, всё остальное — как было.
 */
export function StaffPanel({
  roster,
  candidates,
  coins,
  level,
  maxEmployees,
  restaurantClosed,
  onSetJob,
  onHire,
  onFire,
  onFeed,
  onClose,
}: Props): React.ReactElement {
  const [openId, setOpenId] = useState<string | null>(null);
  const [hiring, setHiring] = useState(false);

  const selected = roster.find((e) => e.id === openId) ?? null;
  const freeSlots = Math.max(0, maxEmployees - roster.length);
  const unlockAt = nextEmployeeSlotLevel(level);

  const step = (delta: number): void => {
    if (!selected || roster.length === 0) return;
    const i = roster.findIndex((e) => e.id === selected.id);
    const next = roster[(i + delta + roster.length) % roster.length];
    if (next) setOpenId(next.id);
  };

  return (
    <>
      <div className="absolute bottom-0 left-0 right-0 p-2 pad-bottom-safe pointer-events-auto">
        <div className="mx-auto max-w-md rounded-2xl bg-[#141a22]/95 backdrop-blur-md border border-white/10 p-3 space-y-2">
          <div className="flex items-center gap-2">
            <img src={asset('ui/btn-hire.png')} alt="" draggable={false} className="w-5 h-4" />
            <div className="text-xs font-semibold">Сотрудники</div>
            <div className="text-[11px] opacity-50">
              {roster.length} / {maxEmployees}
            </div>
            <button
              type="button"
              onClick={onClose}
              className="ml-auto rounded-lg px-2.5 py-1 text-xs border border-white/15 hover:bg-white/5"
            >
              ✕
            </button>
          </div>

          {restaurantClosed && (
            <div className="rounded-xl bg-rose-500/15 border border-rose-400/30 px-2.5 py-1.5 text-[11px] leading-snug text-rose-100">
              Зал закрыт: гостей не будет, пока на смене нет повара и официанта с силами.
            </div>
          )}

          {hiring ? (
            <HireList
              candidates={candidates}
              canHire={freeSlots > 0}
              onHire={(id) => {
                onHire(id);
                if (freeSlots <= 1) setHiring(false);
              }}
              onBack={() => setHiring(false)}
            />
          ) : (
            <div className="flex gap-2 overflow-x-auto pb-1">
              {roster.map((employee) => (
                <StaffCard
                  key={employee.id}
                  employee={employee}
                  onClick={() => {
                    haptic('light');
                    setOpenId(employee.id);
                  }}
                />
              ))}

              {freeSlots > 0 && (
                <SlotCard
                  label="Нанять"
                  hint={`Свободно мест: ${freeSlots}`}
                  onClick={() => {
                    haptic('light');
                    setHiring(true);
                  }}
                />
              )}
              {freeSlots === 0 && unlockAt !== null && (
                <SlotCard label="🔒" hint={`Новое место с ${unlockAt} уровня`} />
              )}
            </div>
          )}

          {!hiring && (
            <div className="text-[11px] leading-snug opacity-60">
              Силы тратятся только на смене и восстанавливаются втрое быстрее на отдыхе — кровать
              ускоряет ещё. Выдохшийся сам не встанет: покормите его или отправьте спать.
            </div>
          )}
        </div>
      </div>

      {selected && (
        <EmployeePopUp
          employee={selected}
          coins={coins}
          onPrev={() => step(-1)}
          onNext={() => step(1)}
          onSetJob={onSetJob}
          onFeed={onFeed}
          onFire={(id) => {
            onFire(id);
            setOpenId(null);
          }}
          onClose={() => setOpenId(null)}
        />
      )}
    </>
  );
}

function StaffCard({
  employee,
  onClick,
}: {
  employee: Employee;
  onClick: () => void;
}): React.ReactElement {
  const percent = Math.round(employee.energy * 100);
  const hint = idleHint(employee);
  const alarm = employee.exhausted || employee.idleReason === 'needs-job';

  return (
    <button
      type="button"
      onClick={onClick}
      title={employee.name}
      className={`shrink-0 w-[104px] rounded-xl border p-2 space-y-1.5 text-left transition ${
        alarm
          ? 'border-rose-400/50 bg-rose-500/10'
          : employee.resting
            ? 'border-sky-400/40 bg-sky-400/5'
            : 'border-white/15 hover:bg-white/5'
      }`}
    >
      <div className="flex items-center gap-1.5">
        <img src={JOB_ICON[employee.job]} alt="" draggable={false} className="w-5 h-5" />
        <span className="text-[11px] font-semibold truncate">{JOB_LABELS[employee.job]}</span>
      </div>

      <div className="text-[10px] opacity-60 truncate">{employee.name}</div>

      {/* Обратный отсчёт рабочего времени — красные часы карточки оригинала. */}
      <div
        className={`font-mono text-[13px] font-bold tabular-nums text-center ${
          employee.exhausted ? 'text-rose-300' : ''
        }`}
      >
        {formatTimeLeft(employee.workTime)}
      </div>

      <div className="h-1.5 rounded-full bg-white/10 overflow-hidden">
        <div
          className={`h-full transition-[width] duration-500 ${energyColor(employee.energy)}`}
          style={{ width: `${percent}%` }}
        />
      </div>

      <div className="text-[10px] text-center opacity-60 truncate">
        {hint ?? (employee.busy ? 'работает' : 'ждёт')}
      </div>
    </button>
  );
}

function SlotCard({
  label,
  hint,
  onClick,
}: {
  label: string;
  hint: string;
  onClick?: () => void;
}): React.ReactElement {
  const interactive = onClick !== undefined;
  return (
    <button
      type="button"
      disabled={!interactive}
      onClick={onClick}
      className={`shrink-0 w-[104px] rounded-xl border border-dashed p-2 grid place-items-center gap-1 transition ${
        interactive
          ? 'border-emerald-400/40 text-emerald-200 hover:bg-emerald-400/10'
          : 'border-white/15 opacity-40'
      }`}
    >
      <span className="text-lg leading-none">{interactive ? '＋' : label}</span>
      <span className="text-[10px] leading-tight text-center opacity-80">{hint}</span>
    </button>
  );
}

/** Биржа труда — замена ленты друзей из WorldHire.as. */
function HireList({
  candidates,
  canHire,
  onHire,
  onBack,
}: {
  candidates: engine.Candidate[];
  canHire: boolean;
  onHire: (candidateId: string) => void;
  onBack: () => void;
}): React.ReactElement {
  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={onBack}
          className="rounded-lg px-2 py-0.5 text-[11px] border border-white/15 hover:bg-white/5"
        >
          ‹ Назад
        </button>
        <span className="text-[11px] opacity-60">
          Найм бесплатный, +{engine.Balance.GOURMET_POINTS_HIRE_EMPLOYEE} опыта
        </span>
      </div>

      <div className="max-h-48 overflow-y-auto space-y-1.5 pr-0.5">
        {candidates.map((candidate) => (
          <div
            key={candidate.id}
            className="flex items-center gap-2 rounded-xl border border-white/15 p-1.5"
          >
            {/* Вместо портрета — цвета его наряда: тот же человек выйдет в зал. */}
            <span
              className="shrink-0 w-7 h-7 rounded-full border border-white/20"
              style={{
                background: `linear-gradient(160deg, ${hex(candidate.look.skin)} 45%, ${hex(
                  candidate.look.shirtColor,
                )} 45%)`,
              }}
            />
            <span className="min-w-0 flex-1 text-xs truncate">{candidate.name}</span>
            <button
              type="button"
              disabled={!canHire}
              onClick={() => {
                haptic('medium');
                onHire(candidate.id);
              }}
              className={`shrink-0 rounded-lg px-2.5 py-1 text-[11px] font-semibold border transition ${
                canHire
                  ? 'border-emerald-400/50 text-emerald-200 hover:bg-emerald-400/10'
                  : 'border-white/10 opacity-40 cursor-not-allowed'
              }`}
            >
              Нанять
            </button>
          </div>
        ))}
      </div>

      {!canHire && (
        <div className="text-[11px] leading-snug text-amber-200/80">
          Свободных мест нет — поднимите уровень или увольте кого-нибудь.
        </div>
      )}
    </div>
  );
}

function hex(color: number): string {
  return `#${color.toString(16).padStart(6, '0')}`;
}
