import { useCallback, useEffect, useRef, useState } from 'react';
import { AvatarCustomizer } from './avatar/AvatarCustomizer';
import { hideBootSplash } from './boot-splash';
import {
  ACCENT_SWATCHES,
  BODY_SWATCHES,
  type FacadeConfig,
  ROOF_KINDS,
  ROOF_LABELS,
  loadFacadeConfig,
  saveFacadeConfig,
} from './game/facade-config';
import { resetPlayerState } from './game/player-state';
import type { SceneHandle, SceneSnapshot } from './game/scene';
import { startScene } from './game/scene';
import { type StreetHandle, startStreetScene } from './game/street-scene';
import { DebugPanel } from './ui/DebugPanel';
import { HUD } from './ui/HUD';
import { ItemChooser } from './ui/ItemChooser';
import { StaffPanel } from './ui/StaffPanel';
import { WelcomeBack } from './ui/WelcomeBack';

type Mode = 'restaurant' | 'street' | 'avatar';

/**
 * Короче этого отсутствия экран «пока вас не было» не показываем: перезагрузка
 * страницы или быстрый выход-вход не должны каждый раз ловить модалку.
 */
const WELCOME_MIN_AWAY_SEC = 5 * 60;

/** Почему не вышло действие с персоналом — коды приходят из движка. */
const HIRE_ERRORS: Record<string, string> = {
  'no-slots': 'Свободных мест нет — нужен уровень повыше',
  'no-coins': 'Не хватает монет',
  'not-found': 'Этого сотрудника уже нет',
};

export default function App(): React.ReactElement {
  const [mode, setMode] = useState<Mode>(() =>
    typeof window !== 'undefined' && window.location.search.includes('avatar')
      ? 'avatar'
      : 'restaurant',
  );

  if (mode === 'avatar') {
    return <AvatarCustomizer onClose={() => setMode('restaurant')} />;
  }
  if (mode === 'street') {
    return <StreetScreen onEnterRestaurant={() => setMode('restaurant')} />;
  }
  return <Game onShowAvatar={() => setMode('avatar')} onShowStreet={() => setMode('street')} />;
}

function Game({
  onShowAvatar,
  onShowStreet,
}: {
  onShowAvatar: () => void;
  onShowStreet: () => void;
}): React.ReactElement {
  const canvasMountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<SceneHandle | null>(null);
  const [snapshot, setSnapshot] = useState<SceneSnapshot | null>(null);
  const [shopOpen, setShopOpen] = useState(false);
  const [sellMode, setSellMode] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [staffOpen, setStaffOpen] = useState(false);
  const [debugOpen, setDebugOpen] = useState(false);
  /** Отчёт «пока вас не было» показываем один раз за сессию. */
  const [welcomeSeen, setWelcomeSeen] = useState(false);
  /** Размер зала из прошлого снимка — по нему ловим, что зал раздвинулся. */
  const roomSizeRef = useRef<string | null>(null);

  const designMode = snapshot?.designMode ?? false;
  // Магазин живёт только внутри дизайн-режима: если тот выключился (в том числе
  // при пересоздании сцены), панель статистики обязана вернуться.
  const shopVisible = designMode && shopOpen;
  // Панель сотрудников и магазин делят низ экрана — открыт всегда только один.
  const staffVisible = staffOpen && !shopVisible;

  /** Закрыть магазин и выйти из режима продажи (например, при выходе из дизайна). */
  const closeShop = (): void => {
    setShopOpen(false);
    setSellMode(false);
    sceneRef.current?.setSellMode(false);
  };

  /**
   * Короткое сообщение внизу экрана — общее для магазина и панели персонала.
   * useCallback ради стабильной ссылки: его зовёт эффект, поднимающий сцену, а
   * тот обязан отработать ровно один раз.
   */
  const showNotice = useCallback((text: string): void => {
    setNotice(text);
    window.setTimeout(() => setNotice(null), 2500);
  }, []);

  const buy = async (contentId: number): Promise<void> => {
    const res = await sceneRef.current?.buyItem(contentId);
    if (!res) return;
    showNotice(
      res.ok
        ? 'Куплено — перетащи на место'
        : res.reason === 'no-space'
          ? 'В зале нет свободного места'
          : res.reason === 'no-coins'
            ? 'Не хватает монет'
            : 'Не получилось поставить',
    );
  };

  useEffect(() => {
    const el = canvasMountRef.current;
    if (!el) return;

    let cancelled = false;
    let localHandle: SceneHandle | null = null;

    startScene(el, (snap) => {
      if (cancelled) return;
      setSnapshot(snap);
      // Зал растёт с уровнем сам по себе — без подписи это выглядит как
      // случайный скачок камеры.
      const size = `${snap.roomSize.width}×${snap.roomSize.height}`;
      if (roomSizeRef.current !== null && roomSizeRef.current !== size) {
        showNotice(`Зал стал больше — ${size}`);
      }
      roomSizeRef.current = size;
      // Первый снимок = зал уже нарисован, заставку можно убирать.
      hideBootSplash();
    })
      .then((handle) => {
        if (cancelled) {
          handle.destroy();
        } else {
          localHandle = handle;
          sceneRef.current = handle;
        }
      })
      .catch((err) => {
        console.error('startScene failed', err);
        // Сцена не поднялась — спиннер снимаем, иначе экран залипнет навсегда.
        hideBootSplash();
      });

    return () => {
      cancelled = true;
      sceneRef.current = null;
      localHandle?.destroy();
    };
  }, [showNotice]);

  return (
    <div className="relative w-screen h-dvh overflow-hidden">
      <div ref={canvasMountRef} className="absolute inset-0" />
      <HUD
        snapshot={snapshot}
        hideRail={shopVisible || staffVisible}
        shopOpen={shopVisible}
        staffOpen={staffVisible}
        onReset={() => sceneRef.current?.resetHall()}
        onToggleDesign={() => {
          const next = !designMode;
          sceneRef.current?.setDesignMode(next);
          if (!next) closeShop();
        }}
        onToggleShop={() => {
          if (shopOpen) closeShop();
          else {
            setStaffOpen(false);
            setShopOpen(true);
          }
        }}
        onToggleStaff={() => {
          setStaffOpen((v) => {
            if (!v) closeShop();
            return !v;
          });
        }}
        onShowAvatar={onShowAvatar}
        onShowStreet={onShowStreet}
      />
      {staffVisible && snapshot && (
        <StaffPanel
          roster={snapshot.roster}
          candidates={snapshot.candidates}
          coins={snapshot.coins}
          level={snapshot.level}
          maxEmployees={snapshot.staff.max}
          restaurantClosed={snapshot.restaurantClosed}
          onSetJob={(id, job) => sceneRef.current?.setEmployeeJob(id, job)}
          onHire={(candidateId) => {
            const res = sceneRef.current?.hireEmployee(candidateId);
            if (res && !res.ok) showNotice(HIRE_ERRORS[res.reason ?? ''] ?? 'Не вышло нанять');
          }}
          onFire={(id) => {
            const res = sceneRef.current?.fireEmployee(id);
            if (res && !res.ok) showNotice(HIRE_ERRORS[res.reason ?? ''] ?? 'Не вышло уволить');
          }}
          onFeed={(id, perkId) => {
            const res = sceneRef.current?.feedEmployee(id, perkId);
            if (res && !res.ok) showNotice(HIRE_ERRORS[res.reason ?? ''] ?? 'Не вышло покормить');
          }}
          onClose={() => setStaffOpen(false)}
        />
      )}
      {staffVisible && notice && (
        <div className="absolute bottom-56 left-0 right-0 flex justify-center pointer-events-none">
          <div className="rounded-full bg-black/70 px-3 py-1.5 text-xs">{notice}</div>
        </div>
      )}
      {/* Магазин и панель персонала показывают сообщение у себя; когда закрыты
          оба — показываем над нижним рядом кнопок. */}
      {notice && !staffVisible && !shopVisible && (
        <div className="absolute bottom-24 left-0 right-0 flex justify-center pointer-events-none">
          <div className="rounded-full bg-black/70 px-3 py-1.5 text-xs">{notice}</div>
        </div>
      )}
      {!welcomeSeen && snapshot && snapshot.offline.awaySeconds >= WELCOME_MIN_AWAY_SEC && (
        <WelcomeBack
          report={snapshot.offline}
          trash={snapshot.trash}
          onClose={() => setWelcomeSeen(true)}
        />
      )}
      {shopVisible && (
        <ItemChooser
          coins={snapshot?.coins ?? 0}
          level={snapshot?.level ?? 0}
          placed={snapshot?.placed ?? []}
          sellMode={sellMode}
          notice={notice}
          onToggleSellMode={(on) => {
            setSellMode(on);
            sceneRef.current?.setSellMode(on);
          }}
          onBuy={(contentId) => void buy(contentId)}
          onSell={(itemId) => sceneRef.current?.sellItem(itemId)}
          onClearRoom={() => sceneRef.current?.resetHall()}
          onClose={closeShop}
        />
      )}

      {/* Отладка: кнопка сбоку, панель по центру. В прод-сборке не рисуется. */}
      {import.meta.env.DEV && !debugOpen && (
        <button
          type="button"
          onClick={() => setDebugOpen(true)}
          title="Отладочная панель"
          className="absolute right-0 top-1/2 -translate-y-1/2 z-20 rounded-l-lg px-1.5 py-3 bg-amber-400/20 border border-r-0 border-amber-300/40 text-amber-200 text-[11px] font-bold hover:bg-amber-400/30"
        >
          DEV
        </button>
      )}
      {import.meta.env.DEV && debugOpen && (
        <DebugPanel
          snapshot={snapshot}
          onGrantCoins={(coins) => sceneRef.current?.debugGrant({ coins })}
          onGrantCash={(cash) => sceneRef.current?.debugGrant({ cash })}
          onSetLevel={(level) => sceneRef.current?.debugGrant({ level })}
          onGrantTrash={(trash) => sceneRef.current?.debugGrant({ trash })}
          onSetDemand={(demand) => sceneRef.current?.debugGrant({ demand })}
          onRefillStaff={() => sceneRef.current?.debugGrant({ refillStaff: true })}
          onReset={() => {
            resetPlayerState();
            window.location.reload();
          }}
          onClose={() => setDebugOpen(false)}
        />
      )}
    </div>
  );
}

function StreetScreen({
  onEnterRestaurant,
}: {
  onEnterRestaurant: () => void;
}): React.ReactElement {
  const mountRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<StreetHandle | null>(null);
  const [visit, setVisit] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [facade, setFacade] = useState<FacadeConfig>(() => loadFacadeConfig());

  // Сцена улицы поднимается один раз на монтирование: PixiJS-приложение
  // тяжёлое, пересоздавать его на смену колбэка нельзя.
  // biome-ignore lint/correctness/useExhaustiveDependencies: mount-only
  useEffect(() => {
    const el = mountRef.current;
    if (!el) return;
    let cancelled = false;
    startStreetScene(el, {
      onEnterRestaurant,
      onVisit: (name) => setVisit(name),
    })
      .then((h) => {
        if (cancelled) h.destroy();
        else handleRef.current = h;
      })
      .catch((err) => console.error('startStreetScene failed', err));
    return () => {
      cancelled = true;
      handleRef.current?.destroy();
      handleRef.current = null;
    };
  }, []);

  /** Применить правку фасада: обновить стейт + живой превью в сцене. */
  const patchFacade = (patch: Partial<FacadeConfig>): void => {
    setFacade((f) => {
      const next = { ...f, ...patch };
      handleRef.current?.setPlayerFacade(next);
      return next;
    });
  };

  return (
    <div className="relative w-screen h-dvh overflow-hidden">
      <div ref={mountRef} className="absolute inset-0" />

      {/* Верхняя плашка */}
      <div className="absolute top-0 left-0 right-0 p-3 flex items-center justify-between text-xs font-mono pointer-events-none">
        <div className="opacity-70">Restaurant Valley · улица</div>
        <div className="flex gap-2 pointer-events-auto">
          <button
            type="button"
            onClick={() => setEditing((v) => !v)}
            className={`rounded-lg px-3 py-1.5 border transition ${
              editing
                ? 'bg-emerald-500/20 border-emerald-400/60 text-emerald-200'
                : 'bg-black/40 border-white/20 hover:bg-white/10'
            }`}
          >
            ✎ Экстерьер
          </button>
          <button
            type="button"
            onClick={onEnterRestaurant}
            className="rounded-lg px-3 py-1.5 bg-black/40 border border-white/20 hover:bg-white/10"
          >
            В ресторан →
          </button>
        </div>
      </div>

      {/* Редактор экстерьера */}
      {editing && (
        <div className="absolute bottom-0 left-0 right-0 p-3 pad-bottom-safe-lg bg-black/50 backdrop-blur-md space-y-2 text-xs">
          <div className="flex items-center gap-2">
            <span className="opacity-60 shrink-0">Название</span>
            <input
              value={facade.name}
              onChange={(e) => patchFacade({ name: e.target.value })}
              maxLength={24}
              className="flex-1 min-w-0 rounded-lg bg-white/10 border border-white/20 px-2 py-1.5 text-sm outline-none focus:border-white/50"
            />
            <button
              type="button"
              onClick={() => {
                saveFacadeConfig(facade);
                setEditing(false);
              }}
              className="shrink-0 rounded-lg px-3 py-1.5 bg-emerald-500/20 border border-emerald-400/50 text-emerald-200 font-semibold"
            >
              Сохранить
            </button>
          </div>

          <div>
            <div className="opacity-60 mb-1">Крыша</div>
            <div className="flex gap-1.5 overflow-x-auto pb-1">
              {ROOF_KINDS.map((r) => (
                <button
                  key={r}
                  type="button"
                  onClick={() => patchFacade({ roof: r })}
                  className={`shrink-0 rounded-lg px-3 py-1.5 font-semibold border transition ${
                    facade.roof === r
                      ? 'bg-white/15 border-white/50'
                      : 'border-white/15 hover:bg-white/5'
                  }`}
                >
                  {ROOF_LABELS[r]}
                </button>
              ))}
            </div>
          </div>

          <div className="flex gap-4">
            <div>
              <div className="opacity-60 mb-1">Стены</div>
              <div className="flex gap-1.5">
                {BODY_SWATCHES.map((c) => (
                  <Swatch
                    key={c}
                    color={c}
                    active={facade.bodyColor === c}
                    onClick={() => patchFacade({ bodyColor: c })}
                  />
                ))}
              </div>
            </div>
            <div>
              <div className="opacity-60 mb-1">Акцент</div>
              <div className="flex gap-1.5">
                {ACCENT_SWATCHES.map((c) => (
                  <Swatch
                    key={c}
                    color={c}
                    active={facade.accentColor === c}
                    onClick={() => patchFacade({ accentColor: c })}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Визит к соседу (заглушка S2) */}
      {visit && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/40 p-4">
          <div className="max-w-sm w-full rounded-2xl bg-[#161c24] border border-white/15 p-4 space-y-3 text-center">
            <div className="text-sm opacity-70">Визит к соседу</div>
            <div className="text-lg font-semibold">{visit}</div>
            <div className="text-xs opacity-60">Оценить ресторан и полить сад — скоро (S2).</div>
            <div className="flex gap-2 justify-center pt-1">
              <button
                type="button"
                disabled
                className="rounded-xl px-3 py-2 text-sm font-semibold bg-amber-400/15 border border-amber-300/30 text-amber-200/60 cursor-not-allowed"
              >
                ★ Оценить
              </button>
              <button
                type="button"
                disabled
                className="rounded-xl px-3 py-2 text-sm font-semibold bg-emerald-400/15 border border-emerald-300/30 text-emerald-200/60 cursor-not-allowed"
              >
                💧 Полить сад
              </button>
              <button
                type="button"
                onClick={() => setVisit(null)}
                className="rounded-xl px-3 py-2 text-sm font-semibold border border-white/20 hover:bg-white/5"
              >
                Уйти
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Swatch({
  color,
  active,
  onClick,
}: {
  color: number;
  active: boolean;
  onClick: () => void;
}): React.ReactElement {
  const hex = `#${color.toString(16).padStart(6, '0')}`;
  return (
    <button
      type="button"
      onClick={onClick}
      title={hex}
      style={{ backgroundColor: hex }}
      className={`shrink-0 w-8 h-8 rounded-full border-2 transition ${
        active ? 'border-white scale-110' : 'border-white/30 hover:border-white/60'
      }`}
    />
  );
}
