/**
 * Мусор в зале — порт trash-механики WorldRestaurantPlay
 * (`addRandomTrash` :1313, `addTrashObject` :2094, `removeTrashObject` :2383).
 *
 * Как это работает в оригинале:
 *   - раз в TRASH_APPEAR_RATE (час ± минута) «долг по мусору» растёт на 1,
 *     потолок MAX_TRASH = 15; счётчик копится и пока игрока нет в игре;
 *   - симуляция досыпает на пол недостающие мусорки на случайные проходимые
 *     клетки без мусора;
 *   - гость у входа бросает кубик `rnd(0, 20) < trashCount` и с грязным залом
 *     разворачивается (STATE_TOO_MUCH_TRASH → уходит недовольным);
 *   - убранный мусор ДАЁТ монеты и опыт — это не штраф, а мини-награда за
 *     возвращение в игру.
 *
 * Мусор не блокирует ходьбу: это объект на полу, а не мебель.
 */

import type { TileCoord } from '../grid';
import { Balance } from './balance';

/** Виды мусора — DEFAULT_TRASH_ITEMS оригинала. */
export const TRASH_KINDS = [
  'BananaPeel',
  'PizzaSlice',
  'SodaCan',
  'ChickenLeg',
  'AppleCore',
] as const;

export type TrashKind = (typeof TRASH_KINDS)[number];

export type TrashItem = {
  readonly id: string;
  readonly kind: TrashKind;
  readonly tileX: number;
  readonly tileY: number;
  /** id уборщика, который уже идёт за этой мусоркой (иначе null). */
  claimedBy: string | null;
};

/** Сериализуемое состояние: сколько мусора «должно» быть и что лежит на полу. */
export type TrashState = {
  target: number;
  timerMs: number;
  items: Array<{ kind: TrashKind; tileX: number; tileY: number }>;
};

/** Что системе нужно от мира, чтобы выбрать клетку под мусор. */
export type TrashWorld = {
  readonly width: number;
  readonly height: number;
  isWalkable(x: number, y: number): boolean;
};

let trashSeq = 0;

export class TrashSystem {
  readonly items: TrashItem[] = [];

  /** Сколько мусорок «должно» лежать (растёт по таймеру, в т.ч. офлайн). */
  private target = 0;
  private timerMs: number;

  constructor(
    state: Partial<TrashState> | null | undefined,
    private readonly rand: (min: number, max: number) => number,
  ) {
    this.target = Math.max(0, Math.min(state?.target ?? 0, Balance.MAX_TRASH));
    this.timerMs = state?.timerMs ?? this.nextInterval();
    for (const raw of state?.items ?? []) {
      if (!TRASH_KINDS.includes(raw.kind)) continue;
      trashSeq++;
      this.items.push({
        id: `trash-${trashSeq}`,
        kind: raw.kind,
        tileX: raw.tileX,
        tileY: raw.tileY,
        claimedBy: null,
      });
    }
  }

  get count(): number {
    return this.items.length;
  }

  /** Сколько мусора ещё не материализовано (не хватило места на полу). */
  get pending(): number {
    return Math.max(0, this.target - this.items.length);
  }

  private nextInterval(): number {
    const d = Balance.TRASH_APPEAR_RATE_RANDOM_DELTA_MS;
    return Balance.TRASH_APPEAR_RATE_MS + this.rand(-d, d);
  }

  /**
   * Начислить мусор за время, пока игра была закрыта. Порт
   * `tickOfflineTimeForUser`: за каждый прошедший интервал +1, но не выше
   * потолка.
   */
  accrueOffline(elapsedMs: number): number {
    if (elapsedMs <= 0) return 0;
    const before = this.target;
    const added = Math.floor(elapsedMs / Balance.TRASH_APPEAR_RATE_MS);
    this.target = Math.min(this.target + added, Balance.MAX_TRASH);
    return this.target - before;
  }

  /** Тик: копим долг по таймеру и досыпаем недостающее на пол. */
  tick(dtMs: number, world: TrashWorld): TrashItem[] {
    this.timerMs -= dtMs;
    if (this.timerMs <= 0) {
      this.timerMs = this.nextInterval();
      this.target = Math.min(this.target + 1, Balance.MAX_TRASH);
    }
    const spawned: TrashItem[] = [];
    while (this.items.length < this.target) {
      const item = this.spawnOne(world);
      if (!item) break; // свободных клеток не осталось
      spawned.push(item);
    }
    return spawned;
  }

  /** Положить одну мусорку на случайную свободную проходимую клетку. */
  spawnOne(world: TrashWorld): TrashItem | null {
    const free: TileCoord[] = [];
    for (let y = 0; y < world.height; y++) {
      for (let x = 0; x < world.width; x++) {
        if (!world.isWalkable(x, y)) continue;
        if (this.at(x, y)) continue;
        free.push({ x, y });
      }
    }
    if (free.length === 0) return null;
    const tile = free[this.rand(0, free.length - 1)]!;
    const kind = TRASH_KINDS[this.rand(0, TRASH_KINDS.length - 1)] ?? 'BananaPeel';
    trashSeq++;
    const item: TrashItem = {
      id: `trash-${trashSeq}`,
      kind,
      tileX: tile.x,
      tileY: tile.y,
      claimedBy: null,
    };
    this.items.push(item);
    // Долг не может быть меньше того, что уже лежит (важно при ручном спавне).
    this.target = Math.max(this.target, this.items.length);
    return item;
  }

  at(x: number, y: number): TrashItem | null {
    return this.items.find((t) => t.tileX === x && t.tileY === y) ?? null;
  }

  byId(id: string): TrashItem | null {
    return this.items.find((t) => t.id === id) ?? null;
  }

  /** Забронировать мусорку за уборщиком. false — её уже кто-то взял. */
  claim(item: TrashItem, by: string): boolean {
    if (item.claimedBy !== null && item.claimedBy !== by) return false;
    item.claimedBy = by;
    return true;
  }

  release(item: TrashItem): void {
    item.claimedBy = null;
  }

  /** Ближайшая (по манхэттену) незанятая мусорка. */
  nearestFree(fromX: number, fromY: number): TrashItem | null {
    let best: TrashItem | null = null;
    let bestDist = Number.POSITIVE_INFINITY;
    for (const item of this.items) {
      if (item.claimedBy !== null) continue;
      const dist = Math.abs(item.tileX - fromX) + Math.abs(item.tileY - fromY);
      if (dist < bestDist) {
        best = item;
        bestDist = dist;
      }
    }
    return best;
  }

  /** Убрать мусорку с пола (и списать долг). */
  remove(item: TrashItem): boolean {
    const i = this.items.indexOf(item);
    if (i < 0) return false;
    this.items.splice(i, 1);
    this.target = Math.max(0, this.target - 1);
    return true;
  }

  clearAll(): void {
    this.items.length = 0;
    this.target = 0;
  }

  toJSON(): TrashState {
    return {
      target: this.target,
      timerMs: this.timerMs,
      items: this.items.map((t) => ({ kind: t.kind, tileX: t.tileX, tileY: t.tileY })),
    };
  }
}
