/**
 * Порт com/playfish/games/cooking/PathFinder.as.
 *
 * A*-поиск на тайл-сетке с 8-направленным движением.
 * Score'ы из оригинала: STRAIGHT = 10, DIAGONAL = 14
 * (приближение √2≈1.4 в целых, чтобы избежать дрейфа от плавающей арифметики).
 *
 * Эвристика: Манхэттен × 10. Не учитывает диагонали — слегка переоценённая,
 * но это поведение оригинала (и в RC оно даёт «жадные» пути,
 * визуально похожие на NPC-движение).
 *
 * Изначальная реализация была шаговой (processOpenList(steps)) — клиент
 * мог расходовать время на поиск по N узлов за кадр. Сохраняем эту возможность
 * (см. PathFinder.processOpenList(maxIterations)), но добавляем удобный
 * findPath() который проводит поиск целиком.
 */

import { type TileCoord, tile } from './grid';

export type WalkabilityChecker = {
  /**
   * Возвращает true, если допустимо шагнуть с тайла (fromX, fromY) на (toX, toY).
   *
   * Параметр isDestination: true когда (toX, toY) — конечный тайл назначения.
   * Оригинал использовал это для специальной логики «стоп рядом с целью» —
   * например, посетитель идёт К стулу, но не НА него.
   *
   * Параметр allowOccupiedByActor: true разрешает шаг на тайл, где сейчас стоит другой actor
   * (но не стационарный предмет). В оригинале это `WorldRestaurant.isWalkableFrom(..., ignoreActors)`.
   */
  isWalkableFrom(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    isDestination: boolean,
    allowOccupiedByActor: boolean,
  ): boolean;
};

export enum PathfinderResult {
  NoPath = 0,
  Processing = 1,
  Found = 2,
}

enum NodeState {
  Available = 0,
  Open = 1,
  Closed = 2,
}

type PathFinderNode = {
  x: number;
  y: number;
  parent: PathFinderNode | null;
  g: number; // cost so far
  fScore: number; // g + heuristic
  state: NodeState;
};

const STRAIGHT_SCORE = 10;
const DIAGONAL_SCORE = 14;

export type PathfinderOptions = {
  /** Ширина сетки в тайлах (для размера node-state-map). */
  width: number;
  /** Высота сетки в тайлах. */
  height: number;
  start: TileCoord;
  destination: TileCoord;
  walkability: WalkabilityChecker;
  /**
   * Если true — поиск завершается, как только дошли до тайла РЯДОМ с destination
   * (используется когда destination — стационарный предмет: посетитель не должен
   * наступать на стул, а должен стоять перед ним).
   */
  stopNextToDestination?: boolean;
};

export class PathFinder {
  private readonly width: number;
  private readonly height: number;
  private readonly startX: number;
  private readonly startY: number;
  private readonly destX: number;
  private readonly destY: number;
  private readonly stopNextToDest: boolean;
  private readonly walkability: WalkabilityChecker;

  /** Отсортирован по возрастанию fScore (как в оригинале). */
  private readonly openList: PathFinderNode[] = [];
  private readonly nodeMap: (PathFinderNode | null)[][];

  constructor(opts: PathfinderOptions) {
    this.width = opts.width;
    this.height = opts.height;
    this.startX = opts.start.x;
    this.startY = opts.start.y;
    this.destX = opts.destination.x;
    this.destY = opts.destination.y;
    this.stopNextToDest = opts.stopNextToDestination ?? false;
    this.walkability = opts.walkability;

    this.nodeMap = new Array(this.width);
    for (let x = 0; x < this.width; x++) {
      this.nodeMap[x] = new Array(this.height).fill(null);
    }

    const start: PathFinderNode = {
      x: this.startX,
      y: this.startY,
      parent: null,
      g: 0,
      fScore: 0,
      state: NodeState.Open,
    };
    this.openList.push(start);
    this.nodeMap[this.startX]![this.startY] = start;
  }

  /**
   * Шаговый поиск. Передай maxIterations, чтобы распределить вычисления
   * между кадрами. -1 = до результата.
   */
  processOpenList(maxIterations: number): PathfinderResult {
    let remaining = maxIterations;
    while (maxIterations === -1 || remaining-- > 0) {
      if (this.openList.length === 0) return PathfinderResult.NoPath;

      const current = this.openList[0]!;
      if (current.x === this.destX && current.y === this.destY) {
        return PathfinderResult.Found;
      }

      // Помечаем как closed и снимаем с openList.
      current.state = NodeState.Closed;
      this.openList.shift();

      this.expandNeighbors(current);
    }
    return PathfinderResult.Processing;
  }

  /** Удобная обёртка: ищет путь полностью и возвращает массив тайлов. null если не найден. */
  findPath(): TileCoord[] | null {
    const result = this.processOpenList(-1);
    if (result !== PathfinderResult.Found) return null;
    return this.reconstructPath();
  }

  /**
   * Возвращает найденный путь как массив тайлов от тайла-после-старта до цели
   * (стартовый тайл не включается — посетитель уже на нём). null если поиск
   * не завершился успехом.
   *
   * Это поведение getFinalPath() из оригинала: путь не содержит стартовую точку,
   * а первый элемент — следующий шаг.
   */
  reconstructPath(): TileCoord[] | null {
    const head = this.openList[0];
    if (!head || head.x !== this.destX || head.y !== this.destY) {
      return null;
    }
    const path: TileCoord[] = [];
    let node: PathFinderNode | null = head;
    while (node && node.parent !== null) {
      path.unshift(tile(node.x, node.y));
      node = node.parent;
    }
    return path;
  }

  // ────────────────────────────────────────────────────────────────────────

  private heuristic(x: number, y: number): number {
    return (Math.abs(this.destX - x) + Math.abs(this.destY - y)) * STRAIGHT_SCORE;
  }

  private isValidStep(fromX: number, fromY: number, toX: number, toY: number): boolean {
    if (toX === this.destX && toY === this.destY) {
      if (this.stopNextToDest) return true;
      return this.walkability.isWalkableFrom(fromX, fromY, toX, toY, true, false);
    }
    return this.walkability.isWalkableFrom(fromX, fromY, toX, toY, false, false);
  }

  private expandNeighbors(node: PathFinderNode): void {
    const cx = node.x;
    const cy = node.y;

    for (let nx = cx - 1; nx <= cx + 1; nx++) {
      if (nx < 0 || nx >= this.width) continue;

      for (let ny = cy - 1; ny <= cy + 1; ny++) {
        if (ny < 0 || ny >= this.height) continue;
        if (nx === cx && ny === cy) continue; // сам себе не сосед

        // noUncheckedIndexedAccess добавляет undefined в indexed access — нормализуем к null.
        const existing = this.nodeMap[nx]![ny] ?? null;
        const isStraight = nx === cx || ny === cy;
        const stepCost = isStraight ? STRAIGHT_SCORE : DIAGONAL_SCORE;
        const tentativeG = node.g + stepCost;

        if (existing === null) {
          if (!this.isValidStep(cx, cy, nx, ny)) continue;
          const h = this.heuristic(nx, ny);
          const fresh: PathFinderNode = {
            x: nx,
            y: ny,
            parent: node,
            g: tentativeG,
            fScore: tentativeG + h,
            state: NodeState.Open,
          };
          this.insertSorted(fresh);
          this.nodeMap[nx]![ny] = fresh;
        } else if (existing.state === NodeState.Open) {
          if (tentativeG < existing.g) {
            existing.g = tentativeG;
            existing.fScore = tentativeG + this.heuristic(nx, ny);
            existing.parent = node;
            // Заметка: оригинал НЕ пересортировывал openList после обновления fScore.
            // Сохраняем эту неточность для эквивалентности поведения. Для большинства
            // карт RC она не давала видимых отличий.
          }
        }
        // existing.state === Closed → пропускаем, как в оригинале.
      }
    }
  }

  /** Вставка с сохранением сортировки по возрастанию fScore. O(N), как в оригинале. */
  private insertSorted(node: PathFinderNode): void {
    for (let i = 0; i < this.openList.length; i++) {
      if (node.fScore <= this.openList[i]!.fScore) {
        this.openList.splice(i, 0, node);
        return;
      }
    }
    this.openList.push(node);
  }
}

// ────────────────────────────────────────────────────────────────────────
// Удобный фронт для типичного случая использования.
// ────────────────────────────────────────────────────────────────────────

export function findPath(opts: PathfinderOptions): TileCoord[] | null {
  return new PathFinder(opts).findPath();
}
