/**
 * Визуальные эффекты интерьера: пузыри над гостями, тарелки на столах,
 * всплывающие деньги и «популярность», дым и свечение плиты.
 *
 * Все ассеты — реальные из game_asset.swf. Класс не принимает игровых решений:
 * сцена говорит ему, что показать, он это рисует и анимирует.
 */

import { Container, Graphics, Sprite, Text, type Texture } from 'pixi.js';
import { DEPTH_BIAS, TILE_H, isoDepth, tileToScreen } from './iso';

export type FxTextures = {
  bubble: Texture;
  plate: Texture;
  popularity: Texture;
  coin: Texture;
  /** 15 кадров вращения монеты (MoneyBill) — для россыпи за уборку мусора. */
  coinFrames: Texture[];
  /** 8 иконок эмоций в порядке CustomerEmotion. */
  emotions: Texture[];
};

/** Одна тарелка на столе: полная (гость ест) или грязная (ждёт уборки). */
export type PlateView = {
  key: string;
  tileX: number;
  tileY: number;
  dirty: boolean;
  /** Высота столешницы над полом, px — тарелка кладётся на неё, а не на клетку. */
  lift: number;
};

type Float = {
  node: Container;
  vy: number;
  life: number;
  maxLife: number;
};

type Puff = { g: Graphics; vy: number; life: number; maxLife: number; r: number };

/** Монетка из россыпи: летит по параболе, подпрыгивает и исчезает. */
type Coin = {
  sprite: Sprite;
  x: number;
  y: number;
  vx: number;
  vy: number;
  z: number;
  vz: number;
  life: number;
  frame: number;
  frameTimer: number;
};

export class InteriorFx {
  private readonly bubbles = new Map<string, { container: Container; icon: Sprite }>();
  private readonly plates = new Map<string, Sprite>();
  private readonly floats: Float[] = [];
  private readonly puffs: Puff[] = [];
  private readonly coins: Coin[] = [];

  private stoveScreen: { x: number; y: number } | null = null;
  private readonly stoveGlow: Graphics;
  private smokeTimer = 0;

  constructor(
    /** Слой над акторами: пузыри, дым, свечение. */
    private readonly fxLayer: Container,
    /** Сортируемый слой: тарелки перекрываются проходящими персонажами. */
    private readonly sortLayer: Container,
    /** Слой поверх всего: всплывающие деньги и популярность. */
    private readonly overlay: Container,
    private readonly tex: FxTextures,
  ) {
    this.stoveGlow = new Graphics();
    this.stoveGlow.circle(0, 0, 24).fill({ color: 0xffa53b, alpha: 0.5 });
    this.stoveGlow.alpha = 0;
    this.fxLayer.addChild(this.stoveGlow);
  }

  /** Где стоит плита (для дыма и свечения). null — плиты нет. */
  setStove(tile: { x: number; y: number } | null): void {
    if (!tile) {
      this.stoveScreen = null;
      this.stoveGlow.visible = false;
      return;
    }
    const s = tileToScreen(tile.x, tile.y);
    this.stoveScreen = { x: s.x, y: s.y + TILE_H / 2 };
    this.stoveGlow.position.set(this.stoveScreen.x, this.stoveScreen.y - 10);
    this.stoveGlow.visible = true;
  }

  // ── Пузыри над головой ────────────────────────────────────────────

  /** Показать пузырь с иконкой. tex === null — спрятать. */
  setBubble(key: string, cx: number, cy: number, depth: number, icon: Texture | null): void {
    if (!icon) {
      const existing = this.bubbles.get(key);
      if (existing) existing.container.visible = false;
      return;
    }
    let bubble = this.bubbles.get(key);
    if (!bubble) {
      const container = new Container();
      const bg = new Sprite(this.tex.bubble);
      bg.anchor.set(0.5, 1);
      bg.scale.set(0.9);
      const iconSprite = new Sprite(icon);
      iconSprite.anchor.set(0.5, 0.5);
      iconSprite.position.set(0, -38);
      container.addChild(bg, iconSprite);
      this.fxLayer.addChild(container);
      bubble = { container, icon: iconSprite };
      this.bubbles.set(key, bubble);
    }
    bubble.icon.texture = icon;
    bubble.icon.scale.set(26 / Math.max(icon.width, icon.height));
    bubble.container.position.set(cx, cy - 132);
    bubble.container.zIndex = depth;
    bubble.container.visible = true;
  }

  removeBubble(key: string): void {
    const bubble = this.bubbles.get(key);
    if (!bubble) return;
    this.fxLayer.removeChild(bubble.container);
    bubble.container.destroy({ children: true });
    this.bubbles.delete(key);
  }

  // ── Тарелки на столах ─────────────────────────────────────────────

  /**
   * Синхронизировать набор тарелок с переданным списком: чего нет в списке —
   * убираем, чего не хватает — создаём. Тарелка живёт в сортируемом слое, чтобы
   * её перекрывали проходящие мимо персонажи, как перекрывает стол.
   */
  syncPlates(views: PlateView[]): void {
    const alive = new Set(views.map((v) => v.key));
    for (const [key, sprite] of this.plates) {
      if (alive.has(key)) continue;
      this.sortLayer.removeChild(sprite);
      sprite.destroy();
      this.plates.delete(key);
    }
    for (const view of views) {
      let sprite = this.plates.get(view.key);
      if (!sprite) {
        sprite = new Sprite(this.tex.plate);
        sprite.anchor.set(0.5, 0.5);
        sprite.scale.set(0.85);
        this.sortLayer.addChild(sprite);
        this.plates.set(view.key, sprite);
      }
      const t = tileToScreen(view.tileX, view.tileY);
      // Центр клетки стола, поднятый на высоту столешницы — порт
      // Waitor.as:337 (getScreenY + tileHeightHalf - getTileTopHeight).
      sprite.position.set(t.x, t.y + TILE_H / 2 - view.lift);
      sprite.zIndex = isoDepth(view.tileX, view.tileY) + DEPTH_BIAS.plate;
      // Грязная тарелка тусклее — видно, что стол требует уборки.
      sprite.tint = view.dirty ? 0x9aa3ad : 0xffffff;
      sprite.alpha = view.dirty ? 0.85 : 1;
    }
  }

  // ── Всплывающие подписи ───────────────────────────────────────────

  /**
   * «+$N» с иконкой монеты — как всплывашка Money в оригинале (mc_plate +
   * tf_money). Появляется там, где официант убрал тарелку.
   */
  spawnMoney(sx: number, sy: number, amount: number): void {
    const node = new Container();
    const coin = new Sprite(this.tex.coin);
    coin.anchor.set(1, 0.5);
    coin.scale.set(0.55);
    coin.position.set(-3, 0);
    const label = new Text({
      text: `+$${amount}`,
      style: {
        fill: 0xffd85e,
        fontSize: 15,
        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
        fontWeight: '700',
        stroke: { color: 0x21160a, width: 3 },
      },
    });
    label.anchor.set(0, 0.5);
    node.addChild(coin, label);
    node.position.set(sx - 8, sy);
    this.overlay.addChild(node);
    this.floats.push({ node, vy: 0.55, life: 1400, maxLife: 1400 });
  }

  /**
   * Россыпь монет — в оригинале так падали деньги за тряску дерева, полив сада
   * друга и УБОРКУ МУСОРА (`removeTrashObject` :2403). Монеты некликабельны:
   * деньги начисляются сразу, это чистая анимация (Coin.as, mouseEnabled=false).
   */
  spawnCoinBurst(sx: number, sy: number, count: number): void {
    const frames = this.tex.coinFrames.length > 0 ? this.tex.coinFrames : [this.tex.coin];
    for (let i = 0; i < Math.max(1, Math.min(8, count)); i++) {
      const frame = Math.floor(Math.random() * frames.length);
      const sprite = new Sprite(frames[frame]);
      sprite.anchor.set(0.5, 0.5);
      sprite.scale.set(0.8);
      this.overlay.addChild(sprite);
      this.coins.push({
        sprite,
        x: sx + (Math.random() * 2 - 1) * 6,
        y: sy,
        vx: (Math.random() * 2 - 1) * 0.9,
        vy: (Math.random() * 2 - 1) * 0.4,
        z: 0,
        vz: 2.6 + Math.random() * 1.4,
        life: 1500,
        frame,
        frameTimer: 55,
      });
    }
  }

  /** Иконка популярности — гость ушёл довольным. */
  spawnPopularity(sx: number, sy: number): void {
    const node = new Container();
    const s = new Sprite(this.tex.popularity);
    s.anchor.set(0.5, 1);
    s.scale.set(0.5);
    node.addChild(s);
    node.position.set(sx, sy);
    this.overlay.addChild(node);
    this.floats.push({ node, vy: 0.5, life: 1200, maxLife: 1200 });
  }

  // ── Кадр ──────────────────────────────────────────────────────────

  update(dtMs: number, cooking: boolean): void {
    this.updateFloats(dtMs);
    this.updateCoins(dtMs);
    this.updateSmoke(dtMs, cooking);
  }

  /** Физика россыпи: гравитация, затухающий отскок, вращение кадрами ассета. */
  private updateCoins(dtMs: number): void {
    const f = dtMs / 16.67;
    const frames = this.tex.coinFrames.length > 0 ? this.tex.coinFrames : [this.tex.coin];
    for (let i = this.coins.length - 1; i >= 0; i--) {
      const c = this.coins[i]!;
      c.x += c.vx * f;
      c.y += c.vy * f;
      c.z += c.vz * f;
      c.vz -= 0.35 * f;
      if (c.z <= 0) {
        c.z = 0;
        c.vz = Math.abs(c.vz) < 1.4 ? 0 : -c.vz * 0.45;
      }
      c.frameTimer -= dtMs;
      if (c.frameTimer <= 0) {
        c.frameTimer = 55;
        c.frame = (c.frame + 1) % frames.length;
        c.sprite.texture = frames[c.frame]!;
      }
      c.life -= dtMs;
      c.sprite.position.set(c.x, c.y - c.z * 5);
      c.sprite.alpha = Math.max(0, Math.min(1, c.life / 400));
      if (c.life <= 0) {
        this.overlay.removeChild(c.sprite);
        c.sprite.destroy();
        this.coins.splice(i, 1);
      }
    }
  }

  private updateFloats(dtMs: number): void {
    const f = dtMs / 16.67;
    for (let i = this.floats.length - 1; i >= 0; i--) {
      const fl = this.floats[i]!;
      fl.node.y -= fl.vy * f;
      fl.life -= dtMs;
      fl.node.alpha = Math.max(0, Math.min(1, (fl.life / fl.maxLife) * 1.4));
      if (fl.life <= 0) {
        this.overlay.removeChild(fl.node);
        fl.node.destroy({ children: true });
        this.floats.splice(i, 1);
      }
    }
  }

  private updateSmoke(dtMs: number, cooking: boolean): void {
    this.stoveGlow.alpha += ((cooking ? 0.55 : 0) - this.stoveGlow.alpha) * Math.min(1, dtMs / 200);
    if (cooking && this.stoveScreen) {
      this.smokeTimer -= dtMs;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = 280;
        this.emitSmoke();
      }
    }
    const f = dtMs / 16.67;
    for (let i = this.puffs.length - 1; i >= 0; i--) {
      const p = this.puffs[i]!;
      p.g.y -= p.vy * f;
      const t = 1 - p.life / p.maxLife;
      p.g.scale.set(0.4 + t * p.r);
      p.g.alpha = (1 - t) * 0.5;
      p.life -= dtMs;
      if (p.life <= 0) {
        this.fxLayer.removeChild(p.g);
        p.g.destroy();
        this.puffs.splice(i, 1);
      }
    }
  }

  private emitSmoke(): void {
    const stove = this.stoveScreen;
    if (!stove) return;
    const g = new Graphics();
    g.circle(0, 0, 1).fill({ color: 0xe8e8ea });
    g.position.set(stove.x + (Math.random() * 2 - 1) * 6, stove.y - 18);
    this.fxLayer.addChild(g);
    this.puffs.push({
      g,
      vy: 0.5 + Math.random() * 0.3,
      life: 1400,
      maxLife: 1400,
      r: 4 + Math.random() * 3,
    });
  }

  /** Убрать все эффекты (вход в дизайн-режим). */
  clear(): void {
    for (const key of [...this.bubbles.keys()]) this.removeBubble(key);
    this.syncPlates([]);
    for (const fl of this.floats) {
      this.overlay.removeChild(fl.node);
      fl.node.destroy({ children: true });
    }
    this.floats.length = 0;
    for (const c of this.coins) {
      this.overlay.removeChild(c.sprite);
      c.sprite.destroy();
    }
    this.coins.length = 0;
    for (const p of this.puffs) {
      this.fxLayer.removeChild(p.g);
      p.g.destroy();
    }
    this.puffs.length = 0;
    this.stoveGlow.alpha = 0;
    this.smokeTimer = 0;
  }
}
