/**
 * Путь к статическому ассету с учётом базы сборки.
 *
 * На дев-сервере приложение живёт в корне, а на GitHub Pages — в подпапке
 * `/<repo>/`. Абсолютные пути вида `/ui/coin.png` в подпапке ведут в никуда,
 * поэтому всё, что грузится в рантайме (спрайты, звуки, модель аватара),
 * обязано проходить через эту функцию.
 *
 * Ассеты, на которые есть `import`, Vite переписывает сам — их сюда нести не надо.
 */
const BASE = import.meta.env.BASE_URL.endsWith('/')
  ? import.meta.env.BASE_URL
  : `${import.meta.env.BASE_URL}/`;

export function asset(path: string): string {
  return BASE + (path.startsWith('/') ? path.slice(1) : path);
}
