  /** Сколько гость топчется у входа перед уходом из-за грязи. */
  TRASH_LEAVE_DELAY_MS: 2_000,

  // ── Уборщик (CleanerEmployee.as:15-19)
  /** Время уборки одной мусорки — по энергии сотрудника. */
