import { engine } from '@rv/shared';
import { useEffect, useMemo, useState } from 'react';
import { asset } from '../asset-url';
import { hasSprite, itemIconUrl, loadItemLibrary } from '../game/item-textures';
import type { SceneSnapshot } from '../game/scene';
import { haptic } from '../telegram';
import { CoinCounter, IconButton } from './flash-ui';

const {
  CATALOG_SECTIONS,
  CATALOG_SECTION_LABELS,
  SHOP_TABS,
  SHOP_TAB_LABELS,
  filterCatalog,
  itemSellPrice,
  purchaseBlock,
} = engine;

type Props = {
  coins: number;
  level: number;
  /** Что уже стоит в зале — для вкладки «В зале». */
  placed: SceneSnapshot['placed'];
  sellMode: boolean;
  onToggleSellMode: (on: boolean) => void;
  onBuy: (contentId: number) => void;
  onSell: (itemId: string) => void;
  onClearRoom: () => void;
  onClose: () => void;
  notice: string | null;
};

const BLOCK_LABEL: Record<engine.PurchaseBlock, string> = {
  locked: 'по уровню',
  premium: 'премиум',
  'no-coins': 'дорого',
  'no-space': 'нет места',
};

/** Иконки разделов — те же кнопки, что были на панели ItemChooser оригинала. */
const SECTION_ICON: Record<engine.CatalogSection, string> = {
  shop: 'btn-shop-items',
  new: 'btn-new-items',
  cash: 'btn-cash-items',
  placed: 'btn-inventory',
};

/**
 * Иконки папок каталога — кнопки `ItemChoosePanel` оригинала.
 *
 * Там групп было 12 (Chair, Table, Door, Window, Fireplace, FloorTile,
 * Wallpaper, Functional, Wall, Award…), у нас шесть укрупнённых: на узком
 * экране двенадцать вкладок в один ряд не помещаются. Каждой достаётся иконка
 * самой характерной для неё группы оригинала.
 */
const FOLDER_ICON: Record<engine.ShopTab, string> = {
  furniture: 'tab-chair',
  kitchen: 'tab-kitchen',
  functional: 'tab-functional',
  decor: 'tab-decor',
  wall: 'tab-wallpaper',
  floor: 'tab-floor',
};

/**
 * Выбор предметов — порт `ui/ItemChooser.as`.
 *
 * Оригинал: ряд вкладок (New / Shop / Inventory / Cash), под ними папки-группы,
 * справа переключатель сортировки, ниже сетка предметов с ценой, а у выбранного
 * — кнопки Flip / Sell. Инвентаря у нас нет (купленное сразу встаёт в зал),
 * поэтому его место заняла вкладка «В зале» со списком расставленного.
 */
export function ItemChooser({
  coins,
  level,
  placed,
  sellMode,
  onToggleSellMode,
  onBuy,
  onSell,
  onClearRoom,
  onClose,
  notice,
}: Props): React.ReactElement {
  const [section, setSection] = useState<engine.CatalogSection>('shop');
  const [folder, setFolder] = useState<engine.ShopTab>('furniture');
  const [sort, setSort] = useState<engine.ShopSort>('price');
  const [libReady, setLibReady] = useState(false);

  useEffect(() => {
    void loadItemLibrary().then(() => setLibReady(true));
  }, []);

  const entries = useMemo(() => {
    if (!libReady || section === 'placed') return [];
    return filterCatalog({
      tab: folder,
      section,
      sort,
      include: (e) => hasSprite(e.def.className),
    });
  }, [folder, section, sort, libReady]);

  /** Сколько предметов в каждой папке — пустые гасим, как в оригинале. */
  const folderCounts = useMemo(() => {
    const counts = {} as Record<engine.ShopTab, number>;
    for (const tab of SHOP_TABS) {
      counts[tab] =
        section === 'placed'
          ? placed.filter((p) => p.tab === tab).length
          : libReady
            ? filterCatalog({ tab, section, include: (e) => hasSprite(e.def.className) }).length
            : 0;
    }
    return counts;
  }, [section, placed, libReady]);

  const placedInFolder = useMemo(() => placed.filter((p) => p.tab === folder), [placed, folder]);

  return (
    <div className="absolute bottom-0 left-0 right-0 pointer-events-auto">
      <div className="mx-auto max-w-md rounded-t-2xl bg-[#141a22]/95 backdrop-blur-md border-t border-white/10 flex flex-col max-h-[62dvh]">
        {/* ── Вкладки разделов + монеты + закрытие ── */}
        <div className="flex items-center gap-1 p-2 pb-1 shrink-0">
          {CATALOG_SECTIONS.map((sec) => (
            <IconButton
              key={sec}
              icon={SECTION_ICON[sec]}
              label={CATALOG_SECTION_LABELS[sec]}
              active={section === sec}
              onClick={() => {
                setSection(sec);
                if (sec === 'placed') onToggleSellMode(false);
              }}
            />
          ))}
          <div className="ml-auto flex items-center gap-1.5">
            <CoinCounter coins={coins} />
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg px-2.5 py-1.5 text-xs border border-white/15 hover:bg-white/5"
            >
              ✕
            </button>
          </div>
        </div>

        {/*
         * ── Папки каталога + сортировка ──
         * Прокручивается только лента папок: сортировка вынесена в соседний
         * блок, иначе на узком экране она уезжает вместе с лентой и до неё не
         * дотянуться.
         */}
        <div className="flex items-stretch gap-1 px-2 pb-1 shrink-0">
          <div className="flex items-center gap-1 min-w-0 flex-1 overflow-x-auto">
            {SHOP_TABS.map((tab) => (
              <button
                key={tab}
                type="button"
                disabled={folderCounts[tab] === 0}
                title={SHOP_TAB_LABELS[tab]}
                onClick={() => {
                  haptic('light');
                  setFolder(tab);
                }}
                className={`shrink-0 flex items-center gap-1 rounded-lg pl-1 pr-2 py-1.5 text-[11px] font-semibold border transition ${
                  folderCounts[tab] === 0
                    ? 'border-white/10 opacity-30 cursor-not-allowed'
                    : folder === tab
                      ? 'bg-white/15 border-white/50'
                      : 'border-white/15 hover:bg-white/5 text-white/70'
                }`}
              >
                <img
                  src={asset(`ui/${FOLDER_ICON[tab]}.png`)}
                  alt=""
                  draggable={false}
                  className="w-5 h-5 object-contain"
                />
                {SHOP_TAB_LABELS[tab]}
              </button>
            ))}
          </div>
          {section !== 'placed' && (
            <button
              type="button"
              title={sort === 'price' ? 'Сортировка: по цене' : 'Сортировка: по алфавиту'}
              onClick={() => {
                haptic('light');
                setSort((v) => (v === 'price' ? 'alpha' : 'price'));
              }}
              className="shrink-0 w-10 grid place-items-center rounded-lg border border-white/15 hover:bg-white/5"
            >
              {/*
               * `ButtonSortPrice` — двухкадровая кнопка оригинала: золотая, пока
               * сортируем по цене, погашенная — когда нет. Пары к ней
               * (`ButtonSortAlphabetically`) в этой сборке SWF нет: символ пустой,
               * да и сам переключатель нигде в AS3 не подключён — сортировка
               * там всегда шла по `compareShopItems`. Переключатель наш.
               */}
              <img
                src={asset(`ui/${sort === 'price' ? 'btn-sort-price' : 'btn-sort-price-off'}.png`)}
                alt=""
                draggable={false}
                className="w-8 h-5 object-contain"
              />
            </button>
          )}
        </div>

        {/* ── Содержимое ── */}
        <div className="overflow-y-auto min-h-0 px-2 pb-2 grid grid-cols-3 gap-1.5">
          {section === 'placed'
            ? placedInFolder.map((item) => <PlacedCard key={item.id} item={item} onSell={onSell} />)
            : entries.map((entry) => (
                <ShopCard
                  key={entry.def.id}
                  entry={entry}
                  level={level}
                  coins={coins}
                  onBuy={onBuy}
                />
              ))}

          {section === 'placed' && placedInFolder.length === 0 && (
            <div className="col-span-3 py-6 text-center text-xs opacity-50">
              В этой категории пока ничего не стоит
            </div>
          )}
          {section !== 'placed' && entries.length === 0 && (
            <div className="col-span-3 py-6 text-center text-xs opacity-50">
              {libReady ? 'Здесь пока пусто' : 'Загружаем каталог…'}
            </div>
          )}
        </div>

        {/* ── Нижний ряд действий: как кнопки Flip / Delete / Clear Room ── */}
        <div className="flex items-center gap-1 px-2 pb-2 pt-1 shrink-0 border-t border-white/10">
          <IconButton
            icon="btn-flip"
            label="Поворот: тапните предмет в зале"
            disabled
            onClick={() => {}}
          />
          <IconButton
            icon="btn-delete"
            label={sellMode ? 'Выйти из режима продажи' : 'Продать: тапните предмет в зале'}
            active={sellMode}
            onClick={() => onToggleSellMode(!sellMode)}
          />
          <IconButton icon="btn-clear-room" label="Убрать всех гостей" onClick={onClearRoom} />
          <div className="ml-2 text-[11px] leading-snug opacity-60">
            {notice ??
              (sellMode
                ? 'Тапните предмет в зале — продадим за треть цены'
                : 'Тапните предмет в зале, чтобы повернуть; тащите, чтобы двигать')}
          </div>
        </div>
      </div>
    </div>
  );
}

function ShopCard({
  entry,
  level,
  coins,
  onBuy,
}: {
  entry: engine.ShopEntry;
  level: number;
  coins: number;
  onBuy: (contentId: number) => void;
}): React.ReactElement {
  const block = purchaseBlock(entry, level, coins);
  const icon = itemIconUrl(entry.def.className);
  return (
    <button
      type="button"
      disabled={block !== null}
      onClick={() => {
        haptic('light');
        onBuy(entry.def.id);
      }}
      title={entry.def.name}
      className={`relative rounded-xl border p-1.5 flex flex-col items-center gap-1 transition ${
        block
          ? 'border-white/10 opacity-40 cursor-not-allowed'
          : 'border-white/15 hover:bg-white/5 active:bg-white/10'
      }`}
    >
      {entry.isNew && (
        <span className="absolute top-0.5 left-0.5 px-1 rounded bg-amber-400 text-black text-[8px] font-bold leading-tight">
          NEW
        </span>
      )}
      <div className="h-11 w-full grid place-items-center">
        {/*
          Иконки грузятся сразу, без loading="lazy": при отложенной загрузке
          быстрый скролл каталога оставлял за собой пустые карточки, которые
          дорисовывались уже после остановки. Экономия того не стоит — самая
          тяжёлая вкладка («Декор», 190 предметов) весит около 760 КБ
          четырёхкилобайтными PNG.
        */}
        {icon && (
          <img src={icon} alt={entry.def.name} className="max-h-11 max-w-full object-contain" />
        )}
      </div>
      <div className="text-[10px] leading-tight text-center text-white/70 line-clamp-2 h-6 overflow-hidden">
        {entry.def.name}
      </div>
      <div className="flex items-center gap-1 text-[11px] font-semibold">
        {block === 'locked' ? (
          <span className="text-white/50">ур. {entry.unlockLevel}</span>
        ) : entry.cash !== null && entry.price === null ? (
          <>
            <img src={asset('ui/cash.png')} alt="" className="w-3.5 h-3.5" />
            <span className="text-emerald-200">{entry.cash}</span>
          </>
        ) : block ? (
          <span className="text-white/50">{BLOCK_LABEL[block]}</span>
        ) : (
          <>
            <img src={asset('ui/coin.png')} alt="" className="w-3.5 h-3.5" />
            <span className="text-amber-200">{entry.price}</span>
          </>
        )}
      </div>
    </button>
  );
}

function PlacedCard({
  item,
  onSell,
}: {
  item: SceneSnapshot['placed'][number];
  onSell: (itemId: string) => void;
}): React.ReactElement {
  const icon = itemIconUrl(item.className);
  return (
    <div className="rounded-xl border border-white/15 p-1.5 flex flex-col items-center gap-1">
      <div className="h-11 w-full grid place-items-center">
        {icon && <img src={icon} alt={item.name} className="max-h-11 object-contain" />}
      </div>
      <div className="text-[10px] leading-tight text-center text-white/70 line-clamp-2 h-6 overflow-hidden">
        {item.name}
      </div>
      <button
        type="button"
        onClick={() => {
          haptic('medium');
          onSell(item.id);
        }}
        className="w-full rounded-lg py-0.5 text-[11px] font-semibold border border-rose-400/40 text-rose-200 hover:bg-rose-400/10"
      >
        +{itemSellPrice(item.def)}
      </button>
    </div>
  );
}
