import { useSyncExternalStore } from 'react';

export type TelegramUser = {
  id: number;
  first_name?: string;
  last_name?: string;
  username?: string;
  language_code?: string;
  is_premium?: boolean;
  allows_write_to_pm?: boolean;
};

export type TelegramState = {
  ready: boolean;
  isInsideTelegram: boolean;
  initData: string;
  user: TelegramUser | null;
  colorScheme: 'light' | 'dark';
  viewportHeight: number;
  /**
   * Безопасные отступы клиента (Bot API 8.0): вырез сверху, системная полоса
   * снизу. Вне Telegram и на старых клиентах — нули, тогда работает
   * env(safe-area-inset-*) из CSS.
   */
  safeArea: { top: number; bottom: number; left: number; right: number };
};

const initialState: TelegramState = {
  ready: false,
  isInsideTelegram: false,
  initData: '',
  user: null,
  colorScheme: 'dark',
  viewportHeight: typeof window === 'undefined' ? 0 : window.innerHeight,
  safeArea: { top: 0, bottom: 0, left: 0, right: 0 },
};

/** Фон мини-аппа — тот же, что у сцены, чтобы не мигало при развороте. */
const APP_BACKGROUND = '#0f141b';

let state: TelegramState = initialState;
const listeners = new Set<() => void>();

function setState(next: Partial<TelegramState>): void {
  state = { ...state, ...next };
  for (const l of listeners) l();
}

/**
 * Инициализация Telegram WebApp SDK. Вызывать ровно один раз при старте.
 * Если приложение запущено вне Telegram (например, в браузере для разработки) —
 * флаг isInsideTelegram = false, остальные поля остаются дефолтными.
 */
export function initTelegram(): void {
  const tg = window.Telegram?.WebApp;
  if (!tg) {
    setState({ ready: true, isInsideTelegram: false });
    return;
  }

  tg.ready();
  tg.expand();

  // Шапка и подложка — под цвет сцены. Без этого при развороте видно светлую
  // полосу клиента, а при оверскролле — белый фон под игрой.
  if (tg.isVersionAtLeast?.('6.1')) {
    try {
      tg.setHeaderColor(APP_BACKGROUND);
      tg.setBackgroundColor(APP_BACKGROUND);
    } catch {
      // На части клиентов метод есть, но цвет задавать не даёт — не критично.
    }
  }

  // Свайп вниз по умолчанию закрывает мини-апп. В игре, где мебель таскают
  // пальцем, это означает случайный выход посреди перестановки (Bot API 7.7).
  if (tg.isVersionAtLeast?.('7.7')) tg.disableVerticalSwipes?.();

  setState({
    ready: true,
    isInsideTelegram: true,
    initData: tg.initData,
    user: tg.initDataUnsafe?.user ?? null,
    colorScheme: tg.colorScheme,
    viewportHeight: tg.viewportHeight,
    safeArea: readSafeArea(tg),
  });
  applySafeArea(readSafeArea(tg));

  // Реакция на смену темы и размер вьюпорта (например, клавиатура поднимается).
  tg.onEvent('themeChanged', () => {
    setState({ colorScheme: tg.colorScheme });
  });
  tg.onEvent('viewportChanged', () => {
    setState({ viewportHeight: tg.viewportHeight });
  });
  const onSafeArea = (): void => {
    const area = readSafeArea(tg);
    setState({ safeArea: area });
    applySafeArea(area);
  };
  tg.onEvent('safeAreaChanged', onSafeArea);
  tg.onEvent('contentSafeAreaChanged', onSafeArea);
}

/** Тип WebApp берём из глобального объявления — отдельного экспорта у него нет. */
type WebApp = NonNullable<Window['Telegram']>['WebApp'];

/** Сумма обоих отступов: вырез экрана + панель клиента над содержимым. */
function readSafeArea(tg: WebApp): TelegramState['safeArea'] {
  const a = tg.safeAreaInset ?? { top: 0, bottom: 0, left: 0, right: 0 };
  const b = tg.contentSafeAreaInset ?? { top: 0, bottom: 0, left: 0, right: 0 };
  return {
    top: a.top + b.top,
    bottom: a.bottom + b.bottom,
    left: a.left + b.left,
    right: a.right + b.right,
  };
}

/**
 * Отдаём отступы в CSS-переменные. На вебе `env(safe-area-inset-*)` уже знает
 * про вырезы, а внутри Telegram — нет: там их сообщает только клиент.
 */
function applySafeArea(area: TelegramState['safeArea']): void {
  const root = document.documentElement.style;
  root.setProperty('--tg-safe-top', `${area.top}px`);
  root.setProperty('--tg-safe-bottom', `${area.bottom}px`);
  root.setProperty('--tg-safe-left', `${area.left}px`);
  root.setProperty('--tg-safe-right', `${area.right}px`);
}

/**
 * Состояние вне React: сцене PixiJS нужны безопасные отступы, а хуки ей
 * недоступны — она живёт вне дерева компонентов.
 */
export function telegramState(): TelegramState {
  return state;
}

export function useTelegram(): TelegramState {
  return useSyncExternalStore(
    (cb) => {
      listeners.add(cb);
      return () => {
        listeners.delete(cb);
      };
    },
    () => state,
    () => state,
  );
}

/** Хаптический отклик при тапе (только в Telegram ≥6.1). */
export function haptic(style: 'light' | 'medium' | 'heavy' | 'rigid' | 'soft' = 'light'): void {
  const wa = window.Telegram?.WebApp;
  // HapticFeedback доступен с Bot API 6.1. На старых клиентах вызов кидает warning —
  // глушим через проверку версии.
  if (!wa?.isVersionAtLeast?.('6.1')) return;
  try {
    wa.HapticFeedback?.impactOccurred(style);
  } catch {
    // не роняем UX из-за хаптики
  }
}

/** Закрыть Mini App. */
export function closeApp(): void {
  window.Telegram?.WebApp?.close();
}
