import { engine } from '@rv/shared';
import { useState, useSyncExternalStore } from 'react';
import { audio } from '../game/audio';
import type { SceneSnapshot } from '../game/scene';
import { haptic, useTelegram } from '../telegram';
import { ButtonRail, CoinCounter, IconButton, LevelBar, PopularityMeter } from './flash-ui';

type Props = {
  snapshot: SceneSnapshot | null;
  /** Магазин или другая панель заняла низ экрана — прячем ряд кнопок. */
  hideRail: boolean;
  shopOpen: boolean;
  staffOpen: boolean;
  onReset: () => void;
  onToggleDesign: () => void;
  onToggleShop: () => void;
  onToggleStaff: () => void;
  onShowAvatar: () => void;
  onShowStreet: () => void;
};

const EMOTION_LABEL: Record<engine.CustomerEmotion, string> = {
  [-1]: 'спокоен',
  [0]: 'нет места',
  [1]: 'грязно!',
  [2]: 'долго ждёт',
  [3]: 'без декора',
  [4]: 'нет стола',
  [5]: 'грязный стол',
  [6]: 'нет туалета',
  [7]: 'долго ждёт напиток',
};

/**
 * HUD в раскладке оригинала: слева сверху шкала уровня, справа популярность и
 * монеты, внизу ряд иконочных кнопок (`RoomUi` из game_asset.swf).
 *
 * Отладочная статистика спрятана под кнопку-закладку — она полезна, но не должна
 * быть главным экраном игры.
 */
export function HUD({
  snapshot,
  hideRail,
  shopOpen,
  staffOpen,
  onReset,
  onToggleDesign,
  onToggleShop,
  onToggleStaff,
  onShowAvatar,
  onShowStreet,
}: Props): React.ReactElement {
  const tg = useTelegram();
  const [statsOpen, setStatsOpen] = useState(false);
  const designMode = snapshot?.designMode ?? false;
  const muted = useSyncExternalStore(
    (fn) => audio.subscribe(fn),
    () => audio.muted,
    () => false,
  );

  // Бейдж на кнопке штата: сколько людей ждут решения игрока — выдохлись или
  // сидят без должности. Отдыхающие в счёт не идут: с ними всё в порядке.
  const needsAttention = (snapshot?.roster ?? []).filter(
    (m) => m.exhausted || m.idleReason === 'needs-job' || m.idleReason === 'needs-stove',
  ).length;
  const trash = snapshot?.trash ?? 0;
  const broken = snapshot?.brokenFacilities ?? 0;
  const closed = snapshot?.restaurantClosed ?? false;

  return (
    <>
      {/* ── Верх: уровень слева, популярность и монеты справа ── */}
      <div className="absolute top-0 left-0 right-0 p-2 pad-top-safe flex items-start justify-between gap-2 pointer-events-none">
        <LevelBar
          level={snapshot?.level ?? 0}
          progress={snapshot?.levelProgress ?? 0}
          points={snapshot?.gourmetPoints ?? 0}
          toNext={snapshot?.pointsToNextLevel ?? null}
        />

        <div className="flex flex-col items-end gap-1.5 pointer-events-auto">
          <div className="flex items-center gap-3">
            <PopularityMeter demand={snapshot?.demand ?? 0} maxDemand={snapshot?.maxDemand ?? 0} />
            <CoinCounter coins={snapshot?.coins ?? 0} />
            <button
              type="button"
              onClick={() => {
                haptic('light');
                audio.toggleMuted();
              }}
              title={muted ? 'Включить звук' : 'Выключить звук'}
              className="rounded-full w-6 h-6 grid place-items-center border border-white/20 hover:bg-white/10 text-[11px]"
            >
              {muted ? '🔇' : '🔊'}
            </button>
          </div>
          <div className="text-[10px] font-mono opacity-40">
            {tg.isInsideTelegram ? `tg · ${tg.user?.first_name ?? 'anon'}` : 'web · dev'}
          </div>
        </div>
      </div>

      {closed && !hideRail && (
        <div className="absolute top-14 left-0 right-0 flex justify-center pointer-events-none">
          <div className="text-xs px-3 py-1.5 rounded-full bg-rose-500/20 text-rose-100 border border-rose-400/40">
            Зал закрыт — нужен повар и официант с силами
          </div>
        </div>
      )}
      {designMode && !hideRail && (
        <div className="absolute top-14 left-0 right-0 flex justify-center pointer-events-none">
          <div className="text-xs px-3 py-1.5 rounded-full bg-emerald-500/15 text-emerald-300 border border-emerald-500/30">
            Тащи — двигать, тапни — повернуть
          </div>
        </div>
      )}

      {/* ── Отладочная статистика (по закладке) ── */}
      {statsOpen && (
        <div className="absolute bottom-20 left-0 right-0 px-3 pointer-events-none">
          <div className="mx-auto max-w-md rounded-2xl bg-black/55 backdrop-blur-md p-3 grid grid-cols-2 gap-x-3 gap-y-0.5 font-mono text-[11px]">
            <Row
              label="популярность"
              value={snapshot ? `${snapshot.demand} / ${snapshot.maxDemand}` : '—'}
            />
            <Row
              label="гость раз в"
              value={snapshot ? `${snapshot.spawnEverySec.toFixed(1)}s` : '—'}
            />
            <Row
              label="места"
              value={snapshot ? `${snapshot.occupancy.busy} / ${snapshot.occupancy.total}` : '—'}
            />
            <Row label="в зале" value={snapshot ? String(snapshot.customerCount) : '—'} />
            <Row label="грязных тарелок" value={snapshot ? String(snapshot.dirtyPlates) : '—'} />
            <Row
              label="мусор"
              value={snapshot ? `${snapshot.trash} / ${engine.Balance.MAX_TRASH}` : '—'}
            />
            <Row
              label="сломано"
              value={snapshot ? `${snapshot.brokenFacilities} (туалетов ${snapshot.toilets})` : '—'}
            />
            <Row
              label="силы смены"
              value={snapshot ? `${Math.round(snapshot.staff.energy * 100)}%` : '—'}
            />
            <Row
              label="штат"
              value={
                snapshot
                  ? `${snapshot.staff.chefs}п · ${snapshot.staff.waiters}о · ${snapshot.staff.cleaners}у (${snapshot.staff.hired}/${snapshot.staff.max})`
                  : '—'
              }
            />
            <Row
              label="размер зала"
              value={snapshot ? `${snapshot.roomSize.width}×${snapshot.roomSize.height}` : '—'}
            />
            <Row
              label="зал"
              value={snapshot ? (snapshot.restaurantClosed ? 'закрыт' : 'работает') : '—'}
            />
            <Row label="предметов" value={snapshot ? String(snapshot.itemCount) : '—'} />
            <Row label="гость: state" value={snapshot?.stateName ?? '—'} />
            <Row
              label="гость: эмоция"
              value={snapshot?.emotion != null ? (EMOTION_LABEL[snapshot.emotion] ?? '?') : '—'}
            />
          </div>
        </div>
      )}

      {/* ── Низ: ряд иконочных кнопок как в оригинале ── */}
      {!hideRail && (
        <div className="absolute bottom-0 left-0 right-0 p-2 pad-bottom-safe pointer-events-auto">
          <ButtonRail>
            <IconButton
              icon="btn-redecorate"
              label={designMode ? 'Выйти из режима перестройки' : 'Перестроить зал'}
              active={designMode}
              onClick={onToggleDesign}
            />
            <IconButton
              icon="btn-shop-items"
              label="Магазин"
              active={shopOpen}
              disabled={!designMode}
              onClick={onToggleShop}
            />
            <IconButton
              icon="btn-hire"
              label="Сотрудники"
              active={staffOpen}
              badge={needsAttention > 0 ? needsAttention : undefined}
              onClick={onToggleStaff}
            />
            <IconButton icon="btn-menu" label="Меню (скоро)" disabled onClick={() => {}} />
            <IconButton icon="btn-awards" label="Достижения (скоро)" disabled onClick={() => {}} />
            <IconButton
              icon="btn-ingredients"
              label="Ингредиенты (скоро)"
              disabled
              onClick={() => {}}
            />
            <IconButton icon="btn-avatar" label="3D-аватар" onClick={onShowAvatar} />
            <IconButton icon="btn-outside" label="На улицу" onClick={onShowStreet} />
            <IconButton
              icon="btn-bookmark"
              label="Статистика"
              active={statsOpen}
              badge={trash + broken > 0 ? trash + broken : undefined}
              onClick={() => setStatsOpen((v) => !v)}
            />
            <IconButton icon="btn-clear-room" label="Очистить зал" onClick={onReset} />
          </ButtonRail>
        </div>
      )}
    </>
  );
}

function Row({ label, value }: { label: string; value: string }): React.ReactElement {
  return (
    <>
      <div className="opacity-50">{label}</div>
      <div className="text-right truncate">{value}</div>
    </>
  );
}
