/**
 * Мусор на полу: спрайты из indoor_asset.swf + тап для уборки.
 *
 * Оригинал показывал под мусоркой белый силуэт `<Class>Outline` при наведении
 * мыши (WorldRestaurantPlay.tick :2593) и убирал мусор по MOUSE_DOWN. Здесь то
 * же самое: halo под спрайтом на hover, тап отдаёт id в симуляцию.
 *
 * Мусор живёт в сортируемом слое — его перекрывают проходящие мимо персонажи.
 */

import type { engine } from '@rv/shared';
import {
  Assets,
  Container,
  type FederatedPointerEvent,
  Rectangle,
  Sprite,
  type Texture,
} from 'pixi.js';
import { asset } from '../asset-url';
import { DEPTH_BIAS, TILE_H, isoDepth, tileToScreen } from './iso';

/**
 * Минимальный размер зоны тапа. Мусорка — 50 px, но это Mini App: палец должен
 * попадать без прицеливания.
 */
const MIN_HIT_SIZE = 44;

/** Имена файлов совпадают с kind в нижнем регистре. */
const TRASH_FILES = ['bananapeel', 'pizzaslice', 'sodacan', 'chickenleg', 'applecore'] as const;

export type TrashTextures = {
  item: Record<string, Texture>;
  outline: Record<string, Texture>;
};

/** Загрузить спрайты мусора и их белые силуэты для подсветки. */
export async function loadTrashTextures(): Promise<TrashTextures> {
  const urls: string[] = [];
  for (const name of TRASH_FILES) {
    urls.push(asset(`trash/${name}.png`), asset(`trash/${name}_outline.png`));
  }
  const assets = (await Assets.load(urls)) as Record<string, Texture>;
  const item: Record<string, Texture> = {};
  const outline: Record<string, Texture> = {};
  for (const name of TRASH_FILES) {
    const tex = assets[asset(`trash/${name}.png`)];
    const halo = assets[asset(`trash/${name}_outline.png`)];
    if (tex) item[name] = tex;
    if (halo) outline[name] = halo;
  }
  return { item, outline };
}

type TrashNode = {
  container: Container;
  /** Интерактивный спрайт — на нём висят hit-area и обработчики. */
  sprite: Sprite;
  halo: Sprite;
};

export class TrashLayer {
  private readonly nodes = new Map<string, TrashNode>();

  constructor(
    private readonly layer: Container,
    private readonly tex: TrashTextures,
    /** Тап по мусорке — сцена передаст id в симуляцию. */
    private readonly onTap: (trashId: string) => void,
  ) {}

  /** Привести спрайты в соответствие со списком мусора из симуляции. */
  sync(items: readonly engine.TrashItem[]): void {
    const alive = new Set(items.map((t) => t.id));
    for (const [id, node] of this.nodes) {
      if (alive.has(id)) continue;
      this.layer.removeChild(node.container);
      node.container.destroy({ children: true });
      this.nodes.delete(id);
    }
    for (const item of items) {
      if (this.nodes.has(item.id)) continue;
      this.nodes.set(item.id, this.createNode(item));
    }
  }

  private createNode(item: engine.TrashItem): TrashNode {
    const key = item.kind.toLowerCase();
    const container = new Container();

    // Белый силуэт под спрайтом — подсветка при наведении (как в оригинале).
    const halo = new Sprite(this.tex.outline[key]);
    halo.anchor.set(0.5, 0.5);
    halo.scale.set(1.15);
    halo.alpha = 0.75;
    halo.visible = false;
    container.addChild(halo);

    const sprite = new Sprite(this.tex.item[key]);
    sprite.anchor.set(0.5, 0.5);
    container.addChild(sprite);

    const screen = tileToScreen(item.tileX, item.tileY);
    container.position.set(screen.x, screen.y + TILE_H / 2);
    container.zIndex = isoDepth(item.tileX, item.tileY) + DEPTH_BIAS.trash;

    // Интерактивен САМ СПРАЙТ, а не контейнер-обёртка: у контейнера в PixiJS нет
    // геометрии, и hit-test до него не доходит (та же схема, что у мебели в
    // ItemLayer). hitArea расширяем до MIN_HIT_SIZE — это Mini App, палец должен
    // попадать без прицеливания.
    const hitW = Math.max(MIN_HIT_SIZE, sprite.width);
    const hitH = Math.max(MIN_HIT_SIZE, sprite.height);
    sprite.hitArea = new Rectangle(-hitW / 2, -hitH / 2, hitW, hitH);
    sprite.eventMode = 'static';
    sprite.cursor = 'pointer';
    sprite.on('pointerover', () => {
      halo.visible = true;
    });
    sprite.on('pointerout', () => {
      halo.visible = false;
    });
    sprite.on('pointertap', (e: FederatedPointerEvent) => {
      e.stopPropagation();
      this.onTap(item.id);
    });

    this.layer.addChild(container);
    return { container, sprite, halo };
  }

  /** Включить/выключить кликабельность (в дизайн-режиме мусор не трогаем). */
  setInteractive(on: boolean): void {
    for (const node of this.nodes.values()) {
      node.sprite.eventMode = on ? 'static' : 'none';
      node.sprite.cursor = on ? 'pointer' : 'default';
      if (!on) node.halo.visible = false;
    }
  }

  clear(): void {
    for (const node of this.nodes.values()) {
      this.layer.removeChild(node.container);
      node.container.destroy({ children: true });
    }
    this.nodes.clear();
  }
}
