/**
 * Оффскрин-рендерер аватара ИГРОКА по сохранённой конфигурации кастомизации.
 *
 * В отличие от батча в зале (фиксированный наряд + только цвета палитры), здесь
 * применяется полная AvatarConfig (причёска/шляпа/тело + цвета). Рендерит во
 * фронт-проекции (улица смотрит на фасады прямо), отдаёт <canvas> для PixiJS.
 */

import * as THREE from 'three';
import { AVATAR_ANIMATIONS, AVATAR_FPS } from './animations';
import type { AvatarConfig } from './avatar-config';
import {
  type AvatarInstance,
  applyAvatarConfig,
  cloneAvatar,
  loadAvatarModel,
} from './avatar-model';

export class PlayerAvatarRenderer {
  readonly canvas: HTMLCanvasElement;
  ready = false;

  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene: THREE.Scene;
  private readonly camera: THREE.PerspectiveCamera;
  private readonly facingGroup: THREE.Group;
  private instance: AvatarInstance | null = null;
  private fullClip: THREE.AnimationClip | null = null;
  private action: THREE.AnimationAction | null = null;
  private currentAnim = '';
  private disposed = false;

  constructor(width = 160, height = 320, cfg?: AvatarConfig) {
    this.canvas = document.createElement('canvas');
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: true,
      premultipliedAlpha: false,
    });
    this.renderer.setSize(width, height, false);
    this.renderer.setClearColor(0x000000, 0);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(28, width / height, 1, 100000);
    this.scene.add(new THREE.AmbientLight(0xffffff, 1.0));
    const dir = new THREE.DirectionalLight(0xffffff, 1.0);
    dir.position.set(2, 8, 6);
    this.scene.add(dir);

    this.facingGroup = new THREE.Group();
    this.scene.add(this.facingGroup);

    void this.load(cfg);
  }

  private async load(cfg?: AvatarConfig): Promise<void> {
    let src: Awaited<ReturnType<typeof loadAvatarModel>>;
    try {
      src = await loadAvatarModel();
    } catch (err) {
      console.error('PlayerAvatarRenderer: model load failed', err);
      return;
    }
    if (this.disposed) return;

    const instance = cloneAvatar(src);
    if (cfg) applyAvatarConfig(instance.root, cfg);
    this.instance = instance;
    this.facingGroup.add(instance.root);
    this.fullClip = instance.clips[0] ?? null;
    this.frameCamera(instance.root);
    this.play('idle');
    this.ready = true;
  }

  /** Фронт-камера: смотрит на аватара прямо, лёгкий наклон сверху. */
  private frameCamera(root: THREE.Object3D): void {
    root.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(root);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    const h = size.y || 200;
    this.instance?.root.position.set(-center.x, 0, -center.z);
    const dist = h * 1.6;
    const elev = THREE.MathUtils.degToRad(8);
    this.camera.position.set(0, center.y + Math.sin(elev) * dist, Math.cos(elev) * dist);
    this.camera.lookAt(0, center.y, 0);
    this.camera.updateProjectionMatrix();
  }

  setConfig(cfg: AvatarConfig): void {
    if (this.instance) applyAvatarConfig(this.instance.root, cfg);
  }

  setFacing(angleRad: number): void {
    this.facingGroup.rotation.y = angleRad;
  }

  play(key: string): void {
    if (this.currentAnim === key) return;
    const mixer = this.instance?.mixer;
    const full = this.fullClip;
    if (!mixer || !full) return;
    const def = AVATAR_ANIMATIONS[key];
    if (!def) return;
    const clip = THREE.AnimationUtils.subclip(full, def.name, def.start, def.end + 1, AVATAR_FPS);
    const next = mixer.clipAction(clip);
    next.reset();
    next.setLoop(THREE.LoopRepeat, Number.POSITIVE_INFINITY);
    next.timeScale = 1 / def.delay;
    next.fadeIn(0.15);
    next.play();
    if (this.action && this.action !== next) this.action.fadeOut(0.15);
    this.action = next;
    this.currentAnim = key;
  }

  update(dtSec: number): void {
    if (this.disposed || !this.ready) return;
    this.instance?.mixer.update(dtSec);
    this.renderer.render(this.scene, this.camera);
  }

  dispose(): void {
    this.disposed = true;
    this.renderer.dispose();
  }
}
