/**
 * Повар (порт ChefActor.as, упрощённый).
 *
 * Стоит на клетке перед своей плитой, берёт заказ из очереди, готовит
 * cookDurationMs(энергия, качество плиты) и кладёт блюдо в раздачу.
 * Ходьба между кухнями (в оригинале повар мог обслуживать несколько плит)
 * пока не реализована — один повар закреплён за одной плитой.
 */

import type { Customer } from '../../customer/Customer';
import { Balance, cookDurationMs } from '../balance';
import { type Employee, Job } from '../employees';
import { energyOf } from '../staff';
import type { PlacedItem, Rotation } from '../types';
import { WorldRestaurant } from '../world-restaurant';
import { PathMover } from './mover';

export type ChefState = 'idle' | 'cooking';

export class ChefActor {
  readonly mover: PathMover;
  /** Плита, за которой закреплён повар. */
  readonly stove: PlacedItem;
  /** Куда «смотрит» повар — на плиту. */
  readonly facing: Rotation;

  state: ChefState = 'idle';
  cookTimer = 0;
  customer: Customer | null = null;

  /**
   * Кто именно на этой должности. Актёр — лишь «тело» сотрудника: запас сил и
   * состояние отдыха живут в Employee и переживают перестановку мебели.
   */
  readonly employee: Employee;

  /** id сотрудника — он же ключ актёра для рендера и сохранений. */
  get id(): string {
    return this.employee.id;
  }

  /** Запас сил, мс (GameUserEmployee.workTime). */
  get workTime(): number {
    return this.employee.workTime;
  }

  set workTime(value: number) {
    this.employee.workTime = Math.max(0, Math.min(Balance.MAX_WORK_TIME_MS, value));
  }

  /**
   * Не работает: либо отправлен на отдых, либо свалился без сил.
   * В оригинале выдохшийся сотрудник вставал в ANIMATION_DEAD и сам на смену
   * не возвращался — нужно было либо покормить, либо перевести в JOB_REST.
   */
  get resting(): boolean {
    return this.employee.job === Job.Rest || this.employee.workTime <= 0;
  }

  /** Доля сил 0..1. */
  get energy(): number {
    return energyOf(this.workTime);
  }

  constructor(employee: Employee, stove: PlacedItem) {
    this.employee = employee;
    this.stove = stove;
    const stand = WorldRestaurant.getFacingTile(stove.tileX, stove.tileY, stove.rotation);
    this.mover = new PathMover(stand.x, stand.y);
    // Лицом к плите — направление, противоположное её повороту.
    this.facing = ((stove.rotation + 180) % 360) as Rotation;
  }

  get busy(): boolean {
    return this.state !== 'idle';
  }

  /** Прогресс готовки 0..1 (для индикатора и эффектов плиты). */
  get cookProgress(): number {
    if (this.state !== 'cooking') return 0;
    const total = this.currentCookTime || 1;
    return Math.max(0, Math.min(1, 1 - this.cookTimer / total));
  }

  private currentCookTime = 0;

  /** Взять заказ в работу. */
  cook(customer: Customer): void {
    this.customer = customer;
    this.currentCookTime = cookDurationMs(this.energy, this.stoveOperatePercent());
    this.cookTimer = this.currentCookTime;
    this.state = 'cooking';
    customer.waitForFood();
  }

  /**
   * Качество плиты — operateTimePercentage из restaurant.xml: у дорогих плит
   * оно ниже 100, и блюдо готовится быстрее (Stove11 — 90%, Stove13 — 95%).
   */
  private stoveOperatePercent(): number {
    return this.stove.definition.operateTimePercentage ?? 100;
  }

  /**
   * Тик. Возвращает гостя, чьё блюдо только что приготовлено (его надо
   * положить в раздачу), либо null.
   */
  tick(dtMs: number): Customer | null {
    this.mover.advance(dtMs);
    if (this.state !== 'cooking') return null;
    this.cookTimer -= dtMs;
    if (this.cookTimer > 0) return null;
    const done = this.customer;
    this.customer = null;
    this.state = 'idle';
    this.cookTimer = 0;
    this.currentCookTime = 0;
    return done;
  }

  reset(): void {
    const stand = WorldRestaurant.getFacingTile(
      this.stove.tileX,
      this.stove.tileY,
      this.stove.rotation,
    );
    this.mover.teleport(stand.x, stand.y);
    this.state = 'idle';
    this.cookTimer = 0;
    this.currentCookTime = 0;
    this.customer = null;
  }
}
