/**
 * Заставка на время загрузки.
 *
 * Живёт в `index.html`, чтобы показаться до того, как приедет бандл: на
 * мобильном интернете three.js, pixi и модель аватара грузятся секундами, и
 * без неё первые мгновения виден пустой экран.
 *
 * Снимает её сцена по первому отрисованному кадру, а не React по монтированию:
 * к моменту mount канвас ещё пустой.
 */

let hidden = false;

export function hideBootSplash(): void {
  if (hidden) return;
  hidden = true;
  const boot = document.getElementById('boot');
  if (!boot) return;
  boot.classList.add('hidden');
  window.setTimeout(() => boot.remove(), 300);
}
