/**
 * Сообщения между клиентом и сервером (Colyseus room + HTTP auth).
 *
 * Дизайн вдохновлён `AuditChangeBatch` оригинала: клиент копит локальные
 * изменения как идемпотентные команды, шлёт батчем; сервер ревалидирует
 * и применяет атомарно. Это анти-чит + offline-tolerant UX.
 */
import { z } from 'zod';

// ──────────────────────────────────────────────────────────────────────────────
// HTTP: /auth/telegram
// ──────────────────────────────────────────────────────────────────────────────

export const AuthRequest = z.object({
  initData: z.string(),
});
export type AuthRequest = z.infer<typeof AuthRequest>;

export const AuthSuccess = z.object({
  token: z.string(),
  user: z.object({
    id: z.number().int(),
    telegramId: z.number().int(),
    firstName: z.string().nullable(),
    username: z.string().nullable(),
    createdAt: z.string(),
  }),
});
export type AuthSuccess = z.infer<typeof AuthSuccess>;

// ──────────────────────────────────────────────────────────────────────────────
// Colyseus: клиент → сервер
// ──────────────────────────────────────────────────────────────────────────────

export const TileCoord = z.object({ x: z.number().int(), y: z.number().int() });
export type TileCoord = z.infer<typeof TileCoord>;

export const PlaceItemCmd = z.object({
  kind: z.literal('place-item'),
  ownedItemId: z.string(),
  position: TileCoord,
  rotation: z.union([z.literal(0), z.literal(90), z.literal(180), z.literal(270)]),
});

export const MoveItemCmd = z.object({
  kind: z.literal('move-item'),
  placedItemId: z.string(),
  position: TileCoord,
  rotation: z.union([z.literal(0), z.literal(90), z.literal(180), z.literal(270)]),
});

export const RemoveItemCmd = z.object({
  kind: z.literal('remove-item'),
  placedItemId: z.string(),
});

export const BuyItemCmd = z.object({
  kind: z.literal('buy-item'),
  /** Item id из контента: 3xxxxxx / 2xxxxxx / 1xxxxxx / 6xxxxxx и т.д. */
  contentId: z.number().int(),
  payWith: z.enum(['coins', 'cash']),
});

export const PlantSeedCmd = z.object({
  kind: z.literal('plant-seed'),
  plotId: z.string(),
  ingredientId: z.number().int(),
});

export const HarvestCmd = z.object({
  kind: z.literal('harvest'),
  plotId: z.string(),
});

export const ServeOrderCmd = z.object({
  kind: z.literal('serve-order'),
  orderId: z.string(),
});

export const ClientCommand = z.discriminatedUnion('kind', [
  PlaceItemCmd,
  MoveItemCmd,
  RemoveItemCmd,
  BuyItemCmd,
  PlantSeedCmd,
  HarvestCmd,
  ServeOrderCmd,
]);
export type ClientCommand = z.infer<typeof ClientCommand>;

export const AuditBatch = z.object({
  /** Монотонный id батча на клиенте — для идемпотентности. */
  batchId: z.string(),
  /** Время на клиенте — для аналитики и анти-чит-сравнения. */
  clientTime: z.number().int(),
  commands: z.array(ClientCommand),
});
export type AuditBatch = z.infer<typeof AuditBatch>;

// ──────────────────────────────────────────────────────────────────────────────
// Colyseus: сервер → клиент
// ──────────────────────────────────────────────────────────────────────────────

export const AuditAckMessage = z.object({
  type: z.literal('audit-ack'),
  batchId: z.string(),
  /** Какие команды приняты, какие отклонены (idx → reason). */
  rejected: z.record(z.string(), z.string()),
});
export type AuditAckMessage = z.infer<typeof AuditAckMessage>;

export const ServerMessage = z.discriminatedUnion('type', [AuditAckMessage]);
export type ServerMessage = z.infer<typeof ServerMessage>;
