/**
 * Официант (порт Waitor.as, сокращённый).
 *
 * Два круга работы, в порядке приоритета:
 *   1) забрать готовое блюдо у плиты → донести гостю → вернуться;
 *   2) забрать грязную тарелку со стола → унести → вернуться.
 *
 * Второй круг — тот самый момент, когда ресторан получает деньги: в оригинале
 * clearEmptyPlate() вызывает onCustomerPay(). Поэтому уборка тарелок здесь не
 * косметика, а часть экономики.
 *
 * Официант забирает блюдо, СТОЯ на домашней клетке рядом с плитой, и никогда не
 * заходит на саму плиту.
 */

import type { Customer } from '../../customer/Customer';
import type { TileCoord } from '../../grid';
import { Balance } from '../balance';
import { type Employee, Job } from '../employees';
import type { EmptyPlate, OrderBoard } from '../orders';
import { energyOf } from '../staff';
import { PathMover } from './mover';

export type WaiterState =
  | 'idle'
  | 'toKitchen'
  | 'pickup'
  | 'toCustomer'
  | 'toPlate'
  | 'clearing'
  | 'back';

/** Что официанту нужно от мира — узкий срез RestaurantSim. */
export type WaiterWorld = {
  findPath(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    stopNextToDestination: boolean,
  ): TileCoord[] | null;
  readonly orders: OrderBoard;
  isActive(customer: Customer): boolean;
};

export type WaiterEvent =
  | { type: 'served'; customer: Customer }
  | { type: 'cleared'; plate: EmptyPlate };

export class WaiterActor {
  readonly mover: PathMover;
  /** Клетка ожидания — вплотную к плите. */
  readonly home: TileCoord;

  state: WaiterState = 'idle';

  /**
   * Кто именно на этой должности. Актёр — лишь «тело» сотрудника: запас сил и
   * состояние отдыха живут в Employee и переживают перестановку мебели.
   */
  readonly employee: Employee;

  /** id сотрудника — он же ключ актёра для рендера и сохранений. */
  get id(): string {
    return this.employee.id;
  }

  /** Запас сил, мс (GameUserEmployee.workTime). */
  get workTime(): number {
    return this.employee.workTime;
  }

  set workTime(value: number) {
    this.employee.workTime = Math.max(0, Math.min(Balance.MAX_WORK_TIME_MS, value));
  }

  /**
   * Не работает: либо отправлен на отдых, либо свалился без сил.
   * В оригинале выдохшийся сотрудник вставал в ANIMATION_DEAD и сам на смену
   * не возвращался — нужно было либо покормить, либо перевести в JOB_REST.
   */
  get resting(): boolean {
    return this.employee.job === Job.Rest || this.employee.workTime <= 0;
  }

  /** Доля сил 0..1. */
  get energy(): number {
    return energyOf(this.workTime);
  }
  /** Несёт ли поднос с блюдом (для анимации). */
  carrying = false;

  private timer = 0;
  private customer: Customer | null = null;
  private plate: EmptyPlate | null = null;

  constructor(employee: Employee, home: TileCoord) {
    this.employee = employee;
    this.home = { x: home.x, y: home.y };
    this.mover = new PathMover(home.x, home.y);
  }

  get busy(): boolean {
    return this.state !== 'idle';
  }

  tick(dtMs: number, world: WaiterWorld): WaiterEvent | null {
    this.mover.advance(dtMs);

    switch (this.state) {
      case 'idle':
        return this.tickIdle(world);

      case 'toKitchen':
        if (this.mover.arrived) {
          this.state = 'pickup';
          this.timer = Balance.WAITER_PICKUP_MS;
        }
        return null;

      case 'pickup':
        this.timer -= dtMs;
        if (this.timer > 0) return null;
        return this.startDelivery(world);

      case 'toCustomer':
        if (!this.mover.arrived) return null;
        return this.finishDelivery(world);

      case 'toPlate':
        if (!this.mover.arrived) return null;
        this.state = 'clearing';
        this.timer = Balance.WAITER_CLEAR_MS;
        return null;

      case 'clearing': {
        this.timer -= dtMs;
        if (this.timer > 0) return null;
        const plate = this.plate;
        this.plate = null;
        this.goHome(world);
        if (!plate) return null;
        world.orders.removePlate(plate);
        return { type: 'cleared', plate };
      }

      case 'back':
        if (this.mover.arrived) this.state = 'idle';
        return null;
    }
  }

  /** Свободен — ищем работу: сначала готовое блюдо, потом грязная тарелка. */
  private tickIdle(world: WaiterWorld): null {
    if (this.resting) return null;
    const customer = world.orders.takeReady((c) => world.isActive(c));
    if (customer) {
      const path = world.findPath(
        this.mover.tileX,
        this.mover.tileY,
        this.home.x,
        this.home.y,
        false,
      );
      if (!path) {
        world.orders.returnReady(customer);
        return null;
      }
      this.customer = customer;
      this.mover.setPath(path);
      this.state = 'toKitchen';
      return null;
    }

    const plate = world.orders.claimPlate();
    if (plate) {
      const path = world.findPath(
        this.mover.tileX,
        this.mover.tileY,
        plate.table.tileX,
        plate.table.tileY,
        true,
      );
      if (!path) {
        world.orders.releasePlate(plate);
        return null;
      }
      this.plate = plate;
      this.mover.setPath(path);
      this.state = 'toPlate';
    }
    return null;
  }

  /** Блюдо в руках — идём к гостю. */
  private startDelivery(world: WaiterWorld): null {
    const customer = this.customer;
    if (!customer || !world.isActive(customer) || !customer.chair) {
      this.customer = null;
      this.goHome(world);
      return null;
    }
    const path = world.findPath(
      this.mover.tileX,
      this.mover.tileY,
      customer.chair.tileX,
      customer.chair.tileY,
      true,
    );
    if (!path) {
      // Не дойти — возвращаем блюдо в раздачу, пусть попробует другой круг.
      world.orders.returnReady(customer);
      this.customer = null;
      this.goHome(world);
      return null;
    }
    this.carrying = true;
    this.mover.setPath(path);
    this.state = 'toCustomer';
    return null;
  }

  private finishDelivery(world: WaiterWorld): WaiterEvent | null {
    const customer = this.customer;
    this.customer = null;
    this.carrying = false;
    this.goHome(world);
    if (!customer || !world.isActive(customer)) return null;
    customer.eatOrder();
    return { type: 'served', customer };
  }

  private goHome(world: WaiterWorld): void {
    const path = world.findPath(
      this.mover.tileX,
      this.mover.tileY,
      this.home.x,
      this.home.y,
      false,
    );
    this.mover.setPath(path ?? [this.home]);
    this.state = 'back';
  }

  reset(): void {
    this.mover.teleport(this.home.x, this.home.y);
    this.state = 'idle';
    this.timer = 0;
    this.customer = null;
    this.plate = null;
    this.carrying = false;
  }
}
