/**
 * Состояние игрока в одном месте: расстановка зала + экономика (монеты, опыт,
 * спрос). Хранится одним ключом в localStorage и версионируется — этот же
 * объект позже уедет на сервер как снапшот, поэтому формат сериализуемый и
 * плоский.
 *
 * Раньше layout лежал отдельным ключом, а деньги вообще не сохранялись
 * (переменная в замыкании сцены) — из-за чего перезагрузка обнуляла прогресс.
 */

import { engine } from '@rv/shared';

const STORAGE_KEY = 'rv:player:v1';
/** Ключ старого формата — переносим расстановку и удаляем. */
const LEGACY_LAYOUT_KEY = 'rv:layout:v1';

export type PlayerState = {
  version: 1;
  layout: engine.RestaurantLayout;
  economy: engine.EconomyState;
  /** Мусор на полу и «долг» по нему — копится и пока игра закрыта. */
  trash: engine.TrashState;
  /** Износ туалетов и автоматов (usageCount по id предмета). */
  facilities: engine.FacilitiesState;
  /** Нанятый штат: кто на какой должности и сколько у кого сил. */
  staff: engine.StaffState;
  /** Момент последнего сохранения — база для офлайн-накопления. */
  savedAt: number;
};

function defaultState(): PlayerState {
  return {
    version: 1,
    layout: engine.defaultLayout,
    economy: { coins: 0, cash: 0, gourmetPoints: 0, demandPoints: engine.Balance.MIN_DEMAND },
    trash: { target: 0, timerMs: engine.Balance.TRASH_APPEAR_RATE_MS, items: [] },
    staff: { roster: engine.Roster.withStarters().toJSON() },
    facilities: { usage: {} },
    savedAt: Date.now(),
  };
}

function isLayout(value: unknown): value is engine.RestaurantLayout {
  const l = value as engine.RestaurantLayout | null;
  return (
    !!l && typeof l.width === 'number' && typeof l.height === 'number' && Array.isArray(l.items)
  );
}

export function loadPlayerState(): PlayerState {
  const fallback = defaultState();
  if (typeof window === 'undefined') return fallback;

  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<PlayerState>;
      return {
        version: 1,
        layout: isLayout(parsed.layout) ? parsed.layout : fallback.layout,
        economy: { ...fallback.economy, ...(parsed.economy ?? {}) },
        trash: { ...fallback.trash, ...(parsed.trash ?? {}) },
        // roster появился вместе с наймом; workTime оставлен для миграции старых сейвов.
        staff: {
          workTime: parsed.staff?.workTime,
          roster: parsed.staff?.roster,
        },
        facilities: { ...fallback.facilities, ...(parsed.facilities ?? {}) },
        savedAt: typeof parsed.savedAt === 'number' ? parsed.savedAt : fallback.savedAt,
      };
    }

    // Миграция со старого ключа: расстановка была, денег не было.
    const legacy = window.localStorage.getItem(LEGACY_LAYOUT_KEY);
    if (legacy) {
      const layout = JSON.parse(legacy) as unknown;
      if (isLayout(layout)) {
        fallback.layout = layout;
        window.localStorage.removeItem(LEGACY_LAYOUT_KEY);
        savePlayerState(fallback);
      }
    }
  } catch (err) {
    console.warn('loadPlayerState: не удалось прочитать сохранение, беру дефолт', err);
  }
  return fallback;
}

export function savePlayerState(state: PlayerState): void {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, savedAt: Date.now() }));
  } catch (err) {
    console.warn('savePlayerState: не удалось сохранить', err);
  }
}

/** Сохранить текущее состояние симуляции (вызывается после правок и по таймеру). */
export function saveSim(sim: engine.RestaurantSim): void {
  savePlayerState({
    version: 1,
    layout: sim.restaurant.serialize(),
    economy: sim.economy.toJSON(),
    trash: sim.trash.toJSON(),
    staff: sim.staffState(),
    facilities: sim.facilities.toJSON(),
    savedAt: Date.now(),
  });
}

/** Сбросить прогресс к стартовому ресторану. */
export function resetPlayerState(): void {
  if (typeof window === 'undefined') return;
  window.localStorage.removeItem(STORAGE_KEY);
  window.localStorage.removeItem(LEGACY_LAYOUT_KEY);
}
