/**
 * Уборщик (порт CleanerEmployee.as, сокращённый).
 *
 * Цикл оригинала: IDLE → выбрать ближайшую достижимую мусорку (если мусора нет —
 * побродить на случайную клетку) → WALKING → CLEANING на cleanDurationMs →
 * убрать мусорку → IDLE с паузой CLEANER_IDLE_MS.
 *
 * Приоритет задач — как в оригинале: сначала починка сломанных туалетов и
 * автоматов (`cleanNextToiletSeat() || fixNextFunctionalItem()`), потом мусор,
 * и только если делать нечего — прогулка по случайной клетке.
 */

import type { TileCoord } from '../../grid';
import { Balance, cleanDurationMs } from '../balance';
import { type Employee, Job } from '../employees';
import { energyOf } from '../staff';
import type { TrashItem, TrashSystem } from '../trash';
import type { PlacedItem } from '../types';
import { PathMover } from './mover';

export type CleanerState = 'idle' | 'walking' | 'cleaning' | 'repairing';

/** Что уборщику нужно от мира — узкий срез RestaurantSim. */
export type CleanerWorld = {
  findPath(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    stopNextToDestination: boolean,
  ): TileCoord[] | null;
  readonly trash: TrashSystem;
  rand(min: number, max: number): number;
  /** Случайная проходимая клетка — куда побродить, когда мусора нет. */
  randomWalkableTile(): TileCoord | null;
  /** Сломанные туалеты и автоматы — их чинят в первую очередь. */
  brokenFacilities(): PlacedItem[];
  repairFacility(itemId: string): boolean;
};

export type CleanerEvent =
  | { type: 'cleaned'; item: TrashItem }
  | { type: 'repaired'; item: PlacedItem };

export class CleanerActor {
  readonly mover: PathMover;
  readonly home: TileCoord;

  state: CleanerState = 'idle';

  /**
   * Кто именно на этой должности. Актёр — лишь «тело» сотрудника: запас сил и
   * состояние отдыха живут в Employee и переживают перестановку мебели.
   */
  readonly employee: Employee;

  /** id сотрудника — он же ключ актёра для рендера и сохранений. */
  get id(): string {
    return this.employee.id;
  }

  /** Запас сил, мс (GameUserEmployee.workTime). */
  get workTime(): number {
    return this.employee.workTime;
  }

  set workTime(value: number) {
    this.employee.workTime = Math.max(0, Math.min(Balance.MAX_WORK_TIME_MS, value));
  }

  /**
   * Не работает: либо отправлен на отдых, либо свалился без сил.
   * В оригинале выдохшийся сотрудник вставал в ANIMATION_DEAD и сам на смену
   * не возвращался — нужно было либо покормить, либо перевести в JOB_REST.
   */
  get resting(): boolean {
    return this.employee.job === Job.Rest || this.employee.workTime <= 0;
  }

  /** Доля сил 0..1. */
  get energy(): number {
    return energyOf(this.workTime);
  }

  private timer: number = Balance.CLEANER_IDLE_MS;
  private target: TrashItem | null = null;
  /** Сломанный предмет, который уборщик идёт чинить. */
  private repairTarget: PlacedItem | null = null;

  constructor(employee: Employee, home: TileCoord) {
    this.employee = employee;
    this.home = { x: home.x, y: home.y };
    this.mover = new PathMover(home.x, home.y);
  }

  /** Мусорка, за которой уборщик сейчас идёт (для подсветки в UI). */
  get targetTrashId(): string | null {
    return this.target?.id ?? null;
  }

  /** Предмет, который уборщик сейчас чинит или идёт чинить. */
  get targetFacilityId(): string | null {
    return this.repairTarget?.id ?? null;
  }

  tick(dtMs: number, world: CleanerWorld): CleanerEvent | null {
    this.mover.advance(dtMs);

    switch (this.state) {
      case 'idle': {
        if (this.resting) return null;
        this.timer -= dtMs;
        if (this.timer > 0) return null;
        this.pickTask(world);
        return null;
      }

      case 'walking': {
        // Задачу закрыли без нас (игрок тапнул) — ищем новую.
        if (this.target && !world.trash.byId(this.target.id)) {
          this.target = null;
          this.mover.clear();
          this.goIdle();
          return null;
        }
        if (this.repairTarget && !this.stillBroken(world, this.repairTarget)) {
          this.repairTarget = null;
          this.mover.clear();
          this.goIdle();
          return null;
        }
        if (!this.mover.arrived) return null;
        if (this.repairTarget) {
          this.state = 'repairing';
          this.timer = cleanDurationMs(this.energy);
          return null;
        }
        if (!this.target) {
          this.goIdle();
          return null;
        }
        this.state = 'cleaning';
        this.timer = cleanDurationMs(this.energy);
        return null;
      }

      case 'repairing': {
        this.timer -= dtMs;
        if (this.timer > 0) return null;
        const item = this.repairTarget;
        this.repairTarget = null;
        this.goIdle();
        if (!item || !world.repairFacility(item.id)) return null;
        return { type: 'repaired', item };
      }

      case 'cleaning': {
        this.timer -= dtMs;
        if (this.timer > 0) return null;
        const item = this.target;
        this.target = null;
        this.goIdle();
        if (!item || !world.trash.byId(item.id)) return null;
        world.trash.remove(item);
        return { type: 'cleaned', item };
      }
    }
  }

  private stillBroken(world: CleanerWorld, item: PlacedItem): boolean {
    return world.brokenFacilities().some((f) => f.id === item.id);
  }

  /** Сначала починка, потом мусор, потом прогулка — порядок оригинала. */
  private pickTask(world: CleanerWorld): void {
    const broken = world.brokenFacilities();
    if (broken.length > 0) {
      // Ближайший по манхэттену сломанный предмет, до которого есть путь.
      const sorted = [...broken].sort(
        (a, b) =>
          Math.abs(a.tileX - this.mover.tileX) +
          Math.abs(a.tileY - this.mover.tileY) -
          (Math.abs(b.tileX - this.mover.tileX) + Math.abs(b.tileY - this.mover.tileY)),
      );
      for (const facility of sorted) {
        const path = world.findPath(
          this.mover.tileX,
          this.mover.tileY,
          facility.tileX,
          facility.tileY,
          true,
        );
        if (!path) continue;
        this.repairTarget = facility;
        this.mover.setPath(path);
        this.state = 'walking';
        return;
      }
    }

    const item = world.trash.nearestFree(this.mover.tileX, this.mover.tileY);
    if (item) {
      const path = world.findPath(
        this.mover.tileX,
        this.mover.tileY,
        item.tileX,
        item.tileY,
        false,
      );
      if (path) {
        world.trash.claim(item, this.id);
        this.target = item;
        this.mover.setPath(path);
        this.state = 'walking';
        return;
      }
    }
    // Мусора нет или он недостижим — идём на случайную клетку.
    const tile = world.randomWalkableTile();
    if (!tile) {
      this.goIdle();
      return;
    }
    const path = world.findPath(this.mover.tileX, this.mover.tileY, tile.x, tile.y, false);
    if (!path) {
      this.goIdle();
      return;
    }
    this.mover.setPath(path);
    this.state = 'walking';
  }

  private goIdle(): void {
    this.state = 'idle';
    this.timer = Balance.CLEANER_IDLE_MS;
  }

  reset(world?: CleanerWorld): void {
    if (this.target && world) world.trash.release(this.target);
    this.target = null;
    this.repairTarget = null;
    this.mover.teleport(this.home.x, this.home.y);
    this.state = 'idle';
    this.timer = Balance.CLEANER_IDLE_MS;
  }
}
