/**
 * Сцена улицы (WorldStreet, упрощённо).
 *
 * Фронт-вид: ряд фасадов (твой ресторан + соседи) на тротуаре, твой кастомный
 * 3D-аватар стоит перед своим зданием. Клик по своему зданию — войти в ресторан;
 * клик по соседу — визит (заглушка/коллбэк). Фасады пока стилизованные Graphics —
 * реальные спрайты из outdoor_asset подключим следующим шагом (S3).
 */

import { Application, Assets, Container, Graphics, Sprite, Text, Texture } from 'pixi.js';
import { asset } from '../asset-url';
import { loadAvatarConfig } from '../avatar/avatar-config';
import { PlayerAvatarRenderer } from '../avatar/player-avatar';
import { audio } from './audio';
import { type FacadeConfig, type RoofKind, loadFacadeConfig } from './facade-config';

/** Реальные спрайты фасада из outdoor_asset.swf (отрендерены FFDec). */
const FACADE_URLS = {
  door: asset('facade/door.png'),
  window: asset('facade/window.png'),
  good: asset('facade/roof_good.png'),
  cupcake: asset('facade/roof_cupcake.png'),
  saloon: asset('facade/roof_saloon.png'),
  spooky: asset('facade/roof_spooky.png'),
  egyptian: asset('facade/roof_egyptian.png'),
  nest: asset('facade/roof_nest.png'),
  classic: asset('facade/roof_classic.png'),
  modern: asset('facade/roof_modern.png'),
} as const;
type FacadeTextures = Record<keyof typeof FACADE_URLS, Texture>;

export type StreetHandle = {
  destroy(): void;
  /** Живое обновление фасада здания игрока (из редактора экстерьера). */
  setPlayerFacade(cfg: FacadeConfig): void;
};

export type StreetOptions = {
  onEnterRestaurant: () => void;
  onVisit: (name: string) => void;
};

/** Эффективные значения для отрисовки одного фасада. */
type FacadeView = {
  name: string;
  isPlayer: boolean;
  accent: number;
  roof: RoofKind;
  bodyColor: number;
};

type BuildingDef = { name: string; isPlayer: boolean; accent: number; roof: RoofKind };

const NEIGHBOURS: BuildingDef[] = [
  { name: "Mia's Diner", isPlayer: false, accent: 0xe07a5f, roof: 'cupcake' },
  { name: 'Твой ресторан', isPlayer: true, accent: 0x2f9ac8, roof: 'good' },
  { name: "Leo's Bistro", isPlayer: false, accent: 0x81b29a, roof: 'saloon' },
  { name: 'Sakura Sushi', isPlayer: false, accent: 0xc77dff, roof: 'spooky' },
];

const FACADE_W = 180;
const FACADE_H = 220;
const FACADE_GAP = 36;

export async function startStreetScene(
  mountEl: HTMLDivElement,
  opts: StreetOptions,
): Promise<StreetHandle> {
  const app = new Application();
  await app.init({
    resizeTo: mountEl,
    backgroundAlpha: 0,
    antialias: true,
    resolution: window.devicePixelRatio || 1,
    autoDensity: true,
    preserveDrawingBuffer: true,
  });
  mountEl.appendChild(app.canvas);

  // Реальные спрайты фасада (дверь/окно/крыши).
  const facadeAssets = (await Assets.load(Object.values(FACADE_URLS))) as Record<string, Texture>;
  const facadeTex = Object.fromEntries(
    Object.entries(FACADE_URLS).map(([k, url]) => [k, facadeAssets[url]]),
  ) as FacadeTextures;

  // MusicStreet — свой трек у улицы, как в оригинале.
  audio.init();
  void audio.playMusic('music-street');

  const stage = new Container();
  app.stage.addChild(stage);

  // Небо + земля (фон).
  const bg = new Graphics();
  stage.addChild(bg);

  // Ряд зданий.
  const row = new Container();
  stage.addChild(row);

  let facadeCfg = loadFacadeConfig();
  const totalW = NEIGHBOURS.length * FACADE_W + (NEIGHBOURS.length - 1) * FACADE_GAP;
  let playerCenterX = 0;
  let playerFacade: Container | null = null;
  let playerX = 0;

  /** Эффективный вид фасада: для игрока — из FacadeConfig, для соседей — из дефолта. */
  function viewFor(b: BuildingDef): FacadeView {
    if (b.isPlayer) {
      return {
        name: facadeCfg.name,
        isPlayer: true,
        accent: facadeCfg.accentColor,
        roof: facadeCfg.roof,
        bodyColor: facadeCfg.bodyColor,
      };
    }
    return { name: b.name, isPlayer: false, accent: b.accent, roof: b.roof, bodyColor: 0xf3ead6 };
  }

  function addFacade(b: BuildingDef, x: number): Container {
    const facade = makeFacade(viewFor(b), facadeTex);
    facade.position.set(x, 0);
    facade.eventMode = 'static';
    facade.cursor = 'pointer';
    facade.on('pointertap', () => {
      if (b.isPlayer) opts.onEnterRestaurant();
      else opts.onVisit(b.name);
    });
    row.addChild(facade);
    return facade;
  }

  NEIGHBOURS.forEach((b, i) => {
    const x = -totalW / 2 + i * (FACADE_W + FACADE_GAP) + FACADE_W / 2;
    const facade = addFacade(b, x);
    if (b.isPlayer) {
      playerCenterX = x;
      playerX = x;
      playerFacade = facade;
    }
  });

  const playerDef = NEIGHBOURS.find((b) => b.isPlayer)!;

  function rebuildPlayerFacade(cfg: FacadeConfig): void {
    facadeCfg = cfg;
    if (playerFacade) {
      row.removeChild(playerFacade);
      playerFacade.destroy();
    }
    playerFacade = addFacade(playerDef, playerX);
  }

  // Аватар игрока перед своим зданием (по сохранённой конфигурации).
  const cfg = loadAvatarConfig();
  const avatar = new PlayerAvatarRenderer(160, 320, cfg);
  const avatarTex = Texture.from(avatar.canvas);
  const avatarSprite = new Sprite(avatarTex);
  avatarSprite.anchor.set(0.5, 0.96);
  avatarSprite.scale.set(0.62);
  stage.addChild(avatarSprite);

  // ── Камера / фон по размеру экрана ───────────────────────────────
  function layout(): void {
    const W = app.screen.width;
    const H = app.screen.height;
    // Фон: небо градиентом (полосами) + тротуар.
    bg.clear();
    bg.rect(0, 0, W, H).fill({ color: 0x9fd3e8 });
    bg.rect(0, H * 0.62, W, H * 0.38).fill({ color: 0x6b7682 }); // дорога
    bg.rect(0, H * 0.58, W, H * 0.06).fill({ color: 0x9aa3ad }); // тротуар
    // Ряд зданий: основания на линии тротуара, центрирован по горизонтали.
    const groundY = H * 0.6;
    row.position.set(W / 2, groundY);
    // Аватар перед своим зданием, чуть ниже (на тротуаре).
    avatarSprite.position.set(W / 2 + playerCenterX, groundY + 20);
  }
  layout();
  app.renderer.on('resize', layout);

  // ── Tick ─────────────────────────────────────────────────────────
  const tickFn = (ticker: { deltaMS: number }): void => {
    if (avatar.ready) {
      avatar.play('idle');
      avatar.update(ticker.deltaMS / 1000);
      avatarTex.source.update();
      avatarSprite.visible = true;
    } else {
      avatarSprite.visible = false;
    }
  };
  app.ticker.add(tickFn);

  const canvasRef = app.canvas;
  let destroyed = false;
  return {
    destroy(): void {
      if (destroyed) return;
      destroyed = true;
      try {
        app.ticker.remove(tickFn);
        avatar.dispose();
        app.destroy(true, { children: true, texture: true });
      } catch {
        /* ignore */
      }
      if (canvasRef && mountEl.contains(canvasRef)) mountEl.removeChild(canvasRef);
    },
    setPlayerFacade(cfg: FacadeConfig): void {
      if (!destroyed) rebuildPlayerFacade(cfg);
    },
  };
}

/** Фасад: цветное тело (Graphics) + РЕАЛЬНЫЕ спрайты крыши/двери/окон. */
function makeFacade(b: FacadeView, tex: FacadeTextures): Container {
  const c = new Container();
  const W = FACADE_W;
  const H = FACADE_H;
  const body = new Graphics();

  // Тень на тротуаре.
  body.ellipse(0, 6, W * 0.55, 12).fill({ color: 0x000000, alpha: 0.18 });
  // Тело здания (основание на y=0, растёт вверх). У игрока — акцентная рамка.
  body
    .roundRect(-W / 2, -H, W, H, 8)
    .fill({ color: b.bodyColor })
    .stroke({ color: b.isPlayer ? b.accent : 0xcdbfa3, width: b.isPlayer ? 4 : 2 });
  c.addChild(body);

  // Реальная крыша (спрайт), вписана по ширине фасада, низом на верхний край тела.
  const roof = new Sprite(tex[b.roof]);
  roof.anchor.set(0.5, 1);
  const roofScale = (W + 14) / roof.texture.width;
  roof.scale.set(roofScale);
  roof.position.set(0, -H + 6);
  c.addChild(roof);

  // Вывеска с названием (под крышей).
  const sign = new Graphics();
  sign.roundRect(-W / 2 + 12, -H + 26, W - 24, 22, 4).fill({ color: 0x2c2420, alpha: 0.85 });
  c.addChild(sign);
  const label = new Text({
    text: b.name,
    style: { fill: 0xffffff, fontSize: 13, fontFamily: 'sans-serif', fontWeight: '600' },
  });
  label.anchor.set(0.5);
  label.position.set(0, -H + 37);
  c.addChild(label);

  // Реальные окна (два, на средней зоне).
  for (const wx of [-W / 2 + 34, W / 2 - 34]) {
    const win = new Sprite(tex.window);
    win.anchor.set(0.5, 0.5);
    win.scale.set(1.25);
    win.position.set(wx, -H + 78);
    c.addChild(win);
  }

  // Реальная дверь (внизу по центру).
  const door = new Sprite(tex.door);
  door.anchor.set(0.5, 1);
  door.scale.set(1.2);
  door.position.set(0, -4);
  c.addChild(door);

  return c;
}
