/**
 * Меню ресторана: какие блюда игрок держит в меню и что заказывает гость.
 *
 * Порт WorldRestaurantPlay.createOrderForCustomer (:1165) + Recipe.as:
 *   - блюда делятся на 4 категории (Starter / Main / Dessert / Drink);
 *   - гость выбирает случайную КАТЕГОРИЮ, затем случайный рецепт из выбранных
 *     игроком в этой категории;
 *   - напитки доступны только с DRINK_START_LEVEL (15) — до него категория
 *     Drink из розыгрыша исключена;
 *   - число блюд на категорию ограничено уровнем (LevelInfo.numDishes).
 *
 * Уровень рецепта (1..10) в оригинале растёт от готовки и влияет ТОЛЬКО на
 * gourmet points и вид тарелки — цена блюда всегда recipe.cost.
 */

import recipesData from '../../content/data/recipes.json';
import { type Recipe as RecipeSchema, Recipe as RecipeZ } from '../../content/schemas';
import type { DishOrder } from '../customer/world';
import { Balance } from './balance';
import { getLevelInfo } from './levels';

export type RecipeCategory = RecipeSchema['category'];

export const RECIPE_CATEGORIES: readonly RecipeCategory[] = [
  'Starter',
  'Main',
  'Dessert',
  'Drink',
] as const;

const ALL_RECIPES: RecipeSchema[] = RecipeZ.array()
  .parse(recipesData)
  // Сезонные и невидимые рецепты в обычный оборот не попадают.
  .filter((r) => !r.isLimited && !r.invisible);

const BY_CATEGORY = new Map<RecipeCategory, RecipeSchema[]>();
for (const cat of RECIPE_CATEGORIES) {
  BY_CATEGORY.set(
    cat,
    ALL_RECIPES.filter((r) => r.category === cat),
  );
}

/** Все доступные рецепты (уже без сезонных). */
export function allRecipes(): readonly RecipeSchema[] {
  return ALL_RECIPES;
}

/** Рецепты одной категории. */
export function recipesInCategory(category: RecipeCategory): readonly RecipeSchema[] {
  return BY_CATEGORY.get(category) ?? [];
}

/** Рецепт по имени (имена в оригинале уникальны). */
export function findRecipe(name: string): RecipeSchema | null {
  return ALL_RECIPES.find((r) => r.name === name) ?? null;
}

/** Позиция меню: рецепт + его накопленный уровень (1..10). */
export type MenuEntry = {
  readonly recipeName: string;
  level: number;
};

/**
 * Меню игрока — по одному списку на категорию. Размер списка ограничен
 * LevelInfo.numDishes текущего уровня.
 */
export class Menu {
  private readonly entries: MenuEntry[];

  constructor(entries: MenuEntry[] = []) {
    this.entries = entries;
  }

  /** Стартовое меню: первые numDishes блюд каждой доступной категории. */
  static forLevel(level: number): Menu {
    const info = getLevelInfo(level);
    const entries: MenuEntry[] = [];
    for (const cat of RECIPE_CATEGORIES) {
      if (cat === 'Drink' && level < Balance.DRINK_START_LEVEL) continue;
      for (const r of recipesInCategory(cat).slice(0, info.numDishes)) {
        entries.push({ recipeName: r.name, level: 1 });
      }
    }
    return new Menu(entries);
  }

  list(): readonly MenuEntry[] {
    return this.entries;
  }

  inCategory(category: RecipeCategory): MenuEntry[] {
    return this.entries.filter((e) => findRecipe(e.recipeName)?.category === category);
  }

  /** Поднять уровень рецепта после успешной подачи (потолок 10). */
  levelUpRecipe(recipeName: string): void {
    const entry = this.entries.find((e) => e.recipeName === recipeName);
    if (entry && entry.level < 10) entry.level++;
  }

  toJSON(): MenuEntry[] {
    return this.entries.map((e) => ({ ...e }));
  }
}

let orderSeq = 0;

/**
 * Собрать заказ для гостя: случайная категория → случайное блюдо из меню.
 * Возвращает null, если меню пустое.
 */
export function createOrder(
  menu: Menu,
  level: number,
  rand: (min: number, max: number) => number,
): DishOrder | null {
  const pool = RECIPE_CATEGORIES.filter((c) => c !== 'Drink' || level >= Balance.DRINK_START_LEVEL);
  // Пробуем категории в случайном порядке, пока не найдём непустую.
  const shuffled = [...pool];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = rand(0, i);
    const a = shuffled[i]!;
    shuffled[i] = shuffled[j]!;
    shuffled[j] = a;
  }
  for (const category of shuffled) {
    const options = menu.inCategory(category);
    if (options.length === 0) continue;
    const entry = options[rand(0, options.length - 1)]!;
    const recipe = findRecipe(entry.recipeName);
    if (!recipe) continue;
    orderSeq++;
    return {
      id: `order-${orderSeq}`,
      recipeName: recipe.name,
      isDrink: recipe.category === 'Drink',
      cost: recipe.cost,
      level: entry.level,
      table: null,
    };
  }
  return null;
}
