/** События симуляции для рендера / UI / звука. */
export type SimEvent =
  | { type: 'customer-added'; customer: Customer }
  | { type: 'customer-left'; customer: Customer; happy: boolean }
  | { type: 'cooking-started'; customer: Customer }
  | { type: 'dish-served'; customer: Customer }
  | { type: 'plate-added'; plate: EmptyPlate }
  /** Тарелка убрана — ресторан получил деньги. tile — где всплывает «+N». */
  | { type: 'paid'; plate: EmptyPlate; payment: MealPayment; tile: TileCoord }
  | { type: 'level-up'; level: number; reward: number }
  /** Зал раздвинулся с уровнем — стены и сетку надо перерисовать. */
  | { type: 'room-grown'; width: number; height: number }
  | { type: 'trash-added'; item: TrashItem }
  /** Мусорка убрана (тапом игрока или уборщиком) — монеты и опыт. */
  | { type: 'trash-cleaned'; item: TrashItem; coins: number; points: number }
  /** Гость воспользовался автоматом — ресторан получил монету. */
  | { type: 'facility-paid'; item: PlacedItem; coins: number; points: number }
  /** Предмет сломался (туалет/автомат) — нужен уборщик или тап игрока. */
  | { type: 'facility-broken'; item: PlacedItem }
  | { type: 'facility-repaired'; item: PlacedItem }
  /** Куплен и поставлен предмет — списаны монеты. */
  | { type: 'item-bought'; item: PlacedItem; price: number }
  /** Продан предмет — начислены монеты и опыт. */
  | { type: 'item-sold'; contentId: number; refund: number; points: number }
  /** Сотруднику сменили должность. */
  | { type: 'employee-job'; employee: Employee; job: JobId }
  /** Сотрудник нанят на бирже. */
  | { type: 'employee-hired'; employee: Employee }
  /** Сотрудник уволен — со штрафом в монетах. */
  | { type: 'employee-fired'; employee: Employee; penalty: number }
  /** Сотрудника покормили — силы восстановлены. */
  | { type: 'employee-fed'; employee: Employee; perk: EmployeePerk }
  /** Сотрудник свалился без сил (ANIMATION_DEAD оригинала). */
  | { type: 'employee-exhausted'; employee: Employee }
  /** Зал закрылся или открылся: нужен повар И официант с силами. */
  | { type: 'restaurant-closed'; closed: boolean };

export type SimListener = (event: SimEvent) => void;

/** Почему сотрудник стоит без дела — порт EmployeeActor.EMOTION_* оригинала. */
export type IdleReason =
  /** JOB_REST: отдыхает (на кровати, если она есть). */
  | 'resting'
  /** JOB_NONE: нанят, но должность не назначена (EMOTION_NEED_JOB). */
  | 'needs-job'
  /** Повар без свободной плиты либо официант без кухни (EMOTION_NEED_STOVE). */
  | 'needs-stove';

/** Сотрудник без рабочего места — его всё равно надо нарисовать в зале. */
export type IdleStaff = {
  readonly employee: Employee;
  readonly reason: IdleReason;
  readonly tile: TileCoord;
  /** Кровать, на которой он спит, либо null. */
  readonly bed: PlacedItem | null;
};

/** Строчка панели персонала. */
export type EmployeeSummary = {
  id: string;
  name: string;
  job: JobId;
  look: Employee['look'];
  workTime: number;
  energy: number;
  /** Занят делом прямо сейчас (готовит, несёт, убирает). */
  busy: boolean;
  /** Переведён в JOB_REST игроком. */
  resting: boolean;
  /** Силы кончились — работать не может, пока не покормят или не уложат спать. */
  exhausted: boolean;
  idleReason: IdleReason | null;
  hasBed: boolean;
};

export type SimOptions = {
  layout: RestaurantLayout;
  economy?: Partial<EconomyState> | null;
  trash?: Partial<TrashState> | null;
  facilities?: Partial<FacilitiesState> | null;
  /** Сохранённый запас сил сотрудников. */
  staff?: Partial<StaffState> | null;
  /** Сколько игра была закрыта, мс — за это время копится мусор. */
  offlineMs?: number;
  /** Случайное целое в [min, max]. Подменяется в тестах на детерминированное. */
  rand?: (min: number, max: number) => number;
};

export class RestaurantSim implements CustomerWorld, WaiterWorld, CleanerWorld {
  readonly restaurant: WorldRestaurant;
  readonly economy: Economy;
  readonly orders = new OrderBoard();
  menu: Menu;

  /** Нанятый штат и биржа труда — единственный источник правды о персонале. */
  readonly roster: Roster;

  readonly customers: Customer[] = [];
  readonly chefs: ChefActor[] = [];
  readonly waiters: WaiterActor[] = [];
  readonly cleaners: CleanerActor[] = [];
  /** Сотрудники без рабочего места: отдыхающие, незанятые, повар без плиты. */
  readonly idleStaff: IdleStaff[] = [];
  readonly trash: TrashSystem;
  /** Износ туалетов и автоматов. */
  readonly facilities: Facilities;

  /**
   * Что заработал ресторан, пока игрока не было. Считается один раз в
   * конструкторе; клиент показывает это экраном «пока вас не было».
   */
  readonly offline: OfflineReport;

  /** Пауза симуляции (дизайн-режим): гости не приходят, актёры не тикают. */
  running = true;
  restaurantClosed = false;

  // ── Поля контракта CustomerWorld ──────────────────────────────────
  readonly waitingChairQueue: unknown[] = [];
  /** Бонус к терпению гостей от предметов (itemfunctions/AddCustomerWaitTime). */
  customerWaitTimeModifier = 0;

  private readonly randFn: (min: number, max: number) => number;
  private readonly listeners = new Set<SimListener>();
  /** Предыдущее состояние гостя — для отлова переходов (доел → тарелка). */
  private readonly prevState = new Map<Customer, CustomerState>();
  /** Оставшееся время «дверь открыта», по id двери. */
  private readonly doorTimers = new Map<string, number>();
  private spawnTimer = 0;
  private customerSeq = 0;

  constructor(opts: SimOptions) {
    this.restaurant = WorldRestaurant.fromLayout(opts.layout, lookupById);
    this.economy = Economy.fromJSON(opts.economy);
    this.randFn = opts.rand ?? ((min, max) => min + Math.floor(Math.random() * (max - min + 1)));
    this.menu = Menu.forLevel(this.economy.level);
    this.trash = new TrashSystem(opts.trash, this.randFn);
    this.facilities = new Facilities(opts.facilities);
    this.roster = createRoster(opts.staff);
    if (opts.offlineMs && opts.offlineMs > 0) this.trash.accrueOffline(opts.offlineMs);
    // Порт WorldRestaurant.init (:481): размер зала берётся из уровня, а не из
    // сохранения. Иначе старый сейв так и остался бы 8×8 после апдейта.
    this.restaurant.resize(...roomSizeForLevel(this.economy.level));
    this.applyItemFunctions();
    this.syncStaff();
    this.offline = this.computeOffline(opts.offlineMs ?? 0);
    this.spawnTimer = this.nextSpawnDelay();
  }

  // ── Подписка ──────────────────────────────────────────────────────

  on(listener: SimListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private emit(event: SimEvent): void {
    for (const l of this.listeners) l(event);
  }

  // ── Персонал ──────────────────────────────────────────────────────

  /** Сколько сотрудников можно держать — GameWorld.as:1251. */
  get maxEmployees(): number {
    return this.economy.levelInfo.employees;
  }

  /** Все кровати в зале (restaurant.xml, type="bed"). */
  private beds(): PlacedItem[] {
    return this.restaurant.getAllItems().filter((i) => isBed(i.definition));
  }

  /**
   * Пересобрать актёров под нанятый штат и текущую расстановку — порт
   * WorldRestaurantPlay.createEmployeeActor (:483).
   *
   * Штат больше не выводится из уровня: кто на какой должности, решает игрок.
   * Повару нужна свободная плита, официанту — хотя бы одна кухня; кому места не
   * нашлось, встаёт без дела с той же табличкой, что в оригинале
   * (EMOTION_NEED_STOVE / EMOTION_NEED_JOB).
   */
  syncStaff(): void {
    this.chefs.length = 0;
    this.waiters.length = 0;
    this.cleaners.length = 0;
    this.idleStaff.length = 0;

    this.roster.refreshBeds(this.beds());

    const stoves = this.restaurant.getKitchens();
    const freeStoves = [...stoves];

    // Сначала повара — они занимают плиты, от которых зависят места официантов.
    for (const employee of this.roster.list) {
      if (employee.job !== Job.Cook) continue;
      const stove = freeStoves.shift();
      if (stove) this.chefs.push(new ChefActor(employee, stove));
      else this.addIdleStaff(employee, 'needs-stove');
    }

    for (const employee of this.roster.list) {
      switch (employee.job) {
        case Job.Cook:
          break; // уже расставлены выше
        case Job.Waiter: {
          const stove = stoves[0];
          const home = stove ? this.waiterHomeTile(stove) : null;
          if (home) this.waiters.push(new WaiterActor(employee, home));
          else this.addIdleStaff(employee, 'needs-stove');
          break;
        }
        case Job.Cleaner: {
          const home =
            this.restaurant.getDoorEntrances()[0]?.insideTile ?? this.randomWalkableTile();
          if (home) this.cleaners.push(new CleanerActor(employee, home));
          else this.addIdleStaff(employee, 'needs-job');
          break;
        }
        case Job.Rest:
          this.addIdleStaff(employee, 'resting');
          break;
        default:
          this.addIdleStaff(employee, 'needs-job');
      }
    }

    this.refreshRestaurantClosedState();
  }

  /** Поставить сотрудника без рабочего места: на кровать или к свободной клетке. */
  private addIdleStaff(employee: Employee, reason: IdleReason): void {
    const bed = employee.bedItemId ? this.restaurant.getItem(employee.bedItemId) : null;
    const tile = bed
      ? { x: bed.tileX, y: bed.tileY }
      : this.freeStandingTile(this.idleStaff.length);
    if (!tile) return;
    this.idleStaff.push({ employee, reason, tile, bed: bed ?? null });
  }

  /**
   * Клетка «постоять в сторонке»: ближайшие ко входу проходимые тайлы, не
   * занятые другими актёрами. index разводит сотрудников по разным клеткам.
   */
  private freeStandingTile(index: number): TileCoord | null {
    const anchor = this.restaurant.getDoorEntrances()[0]?.insideTile ?? { x: 0, y: 0 };
    const taken = new Set<string>();
    for (const a of [...this.chefs, ...this.waiters, ...this.cleaners]) {
      taken.add(`${a.mover.tileX},${a.mover.tileY}`);
    }
    for (const i of this.idleStaff) taken.add(`${i.tile.x},${i.tile.y}`);

    const free: TileCoord[] = [];
    for (let y = 0; y < this.restaurant.height; y++) {
      for (let x = 0; x < this.restaurant.width; x++) {
        if (!this.restaurant.isWalkable(x, y)) continue;
        if (taken.has(`${x},${y}`)) continue;
        free.push({ x, y });
      }
    }
    if (free.length === 0) return null;
    free.sort(
      (a, b) =>
        Math.abs(a.x - anchor.x) +
        Math.abs(a.y - anchor.y) -
        (Math.abs(b.x - anchor.x) + Math.abs(b.y - anchor.y)),
    );
    return free[Math.min(index, free.length - 1)] ?? null;
  }

  /** Проходимый сосед плиты, не занятый поваром — точка ожидания официанта. */
  private waiterHomeTile(stove: PlacedItem): TileCoord | null {
    const taken = new Set(this.chefs.map((c) => `${c.mover.tileX},${c.mover.tileY}`));
    const candidates: TileCoord[] = [
      { x: stove.tileX, y: stove.tileY + 1 },
      { x: stove.tileX + 1, y: stove.tileY },
      { x: stove.tileX, y: stove.tileY - 1 },
      { x: stove.tileX - 1, y: stove.tileY },
    ];
    const walkable = candidates.filter((t) => this.restaurant.isWalkable(t.x, t.y));
    return walkable.find((t) => !taken.has(`${t.x},${t.y}`)) ?? walkable[0] ?? null;
  }

  /**
   * Применить функции расставленных предметов (itemfunctions/ оригинала).
   * Пока поддержаны только те, что двигают баланс зала.
   */
  private applyItemFunctions(): void {
    this.economy.maxDemand = Balance.DEFAULT_MAX_DEMAND;
    this.customerWaitTimeModifier = 0;
    for (const item of this.restaurant.getAllItems()) {
      for (const fn of item.definition.functions ?? []) {
        if (fn.startsWith('AddMaxDemand')) this.economy.maxDemand += 20;
        else if (fn === 'AddCustomerWaitTime') this.customerWaitTimeModifier = 1000;
      }
    }
  }

  /** Вызывать после любой правки расстановки (дизайн-режим). */
  onLayoutChanged(): void {
    this.applyItemFunctions();
    this.syncStaff();
    // Счётчики износа предметов, которых больше нет в зале, не нужны.
    this.facilities.prune(this.restaurant.getAllItems().map((i) => i.id));
  }

  // ── Персонал ──────────────────────────────────────────────────────

  /** Все актёры-сотрудники одним списком. */
  private allStaff(): Array<ChefActor | WaiterActor | CleanerActor> {
    return [...this.chefs, ...this.waiters, ...this.cleaners];
  }

  /** Соискатели на бирже труда. */
  candidates(): Candidate[] {
    return this.roster.candidates();
  }

  /**
   * Нанять соискателя — порт WorldHireEmployeePopUp.onHireTickClick.
   * Найм бесплатный и даёт GOURMET_POINTS_HIRE_EMPLOYEE опыта; ограничение
   * одно — число слотов текущего уровня.
   */
  hireEmployee(
    candidateId: string,
  ): { ok: true; employee: Employee } | { ok: false; reason: string } {
    const result = this.roster.hire(candidateId, this.maxEmployees);
    if (!result.ok) return { ok: false, reason: result.reason };
    const levelBefore = this.economy.level;
    this.economy.gourmetPoints += Balance.GOURMET_POINTS_HIRE_EMPLOYEE;
    this.syncStaff();
    this.emit({ type: 'employee-hired', employee: result.employee });
    this.checkLevelUp(levelBefore);
    return { ok: true, employee: result.employee };
  }

  /**
   * Уволить — порт WorldSackEmployee.onTickClick: штраф FIRE_EMPLOYEE_PENALTY
   * и проверка «монет должно хватить с запасом» (money + penalty > 0).
   */
  fireEmployee(id: string): { ok: true; penalty: number } | { ok: false; reason: string } {
    const penalty = Balance.FIRE_EMPLOYEE_PENALTY;
    if (this.economy.coins + penalty <= 0) return { ok: false, reason: 'no-coins' };
    const employee = this.roster.fire(id);
    if (!employee) return { ok: false, reason: 'not-found' };
    this.economy.coins += penalty;
    this.syncStaff();
    this.emit({ type: 'employee-fired', employee, penalty });
    return { ok: true, penalty };
  }

  /** Назначить должность — порт кнопок Cook / Waitor / Cleaner / Rest попапа. */
  setEmployeeJob(id: string, job: JobId): boolean {
    if (!this.roster.setJob(id, job)) return false;
    const employee = this.roster.get(id);
    this.syncStaff();
    if (employee) this.emit({ type: 'employee-job', employee, job });
    return true;
  }

  /**
   * Покормить сотрудника — порт WorldEmployeePopUp.onItemClicked: перк из
   * группы «Employee» покупается за монеты и сразу возвращает силы.
   */
  feedEmployee(
    id: string,
    perkId: number,
  ): { ok: true; perk: EmployeePerk } | { ok: false; reason: string } {
    const perk = lookupPerk(perkId);
    if (!perk) return { ok: false, reason: 'not-found' };
    const employee = this.roster.get(id);
    if (!employee) return { ok: false, reason: 'not-found' };
    if (this.economy.coins < perk.cost) return { ok: false, reason: 'no-coins' };
    const wasDown = employee.workTime <= 0;
    this.economy.spendCoins(perk.cost);
    this.roster.feed(id, perk);
    if (wasDown) this.syncStaff();
    this.refreshRestaurantClosedState();
    this.emit({ type: 'employee-fed', employee, perk });
    return { ok: true, perk };
  }

  /**
   * Отправить на отдых / вернуть на смену. Тонкая обёртка над сменой должности:
   * возврат ставит прежнюю работу, как если бы игрок нажал её кнопку заново.
   */
  setStaffResting(id: string, resting: boolean): boolean {
    const changed = resting ? this.roster.setJob(id, Job.Rest) : this.roster.backToWork(id);
    if (!changed) return false;
    const employee = this.roster.get(id);
    this.syncStaff();
    if (employee) this.emit({ type: 'employee-job', employee, job: employee.job });
    return true;
  }

  /** Сводка по сотруднику для панели персонала. */
  staffRoster(): EmployeeSummary[] {
    const busy = new Map<string, boolean>();
    for (const c of this.chefs) busy.set(c.id, c.state === 'cooking');
    for (const w of this.waiters) busy.set(w.id, w.state !== 'idle');
    for (const c of this.cleaners) busy.set(c.id, c.state !== 'idle');
    const idle = new Map(this.idleStaff.map((i) => [i.employee.id, i.reason] as const));

    return this.roster.list.map((employee) => ({
      id: employee.id,
      name: employee.name,
      job: employee.job,
      look: employee.look,
      workTime: employee.workTime,
      energy: energyOf(employee.workTime),
      busy: busy.get(employee.id) ?? false,
      resting: employee.job === Job.Rest,
      exhausted: employee.workTime <= 0,
      idleReason: idle.get(employee.id) ?? null,
      hasBed: employee.bedItemId !== null,
    }));
  }

  /** Снимок штата для сохранения. */
  staffState(): StaffState {
    return { roster: this.roster.toJSON() };
  }

  /**
   * Списать силы за прошедшее время — порт GameUser.tick (:857).
   * Выдохшийся НЕ уходит отдыхать сам: в оригинале он падал (ANIMATION_DEAD)
   * и ждал, пока игрок его покормит или переведёт в JOB_REST.
   */
  private tickStaffEnergy(dtMs: number): void {
    const down = new Set(this.roster.list.filter((e) => e.workTime <= 0).map((e) => e.id));
    this.roster.tick(dtMs, (employee) => {
      const bed = employee.bedItemId ? this.restaurant.getItem(employee.bedItemId) : null;
      return bed?.definition ?? null;
    });
    for (const employee of this.roster.list) {
      if (employee.workTime <= 0 && !down.has(employee.id)) {
        this.emit({ type: 'employee-exhausted', employee });
      }
    }
    this.refreshRestaurantClosedState();
  }

  /**
   * Зал работает, только если есть повар И официант с остатком сил —
   * порт GameUser.isRestaurantClosed (:483) + refreshRestaurantClosedState.
   */
  private refreshRestaurantClosedState(): void {
    const closed = this.roster.isRestaurantClosed();
    if (closed === this.restaurantClosed) return;
    this.restaurantClosed = closed;
    this.emit({ type: 'restaurant-closed', closed });
  }

  /**
   * Уровень вырос — единственное место, где это обрабатывается.
   *
   * Меню, штат и размер зала завязаны на уровень, и раньше три точки начисления
   * опыта (оплата блюда, уборка мусора, найм) делали это каждая по-своему.
   */
  private checkLevelUp(levelBefore: number, reward = 0): void {
    const level = this.economy.level;
    if (level <= levelBefore) return;
    this.menu = Menu.forLevel(level);
    this.growRoomToLevel();
    this.syncStaff();
    this.emit({ type: 'level-up', level, reward });
  }

  /**
   * Раздвинуть зал под текущий уровень — порт onLevelUp (:916).
   *
   * Рассадка не ломается: клетка (0,0) остаётся дальним углом, новые ряды
   * прирастают к ближним стенам, координаты мебели не меняются.
   */
  private growRoomToLevel(): boolean {
    const [w, h] = roomSizeForLevel(this.economy.level);
    if (!this.restaurant.resize(w, h)) return false;
    this.emit({
      type: 'room-grown',
      width: this.restaurant.width,
      height: this.restaurant.height,
    });
    return true;
  }

  /** Множитель восстановления сил для сотрудника (учитывает кровать). */
  restMultiplierFor(employee: Employee): number {
    const bed = employee.bedItemId ? this.restaurant.getItem(employee.bedItemId) : null;
    return restMultiplier(bed?.definition ?? null);
  }

  /** Средние gourmet points за блюдо по текущему меню (для офлайн-расчёта). */
  private averageGourmetPerDish(): number {
    const entries = this.menu.list();
    if (entries.length === 0) return Balance.GOURMET_POINTS_PER_DISH;
    let sum = 0;
    for (const e of entries) sum += gourmetPointsForDish(e.level);
    return sum / entries.length;
  }

  /** Посчитать и сразу начислить офлайн-доход (порт GameWorld.init :1251-1265). */
  private computeOffline(elapsedMs: number): OfflineReport {
    if (elapsedMs <= 0) return EMPTY_OFFLINE_REPORT;

    // Считаем по должностям, а не по актёрам: в оригинале getOfflineCustomers
    // перебирал employeeUsers и смотрел именно job.
    const cooks = this.roster.byJob(Job.Cook);
    const waiters = this.roster.byJob(Job.Waiter);
    const report = offlineReport({
      elapsedMs,
      chefWorkTimes: cooks.map((e) => e.workTime),
      waiterWorkTimes: waiters.map((e) => e.workTime),
      demandPoints: this.economy.demandPoints,
      hasEntrance: this.restaurant.getDoorEntrances().length > 0,
      gourmetPerDish: this.averageGourmetPerDish(),
      totalEmployees: this.roster.size,
      restingEmployees: this.roster.byJob(Job.Rest).length,
    });

    // Пока игрока не было, отдыхающие тоже набирали силы.
    const awayMs = Math.max(0, elapsedMs);
    for (const employee of this.roster.byJob(Job.Rest)) {
      employee.workTime = Math.min(
        Balance.MAX_WORK_TIME_MS,
        employee.workTime + awayMs * this.restMultiplierFor(employee),
      );
    }
    if (report.customers === 0) return report;

    this.economy.coins += report.coins;
    this.economy.gourmetPoints += report.gourmetPoints;
    // Смена состоялась — силы на неё потрачены.
    const spent = report.workedSeconds * 1000;
    for (const employee of [...cooks, ...waiters]) {
      employee.workTime = Math.max(0, employee.workTime - spent);
    }
    return report;
  }

  // ── Главный тик ───────────────────────────────────────────────────

  tick(dtMs: number): void {
    if (!this.running) return;
    this.tickCustomers(dtMs);
    this.tickSpawn(dtMs);
    this.tickChefs(dtMs);
    this.tickWaiters(dtMs);
    this.tickTrash(dtMs);
    this.tickStaffEnergy(dtMs);
    this.tickDoors(dtMs);
  }

  /** Мусор копится по таймеру и досыпается на свободные клетки. */
  private tickTrash(dtMs: number): void {
    for (const item of this.trash.tick(dtMs, this.restaurant)) {
      this.emit({ type: 'trash-added', item });
    }
    for (const cleaner of this.cleaners) {
      const event = cleaner.tick(dtMs, this);
      // Починка сама эмиттит facility-repaired из repairFacility; за мусор платим тут.
      if (event?.type === 'cleaned') this.rewardTrash(event.item);
    }
  }

  /**
   * Убрать мусорку по тапу игрока. Возвращает false, если её уже нет.
   * Порт onTrashMouseDown → removeTrashObject (:2383).
   */
  cleanTrashAt(itemId: string): boolean {
    const item = this.trash.byId(itemId);
    if (!item) return false;
    this.trash.remove(item);
    this.rewardTrash(item);
    return true;
  }

  /** Награда за убранную мусорку: монеты + gourmet points. */
  private rewardTrash(item: TrashItem): void {
    const coins = Balance.TRASH_COIN_VALUE * this.randFn(1, Balance.TRASH_MAX_COINS);
    const points = Balance.GOURMET_POINTS_TRASH;
    const levelBefore = this.economy.level;
    this.economy.coins += coins;
    this.economy.gourmetPoints += points;
    this.emit({ type: 'trash-cleaned', item, coins, points });
    this.checkLevelUp(levelBefore);
  }

  private tickCustomers(dtMs: number): void {
    for (let i = this.customers.length - 1; i >= 0; i--) {
      const c = this.customers[i]!;
      const before = this.prevState.get(c) ?? c.state;
      c.tick(dtMs);
      const after = c.state;

      // Доел → на столе осталась грязная тарелка.
      if (before === CustomerState.Eating && after !== CustomerState.Eating) {
        this.onFinishedEating(c);
      }

      // Гость у двери — открыть её (порт Customer.tick:539).
      this.maybeOpenDoorFor(c);

      if (after === CustomerState.Left) {
        // Именно leftHappy: эмоция к этому моменту уже погашена.
        const happy = c.leftHappy === true;
        this.removeCustomer(c);
        this.emit({ type: 'customer-left', customer: c, happy });
        continue;
      }
      this.prevState.set(c, after);
    }
  }

  private onFinishedEating(c: Customer): void {
    const order = c.finishedOrder;
    c.finishedOrder = null;
    const table = order?.table;
    if (!order || !table) return;
    const plate = this.orders.addEmptyPlate(order, table);
    this.emit({ type: 'plate-added', plate });
  }

  private tickSpawn(dtMs: number): void {
    if (this.restaurantClosed) return;
    this.spawnTimer -= dtMs;
    if (this.spawnTimer > 0) return;
    this.spawnTimer = this.nextSpawnDelay();
    if (this.customers.length >= Balance.MAX_CONCURRENT_CUSTOMERS) return;
    this.spawnCustomer();
  }

  /** Интервал до следующего гостя — по текущему спросу, с разбросом. */
  private nextSpawnDelay(): number {
    const jitter = this.randFn(-Balance.SPAWN_JITTER_MS, Balance.SPAWN_JITTER_MS);
    return this.economy.nextCustomerDelayMs(jitter);
  }

  /**
   * Впустить гостя через случайную валидную дверь. Нет двери — нет гостей
   * (порт hasValidEntrances).
   */
  spawnCustomer(): Customer | null {
    const entrances = this.restaurant.getDoorEntrances();
    if (entrances.length === 0) return null;
    const entrance = entrances[this.randFn(0, entrances.length - 1)]!;
    const order = createOrder(this.menu, this.economy.level, this.randFn);
    if (!order) return null;

    this.customerSeq++;
    const customer = new Customer({
      id: `cust-${this.customerSeq}`,
      spawnTile: entrance.outsideTile,
      entranceTile: entrance.insideTile,
      doorTile: entrance.doorTile,
      outsideTile: entrance.outsideTile,
      door: entrance.door,
      order,
      world: this,
    });
    customer.on((e) => {
      if (e.type === 'facility-used') this.onFacilityUsed(e.itemId, e.kind);
    });
    this.customers.push(customer);
    this.prevState.set(customer, customer.state);
    customer.enter();
    this.emit({ type: 'customer-added', customer });
    return customer;
  }

  private tickChefs(dtMs: number): void {
    for (const chef of this.chefs) {
      const done = chef.tick(dtMs);
      if (done) this.orders.addReady(done);
      if (chef.state === 'idle' && !chef.resting) {
        const next = this.orders.takePending((c) => this.isActive(c));
        if (next) {
          chef.cook(next);
          this.emit({ type: 'cooking-started', customer: next });
        }
      }
    }
  }

  private tickWaiters(dtMs: number): void {
    for (const waiter of this.waiters) {
      const event = waiter.tick(dtMs, this);
      if (!event) continue;
      if (event.type === 'served') {
        this.emit({ type: 'dish-served', customer: event.customer });
      } else {
        this.onPlateCleared(event.plate, waiter);
      }
    }
  }

  /** Убрана тарелка → монеты + опыт (порт clearEmptyPlate → onCustomerPay). */
  private onPlateCleared(plate: EmptyPlate, waiter: WaiterActor): void {
    const payment = this.economy.payMeal(plate.order.cost, plate.order.level);
    this.menu.levelUpRecipe(plate.order.recipeName);
    this.emit({
      type: 'paid',
      plate,
      payment,
      tile: { x: waiter.mover.tileX, y: waiter.mover.tileY },
    });
    this.checkLevelUp(payment.levelBefore, payment.levelReward);
  }

  /**
   * Гость воспользовался туалетом или автоматом: предмет изнашивается, автомат
   * вдобавок приносит монету и gourmet point (порт onCustomerPayForFunctional).
   */
  private onFacilityUsed(itemId: string, kind: 'toilet' | 'interactive'): void {
    const item = this.restaurant.getItem(itemId);
    if (!item) return;
    const broke = this.facilities.use(item);
    if (kind === 'interactive') {
      const coins = this.economy.payFunctional();
      const points = Balance.GOURMET_POINTS_PER_FUNCTIONAL_ITEM;
      this.economy.gourmetPoints += points;
      this.emit({ type: 'facility-paid', item, coins, points });
    }
    if (broke) this.emit({ type: 'facility-broken', item });
  }

  /** Все сломанные функциональные предметы (для уборщика и подсветки в UI). */
  brokenFacilities(): PlacedItem[] {
    return [...this.restaurant.getToilets(), ...this.restaurant.getInteractiveItems()].filter(
      (item) => this.facilities.isBroken(item),
    );
  }

  /**
   * Починить предмет — уборщиком или тапом игрока (до найма уборщика чинить
   * некому). Возвращает false, если предмет цел или его уже нет.
   */
  repairFacility(itemId: string): boolean {
    const item = this.restaurant.getItem(itemId);
    if (!item || !this.facilities.isBroken(item)) return false;
    this.facilities.repair(item);
    this.emit({ type: 'facility-repaired', item });
    return true;
  }

  // ── Отладка ───────────────────────────────────────────────────────

  /**
   * Выдать валюту / поставить уровень — только для отладочной панели.
   * Уровень выставляется через порог gourmet points, чтобы не рассинхронить
   * прогресс: экономика везде считает уровень из опыта.
   */
  debugGrant(patch: {
    coins?: number;
    cash?: number;
    level?: number;
    demand?: number;
    trash?: number;
    refillStaff?: boolean;
  }): void {
    if (patch.coins) this.economy.coins = Math.max(0, this.economy.coins + patch.coins);
    if (patch.cash) this.economy.cash = Math.max(0, this.economy.cash + patch.cash);

    if (patch.level != null) {
      const target = Math.max(0, Math.min(MAX_LEVEL, Math.floor(patch.level)));
      this.economy.gourmetPoints = getLevelInfo(target).points;
      this.menu = Menu.forLevel(target);
      // Зал только растёт: уровень вниз оставит уже раздвинутые стены на месте
      // (иначе мебель у дальних рядов оказалась бы за границей).
      this.growRoomToLevel();
      this.syncStaff();
    }

    if (patch.demand != null) {
      // addDemand умеет зажимать в допустимый диапазон — считаем дельту от текущего.
      this.economy.addDemand(patch.demand - this.economy.demandPoints);
    }

    if (patch.trash) {
      for (let i = 0; i < patch.trash; i++) {
        const item = this.trash.spawnOne(this.restaurant);
        if (!item) break;
        this.emit({ type: 'trash-added', item });
      }
    }

    if (patch.refillStaff) {
      this.roster.refillEnergy();
      this.refreshRestaurantClosedState();
    }
  }

  // ── Магазин ───────────────────────────────────────────────────────

  /**
   * Купить предмет и сразу поставить его в зал (порт placeCurrentItem
   * WorldRestaurantEditor.as:468 + проверок ShopTransactionHandler).
   * Возвращает поставленный предмет либо причину отказа.
   */
  buyItem(
    contentId: number,
    tileX: number,
    tileY: number,
    rotation: Rotation = 0,
  ): { ok: true; item: PlacedItem } | { ok: false; reason: PurchaseBlock } {
    const entry = shopCatalog().find((e) => e.def.id === contentId);
    if (!entry) return { ok: false, reason: 'locked' };

    const block = purchaseBlock(entry, this.economy.level, this.economy.coins);
    if (block) return { ok: false, reason: block };

    const item = this.restaurant.place(entry.def, tileX, tileY, rotation);
    if (!item) return { ok: false, reason: 'no-space' };

    const price = entry.price ?? 0;
    this.economy.spendCoins(price);
    this.onLayoutChanged();
    this.emit({ type: 'item-bought', item, price });
    return { ok: true, item };
  }

  /**
   * Продать предмет из зала: возврат по getItemSellPrice + 2 gourmet points
   * (порт onItemSellOK :999). Дверь продать нельзя, если она последняя — иначе
   * гости перестанут приходить совсем.
   */
  sellItem(itemId: string): { ok: true; refund: number } | { ok: false; reason: string } {
    const item = this.restaurant.getItem(itemId);
    if (!item) return { ok: false, reason: 'not-found' };
    if (classifyItem(item.definition) === 'door' && this.restaurant.getDoors().length <= 1) {
      return { ok: false, reason: 'last-door' };
    }

    const refund = itemSellPrice(item.definition);
    const points = Balance.GOURMET_POINTS_SELL_ITEM;
    this.restaurant.remove(itemId);
    this.facilities.forget(itemId);
    this.economy.coins += refund;
    this.economy.gourmetPoints += points;
    this.onLayoutChanged();
    this.emit({ type: 'item-sold', contentId: item.contentId, refund, points });
    return { ok: true, refund };
  }

  // ── Двери ─────────────────────────────────────────────────────────

  /** Открыть дверь на DOOR_OPEN_HOLD_MS (порт WorldRestaurantPlay.openDoor). */
  openDoor(doorId: string): void {
    this.doorTimers.set(doorId, Balance.DOOR_OPEN_HOLD_MS);
  }

  /** Открыта ли дверь прямо сейчас. */
  isDoorOpen(doorId: string): boolean {
    return (this.doorTimers.get(doorId) ?? 0) > 0;
  }

  private maybeOpenDoorFor(c: Customer): void {
    if (!c.door) return;
    const pos = c.getInterpolatedPosition();
    const dist = Math.abs(c.door.tileX - pos.x) + Math.abs(c.door.tileY - pos.y);
    if (dist <= 1.2) this.openDoor(c.door.id);
  }

  private tickDoors(dtMs: number): void {
    for (const [id, left] of this.doorTimers) {
      const next = left - dtMs;
      if (next <= 0) this.doorTimers.delete(id);
      else this.doorTimers.set(id, next);
    }
  }

  // ── Управление ────────────────────────────────────────────────────

  /** Выгнать всех гостей и сбросить актёров (вход в дизайн-режим). */
  clearHall(): void {
    this.prevState.clear();
    this.customers.length = 0;
    this.orders.clear();
    for (const chef of this.chefs) chef.reset();
    for (const waiter of this.waiters) waiter.reset();
    // Мусор остаётся лежать — дизайн-режим его не убирает.
    for (const cleaner of this.cleaners) cleaner.reset(this);
    this.doorTimers.clear();
    this.spawnTimer = this.nextSpawnDelay();
  }

  setRunning(on: boolean): void {
    if (this.running === on) return;
    this.running = on;
    if (!on) this.clearHall();
  }

  // ── Реализация CustomerWorld / WaiterWorld ────────────────────────

  isActive(customer: Customer): boolean {
    return this.customers.includes(customer);
  }

  findPath(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    stopNextToDestination: boolean,
  ): TileCoord[] | null {
    return findPath({
      width: this.restaurant.width,
      height: this.restaurant.height,
      start: { x: fromX, y: fromY },
      destination: { x: toX, y: toY },
      walkability: this.restaurant,
      stopNextToDestination,
    });
  }

  findPathTo(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    stopNextToDestination: boolean,
  ): TileCoord[] | null {
    return this.findPath(fromX, fromY, toX, toY, stopNextToDestination);
  }

  /**
   * Свободные стулья. Стул подходит, только если к нему приставлен стол (на
   * одинокий стул гость не садится), он не занят и не зарезервирован другим
   * гостем. requireCleanTable отсекает столы с грязной посудой.
   */
  getEmptyChairs(requireCleanTable: boolean): RoomItem[] {
    const claimed = new Set<string>();
    for (const c of this.customers) {
      if (c.chair) claimed.add(c.chair.id);
    }
    return this.restaurant.getChairs().filter((chair) => {
      if (claimed.has(chair.id)) return false;
      const table = this.restaurant.getTableForChair(chair);
      if (!table) return false;
      if (requireCleanTable && this.orders.isTableDirty(table)) return false;
      return true;
    });
  }

  getTableForChair(chair: RoomItem): RoomItem | null {
    const placed = this.restaurant.getItem(chair.id);
    return placed ? this.restaurant.getTableForChair(placed) : null;
  }

  isTableFree(table: RoomItem): boolean {
    return !this.orders.isTableDirty(table);
  }

  /** Автоматы: не сломаны и никем не заняты. */
  getEmptyInteractiveItems(): RoomItem[] {
    const busy = new Set(
      this.customers.map((c) => c.interactiveItem?.id).filter((id): id is string => !!id),
    );
    return this.restaurant
      .getInteractiveItems()
      .filter((item) => !busy.has(item.id) && !this.facilities.isBroken(item));
  }

  /** Туалеты: не сломаны и не заняты (гость садится на них как на стул). */
  getEmptyToiletSeats(): RoomItem[] {
    const busy = new Set(this.customers.map((c) => c.chair?.id).filter((id): id is string => !!id));
    return this.restaurant
      .getToilets()
      .filter((item) => !busy.has(item.id) && !this.facilities.isBroken(item));
  }

  /** Раковины: не ломаются, только занятость. */
  getEmptySinks(): RoomItem[] {
    const busy = new Set(
      this.customers.map((c) => c.sinkItem?.id).filter((id): id is string => !!id),
    );
    return this.restaurant.getSinks().filter((item) => !busy.has(item.id));
  }

  /** Уровень игрока — им гейтятся туалеты и напитки. */
  get playerLevel(): number {
    return this.economy.level;
  }

  addOrderFromCustomer(customer: { order: DishOrder | null }): void {
    this.orders.addOrder(customer as Customer);
  }

  removeCustomer(customer: unknown): void {
    const c = customer as Customer;
    const i = this.customers.indexOf(c);
    if (i >= 0) this.customers.splice(i, 1);
    this.orders.forget(c);
    this.prevState.delete(c);
  }

  /** Спрос ±1 за довольного/недовольного гостя (порт addDemand). */
  addDemand(delta: number): void {
    this.economy.addDemand(delta);
  }

  rand(min: number, max: number): number {
    return this.randFn(min, max);
  }

  /** Сколько мусора в зале — гости у входа смотрят именно на это число. */
  get trashCount(): number {
    return this.trash.count;
  }

  /** Случайная проходимая клетка — куда побродить уборщику (CleanerWorld). */
  randomWalkableTile(): TileCoord | null {
    const tiles: TileCoord[] = [];
    for (let y = 0; y < this.restaurant.height; y++) {
      for (let x = 0; x < this.restaurant.width; x++) {
        if (this.restaurant.isWalkable(x, y)) tiles.push({ x, y });
      }
    }
    if (tiles.length === 0) return null;
    return tiles[this.randFn(0, tiles.length - 1)] ?? null;
  }

  // ── Для UI ────────────────────────────────────────────────────────

  /** Валидные входы (для рендера проёмов в стене). */
  getEntrances(): DoorEntrance[] {
    return this.restaurant.getDoorEntrances();
  }

  /** Сколько стульев занято / всего. */
  occupancy(): { busy: number; total: number } {
    const total = this.restaurant.getChairs().length;
    const busy = this.customers.filter((c) => c.chair !== null).length;
    return { busy, total };
  }
}

/**
 * Собрать штат из сейва. Сейвы до системы найма хранили только запас сил по id
 * актёра (`chef-0` / `waiter-0` / `cleaner-0`) — переносим их на стартовую пару
 * повар+официант, чтобы старая игра не начиналась заново.
 */
function createRoster(saved?: Partial<StaffState> | null): Roster {
  if (saved?.roster?.employees && saved.roster.employees.length > 0) {
    return new Roster(saved.roster);
  }
  const roster = Roster.withStarters();
  const legacy = saved?.workTime;
  if (legacy) {
    const carry = (job: JobId, key: string): void => {
      const employee = roster.byJob(job)[0];
      const workTime = legacy[key];
      if (employee && typeof workTime === 'number') {
        employee.workTime = Math.max(0, Math.min(Balance.MAX_WORK_TIME_MS, workTime));
      }
    };
    carry(Job.Cook, 'chef-0');
    carry(Job.Waiter, 'waiter-0');
  }
  return roster;
}
