/**
 * WorldRestaurant — порт com/playfish/games/cooking/WorldRestaurant.as (логическая часть).
 *
 * Что включено:
 *   - тайл-сетка фиксированного размера (по умолчанию 8×8, как в оригинальном DEFAULT)
 *   - размещённые предметы с поддержкой sizeX × sizeY и ротации
 *   - spatial-индекс по тайлам для быстрых запросов
 *   - isWalkable / isWalkableFrom (с проверкой угла при диагонали — как в оригинале)
 *   - getEmptyChairs / getTableForChair (через getFacingTile, как в оригинале)
 *   - place / move / remove с валидацией isValidPlacement
 *   - serialize / fromLayout для сохранения в JSON
 *
 * Что НЕ включено (откладывается):
 *   - outside area (огород/двор)
 *   - сцеплённые предметы (subItems)
 *   - окна/двери, привязанные к стенам (attachedWalls)
 *   - спецлогика «auto-rotate» соседей у обоев
 */

import type { WalkabilityChecker } from '../pathfinder';
import { classifyItem, isBlocking, isOverlay, isWallCategory } from './classify';
import { isInteractive, isSink, isToilet } from './facilities';
import { nextRotation, normalizeRotation } from './rotations';
import type {
  ItemCategory,
  ItemDefinition,
  PlacedItem,
  RestaurantLayout,
  Rotation,
  TileCoord,
} from './types';

/** Валидный вход: дверь + клетки двери, внутренняя и наружная. */
export type DoorEntrance = {
  door: PlacedItem;
  doorTile: TileCoord;
  insideTile: TileCoord;
  outsideTile: TileCoord;
};

export class WorldRestaurant implements WalkabilityChecker {
  private _width: number;
  private _height: number;

  private readonly items = new Map<string, PlacedItem>();
  /** Spatial index: "x,y" → все предметы, чьи bounding-box'ы покрывают этот тайл. */
  private readonly byTile = new Map<string, PlacedItem[]>();

  constructor(width: number, height: number) {
    if (width <= 0 || height <= 0) {
      throw new Error('WorldRestaurant: dimensions must be positive');
    }
    this._width = width;
    this._height = height;
  }

  get width(): number {
    return this._width;
  }

  get height(): number {
    return this._height;
  }

  /**
   * Раздвинуть зал — порт `setRoomSize` (:1808).
   *
   * Клетка (0,0) остаётся дальним углом, новые ряды прирастают в сторону
   * игрока: задние стены становятся длиннее, а всё уже расставленное остаётся
   * на своих координатах и никуда не едет.
   *
   * ОТСТУПЛЕНИЕ: уменьшать нельзя. В оригинале `setRoomSize` работал в обе
   * стороны (при загрузке размер брался из уровня как есть), и мебель за новой
   * границей просто повисала недосягаемой. Нам такое ронять некуда — отладочная
   * панель умеет ставить уровень вниз, — поэтому сжатие молча игнорируем.
   *
   * @returns true, если размер действительно изменился.
   */
  resize(width: number, height: number): boolean {
    const w = Math.max(this._width, Math.floor(width));
    const h = Math.max(this._height, Math.floor(height));
    if (w === this._width && h === this._height) return false;
    this._width = w;
    this._height = h;
    return true;
  }

  // ──────────────────────────────────────────────────────────────────
  // Запросы
  // ──────────────────────────────────────────────────────────────────

  isInBounds(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.width && y < this.height;
  }

  getItemsAt(x: number, y: number): PlacedItem[] {
    return this.byTile.get(tileKey(x, y)) ?? [];
  }

  /** Все размещённые предметы. */
  getAllItems(): PlacedItem[] {
    return Array.from(this.items.values());
  }

  getItem(id: string): PlacedItem | null {
    return this.items.get(id) ?? null;
  }

  /**
   * Можно ли ходить по тайлу. Стена блокирует, кроме случая когда на тайле
   * есть дверь (door перекрывает wall). Floor/wallpaper/wall-decor не считаются
   * блокирующими — они декоративные слои.
   */
  isWalkable(x: number, y: number): boolean {
    if (!this.isInBounds(x, y)) return false;
    const items = this.getItemsAt(x, y);
    let blocking = false;
    let hasDoor = false;
    for (const it of items) {
      const cat = classifyItem(it.definition);
      if (cat === 'door') hasDoor = true;
      else if (isBlocking(cat)) blocking = true;
    }
    if (hasDoor) return true;
    return !blocking;
  }

  /**
   * WalkabilityChecker.isWalkableFrom — то же, что в PathFinder.as:
   *   - если isDestination, точка цели проходима по определению (стул, ит.п.)
   *   - при диагональном шаге оба ортогональных соседних тайла должны быть проходимы
   *     (это убирает «срезы» через угол двух мебельных предметов)
   *   - allowOccupiedByActor пока игнорируется (в оригинале это значение
   *     было для случая, когда в тайле уже стоит другой actor — мы не моделируем
   *     столкновения actor'ов в этом срезе).
   */
  isWalkableFrom(
    fromX: number,
    fromY: number,
    toX: number,
    toY: number,
    isDestination: boolean,
    _allowOccupiedByActor: boolean,
  ): boolean {
    const targetOk = isDestination || this.isWalkable(toX, toY);
    if (!targetOk) return false;

    const dx = toX - fromX;
    const dy = toY - fromY;
    if (dx !== 0 && dy !== 0) {
      // Угловая проверка — НЕ применяется к destination, иначе можно зажать стул
      // между мебелью и не дать customer'у дойти. Совместимо с оригиналом.
      if (!this.isWalkable(toX, fromY)) return false;
      if (!this.isWalkable(fromX, toY)) return false;
    }
    return true;
  }

  /** Получить тайл, в который «смотрит» предмет с заданной ротацией. */
  static getFacingTile(tileX: number, tileY: number, rotation: Rotation): TileCoord {
    switch (rotation) {
      case 0:
        return { x: tileX + 1, y: tileY };
      case 90:
        return { x: tileX, y: tileY + 1 };
      case 180:
        return { x: tileX - 1, y: tileY };
      case 270:
        return { x: tileX, y: tileY - 1 };
    }
  }

  /** Все стулья. (Оккупация трекается снаружи — например, по Customer.chair). */
  getChairs(): PlacedItem[] {
    return this.getAllItems().filter((i) => i.definition.group === 'Chair');
  }

  /** Все столы. */
  getTables(): PlacedItem[] {
    return this.getAllItems().filter((i) => i.definition.group === 'Table');
  }

  /** Все кухонные приборы (плиты) — рабочие места повара. */
  getKitchens(): PlacedItem[] {
    return this.getAllItems().filter((i) => classifyItem(i.definition) === 'kitchen');
  }

  /**
   * Туалеты, раковины и игровые автоматы — по флагам `type` из restaurant.xml
   * (`toilet`, `sink`, `interactive`), как и в оригинале.
   */
  getToilets(): PlacedItem[] {
    return this.getAllItems().filter((i) => isToilet(i.definition));
  }

  getSinks(): PlacedItem[] {
    return this.getAllItems().filter((i) => isSink(i.definition));
  }

  getInteractiveItems(): PlacedItem[] {
    return this.getAllItems().filter((i) => isInteractive(i.definition));
  }

  /** Все двери — для определения точки входа customer'ов. */
  getDoors(): PlacedItem[] {
    return this.getAllItems().filter((i) => classifyItem(i.definition) === 'door');
  }

  /**
   * Геометрия входа от первой ВАЛИДНОЙ двери, или null если двери нет/непригодны.
   *
   *   doorTile    — клетка двери на стене (через неё гость проходит);
   *   insideTile  — клетка, в которую дверь «смотрит» (getFacingTile) — должна
   *                 быть в пределах сетки и проходима, иначе дверь невалидна;
   *   outsideTile — зеркальная клетка снаружи (off-grid), точка спавна/ухода.
   *
   * Порт логики WorldRestaurantPlay.getValidDoors() (дверь валидна, если клетка
   * перед ней проходима). Нет валидной двери → гости не приходят.
   */
  getDoorEntrance(): DoorEntrance | null {
    return this.getDoorEntrances()[0] ?? null;
  }

  /**
   * Все валидные входы — по одному на дверь, чья внутренняя клетка лежит в зале
   * и проходима. Порт WorldRestaurantPlay.getValidDoors (:2824): гость входит
   * через случайную из них, поэтому список, а не первая попавшаяся.
   */
  getDoorEntrances(): DoorEntrance[] {
    const result: DoorEntrance[] = [];
    for (const door of this.getDoors()) {
      const inside = WorldRestaurant.getFacingTile(door.tileX, door.tileY, door.rotation);
      if (!this.isInBounds(inside.x, inside.y)) continue;
      if (!this.isWalkable(inside.x, inside.y)) continue;
      result.push({
        door,
        doorTile: { x: door.tileX, y: door.tileY },
        insideTile: inside,
        // Клетка снаружи — зеркало внутренней относительно двери.
        outsideTile: { x: 2 * door.tileX - inside.x, y: 2 * door.tileY - inside.y },
      });
    }
    return result;
  }

  /**
   * Стол, к которому прикручен стул (расположен в тайле, куда стул «смотрит»).
   * В оригинале — getFacingTile + проверка tableItem.
   */
  getTableForChair(chair: PlacedItem): PlacedItem | null {
    if (chair.definition.group !== 'Chair') return null;
    const facing = WorldRestaurant.getFacingTile(chair.tileX, chair.tileY, chair.rotation);
    const itemsThere = this.getItemsAt(facing.x, facing.y);
    return itemsThere.find((i) => i.definition.group === 'Table') ?? null;
  }

  /**
   * Лежит ли тайл на стене, соответствующей повороту настенного предмета:
   *   rotation 0   → задняя-левая стена  (tx = 0)
   *   rotation 90  → задняя-правая стена  (ty = 0)
   *   rotation 180 → передняя-правая стена (tx = width-1)
   *   rotation 270 → передняя-левая стена  (ty = height-1)
   */
  isOnWallForRotation(tileX: number, tileY: number, rotation: Rotation): boolean {
    switch (rotation) {
      case 0:
        return tileX === 0;
      case 90:
        return tileY === 0;
      case 180:
        return tileX === this.width - 1;
      case 270:
        return tileY === this.height - 1;
    }
  }

  // ──────────────────────────────────────────────────────────────────
  // Валидация и мутации
  // ──────────────────────────────────────────────────────────────────

  /**
   * Можно ли поставить предмет в (tileX, tileY) с заданной ротацией.
   *   - все тайлы occupy-box'а должны быть в пределах сетки
   *   - правила сожительства зависят от категории:
   *       floor + wallpaper: уникальны per-tile (новый заменяет старый — это делает place())
   *       wall-decor: требует наличия стены под собой
   *       wall/door: не должно быть других wall/door на тех же тайлах
   *       furniture/kitchen/decor/functional: не должно быть других блокирующих предметов
   */
  isValidPlacement(
    def: ItemDefinition,
    tileX: number,
    tileY: number,
    rotation: Rotation,
    excludeId?: string,
  ): boolean {
    const { sizeX, sizeY } = rotatedSize(def, rotation);
    const cat = classifyItem(def);

    // Настенные предметы (окна, картины, двери, обои) — только на стене,
    // соответствующей повороту. Иначе их нельзя поставить «в воздухе» посреди зала.
    if (isWallCategory(cat) && !this.isOnWallForRotation(tileX, tileY, rotation)) {
      return false;
    }

    // Дверь — только на левой стене. В оригинале она могла стоять на любой, но
    // там же наружная площадка пристраивалась именно слева-снизу
    // (WorldRestaurant.as:709: outsideAreaFloor.x = getScreenX(0, numTilesY)),
    // и расширение зала ориентировано на ту же сторону. Держим вход там же,
    // чтобы пристройка не осталась без входа.
    if (cat === 'door' && !(tileX === 0 && rotation === 0)) return false;

    // Плитка пола не ложится на клетки стен — порт WorldRestaurant.isValid
    // (:1680): `if (param2 == 0 || param3 == 0) return false`.
    if (cat === 'floor' && (tileX === 0 || tileY === 0)) return false;

    for (let dx = 0; dx < sizeX; dx++) {
      for (let dy = 0; dy < sizeY; dy++) {
        const x = tileX + dx;
        const y = tileY + dy;
        if (!this.isInBounds(x, y)) return false;

        const here = this.getItemsAt(x, y).filter((i) => i.id !== excludeId);

        if (cat === 'floor' || cat === 'wallpaper') {
          if (here.some((i) => classifyItem(i.definition) === cat)) return false;
        } else if (cat === 'wall-decor') {
          // Один предмет на сегмент стены — порт WorldRestaurant.isValid (:1712):
          // `if (wallDecorationItem && itemMap[idx].length > 1) return false`,
          // где единственный допустимый жилец клетки — сама стена. Обои в счёт
          // не идут: они часть стены и рисуются за предметом, а не поверх него.
          if (
            here.some((i) => {
              const c = classifyItem(i.definition);
              return c === 'wall-decor' || c === 'door';
            })
          ) {
            return false;
          }
        } else if (cat === 'wall' || cat === 'door') {
          if (
            here.some((i) => {
              const c = classifyItem(i.definition);
              return c === 'wall' || c === 'door';
            })
          ) {
            return false;
          }
        } else {
          // Блокирующие: стена/мебель/кухня/декор — не должны пересекаться с другими блокирующими.
          if (here.some((i) => isBlocking(classifyItem(i.definition)))) return false;
        }
      }
    }
    return true;
  }

  place(
    def: ItemDefinition,
    tileX: number,
    tileY: number,
    rotationRaw: Rotation,
    id?: string,
  ): PlacedItem | null {
    // У предмета может быть меньше четырёх ракурсов (порт getMaxRotationCount):
    // сворачиваем поворот к тому, который реально существует, иначе логика
    // (например, клетка повара у плиты) разойдётся с картинкой.
    const rotation = normalizeRotation(def, rotationRaw);
    if (!this.isValidPlacement(def, tileX, tileY, rotation, id)) return null;
    const itemId = id ?? randomId();
    const item: PlacedItem = {
      id: itemId,
      contentId: def.id,
      definition: def,
      tileX,
      tileY,
      rotation,
    };
    this.items.set(itemId, item);
    this.indexItem(item);
    return item;
  }

  move(id: string, toX: number, toY: number, rotation?: Rotation): boolean {
    const item = this.items.get(id);
    if (!item) return false;
    const newRotation = normalizeRotation(item.definition, rotation ?? item.rotation);
    if (!this.isValidPlacement(item.definition, toX, toY, newRotation, id)) return false;
    this.unindexItem(item);
    item.tileX = toX;
    item.tileY = toY;
    item.rotation = newRotation;
    this.indexItem(item);
    return true;
  }

  /**
   * Повернуть предмет на следующий доступный ракурс. У однокадровых предметов
   * (плита) поворотов нет вовсе — возвращаем false, чтобы UI не делал вид,
   * будто что-то произошло.
   */
  rotate(id: string): boolean {
    const item = this.items.get(id);
    if (!item) return false;
    const newRotation = nextRotation(item.definition, item.rotation);
    if (newRotation === item.rotation) return false;
    return this.move(id, item.tileX, item.tileY, newRotation);
  }

  remove(id: string): boolean {
    const item = this.items.get(id);
    if (!item) return false;
    this.unindexItem(item);
    this.items.delete(id);
    return true;
  }

  // ──────────────────────────────────────────────────────────────────
  // Сериализация
  // ──────────────────────────────────────────────────────────────────

  serialize(): RestaurantLayout {
    return {
      width: this.width,
      height: this.height,
      items: this.getAllItems().map((i) => ({
        id: i.id,
        contentId: i.contentId,
        tileX: i.tileX,
        tileY: i.tileY,
        rotation: i.rotation,
      })),
    };
  }

  static fromLayout(
    layout: RestaurantLayout,
    lookup: (contentId: number) => ItemDefinition | null,
  ): WorldRestaurant {
    const world = new WorldRestaurant(layout.width, layout.height);
    for (const entry of layout.items) {
      const def = lookup(entry.contentId);
      if (!def) {
        console.warn(`WorldRestaurant.fromLayout: unknown contentId ${entry.contentId}, skipping`);
        continue;
      }
      const placed = world.place(def, entry.tileX, entry.tileY, entry.rotation, entry.id);
      if (!placed) {
        console.warn(
          `WorldRestaurant.fromLayout: invalid placement for ${def.name} at (${entry.tileX},${entry.tileY})`,
        );
      }
    }
    return world;
  }

  // ──────────────────────────────────────────────────────────────────
  // Private
  // ──────────────────────────────────────────────────────────────────

  private indexItem(item: PlacedItem): void {
    const { sizeX, sizeY } = rotatedSize(item.definition, item.rotation);
    for (let dx = 0; dx < sizeX; dx++) {
      for (let dy = 0; dy < sizeY; dy++) {
        const k = tileKey(item.tileX + dx, item.tileY + dy);
        const arr = this.byTile.get(k);
        if (arr) arr.push(item);
        else this.byTile.set(k, [item]);
      }
    }
  }

  private unindexItem(item: PlacedItem): void {
    const { sizeX, sizeY } = rotatedSize(item.definition, item.rotation);
    for (let dx = 0; dx < sizeX; dx++) {
      for (let dy = 0; dy < sizeY; dy++) {
        const k = tileKey(item.tileX + dx, item.tileY + dy);
        const arr = this.byTile.get(k);
        if (!arr) continue;
        const idx = arr.indexOf(item);
        if (idx >= 0) arr.splice(idx, 1);
        if (arr.length === 0) this.byTile.delete(k);
      }
    }
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Утилиты
// ──────────────────────────────────────────────────────────────────────────

function tileKey(x: number, y: number): string {
  return `${x},${y}`;
}

/** При повороте на 90/270° размеры меняются местами. */
export function rotatedSize(
  def: ItemDefinition,
  rotation: Rotation,
): { sizeX: number; sizeY: number } {
  if (rotation === 90 || rotation === 270) {
    return { sizeX: def.sizeY, sizeY: def.sizeX };
  }
  return { sizeX: def.sizeX, sizeY: def.sizeY };
}

function randomId(): string {
  return `it-${Math.random().toString(36).slice(2, 10)}`;
}

export type { ItemCategory };
