/**
 * Батч-рендерер 3D-аватаров в ОДНОМ WebGL-контексте.
 *
 * Идея — как у оригинала (IsoCacher кешировал аватаров в битмапы): вместо N
 * отдельных WebGL-контекстов держим один renderer и один canvas-«стрип» из
 * горизонтальных ячеек CELL_W×CELL_H. Каждый активный актёр занимает слот;
 * раз в кадр для каждого занятого слота выставляем viewport/scissor на его
 * ячейку, показываем только его модель и рендерим. PixiJS берёт весь canvas
 * как источник, а каждый актёр — под-прямоугольник (frame) этого источника.
 *
 * Это масштабируется на гостей + официанта + повара без накопления контекстов
 * (главный источник нестабильности при множестве three.js-сцен).
 */

import * as THREE from 'three';
import { AVATAR_ANIMATIONS, AVATAR_FPS } from './animations';
import type { AvatarConfig } from './avatar-config';
import {
  type AvatarInstance,
  type AvatarModelSource,
  type AvatarPalette,
  type AvatarProp,
  DEFAULT_PALETTE,
  applyAvatarConfig,
  cloneAvatar,
  loadAvatarModel,
  resetAvatarOutfit,
  setAvatarProp,
} from './avatar-model';

export const CELL_W = 128;
export const CELL_H = 220;

type Slot = {
  index: number;
  inUse: boolean;
  /** Обёртка поворота по направлению движения. */
  facingGroup: THREE.Group;
  instance: AvatarInstance;
  fullClip: THREE.AnimationClip | null;
  action: THREE.AnimationAction | null;
  currentAnim: string;
  /** Предмет в руках — храним, чтобы не перебирать меши каждый кадр. */
  currentProp: AvatarProp | null;
  /** Применённая внешность — чтобы не перекрашивать модель каждый кадр. */
  currentLook: AvatarConfig | null;
};

export class AvatarBatch {
  readonly canvas: HTMLCanvasElement;
  ready = false;

  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene: THREE.Scene;
  private readonly camera: THREE.PerspectiveCamera;
  private readonly slots: Slot[] = [];
  private readonly capacity: number;
  private centerY = 0;
  private disposed = false;

  private readonly palette: AvatarPalette;

  constructor(capacity = 6, palette?: AvatarPalette) {
    this.palette = palette ?? DEFAULT_PALETTE;
    this.capacity = capacity;
    this.canvas = document.createElement('canvas');
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: true,
      premultipliedAlpha: false,
    });
    this.renderer.setSize(CELL_W * capacity, CELL_H, false);
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.autoClear = false; // очищаем вручную, рендерим ячейки по scissor

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(32, CELL_W / CELL_H, 1, 100000);
    this.scene.add(new THREE.AmbientLight(0xffffff, 1.0));
    const dir = new THREE.DirectionalLight(0xffffff, 1.0);
    dir.position.set(2, 8, 6);
    this.scene.add(dir);

    void this.load(palette);
  }

  private async load(palette?: AvatarPalette): Promise<void> {
    let src: AvatarModelSource;
    try {
      src = await loadAvatarModel();
    } catch (err) {
      console.error('AvatarBatch: model load failed', err);
      return;
    }
    if (this.disposed) return;

    for (let i = 0; i < this.capacity; i++) {
      const instance = cloneAvatar(src, palette);
      const facingGroup = new THREE.Group();
      facingGroup.add(instance.root);
      facingGroup.visible = false;
      this.scene.add(facingGroup);
      this.slots.push({
        index: i,
        inUse: false,
        facingGroup,
        instance,
        // Клип, ретаргетированный на UUID именно этого клона.
        fullClip: instance.clips[0] ?? null,
        action: null,
        currentAnim: '',
        currentProp: null,
        currentLook: null,
      });
    }

    // Камера кадрируется по одному клону (все одинаковы): центрируем по X/Z,
    // смотрим сверху-спереди под изо-углом (~20°).
    const sample = this.slots[0]!;
    sample.facingGroup.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(sample.instance.root);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    const h = size.y || 200;
    this.centerY = center.y;
    for (const s of this.slots) {
      // Сдвигаем модель так, чтобы её X/Z-центр был на оси вращения.
      s.instance.root.position.set(-center.x, 0, -center.z);
    }
    const dist = h * 1.5;
    const elev = THREE.MathUtils.degToRad(20);
    this.camera.position.set(0, center.y + Math.sin(elev) * dist, Math.cos(elev) * dist);
    this.camera.lookAt(0, center.y, 0);
    this.camera.updateProjectionMatrix();

    this.ready = true;
  }

  /**
   * Занять свободный слот. Возвращает индекс или null, если все заняты.
   * `look` красит именно этот клон — так сотрудники отличаются друг от друга.
   */
  acquire(look?: AvatarConfig | null): number | null {
    for (const s of this.slots) {
      if (!s.inUse) {
        s.inUse = true;
        s.facingGroup.visible = true;
        s.facingGroup.rotation.y = 0;
        s.currentAnim = '';
        this.applyLook(s, look ?? null);
        return s.index;
      }
    }
    return null;
  }

  /** Перекрасить слот под конкретную внешность (или вернуть наряд по умолчанию). */
  setLook(index: number, look: AvatarConfig | null): void {
    const s = this.slots[index];
    if (s) this.applyLook(s, look);
  }

  private applyLook(slot: Slot, look: AvatarConfig | null): void {
    if (slot.currentLook === look) return;
    const had = slot.currentLook !== null;
    slot.currentLook = look;
    if (look) {
      applyAvatarConfig(slot.instance.root, look);
    } else if (had) {
      // Слот освободился после сотрудника с индивидуальной внешностью. Без
      // сброса следующий занявший его гость унаследует чужой наряд — вплоть до
      // платья, которого у модели гостя быть не должно.
      resetAvatarOutfit(slot.instance.root, this.palette);
    } else {
      return;
    }
    // Смена наряда прячет и реквизит — пусть ActorView выставит его заново.
    slot.currentProp = null;
  }

  /** Освободить слот. */
  release(index: number): void {
    const s = this.slots[index];
    if (!s) return;
    s.inUse = false;
    s.facingGroup.visible = false;
    // Наряд сотрудника не должен достаться следующему жильцу слота.
    this.applyLook(s, null);
    if (s.action) {
      s.action.stop();
      s.action = null;
    }
    s.currentAnim = '';
    // Слот уходит в пул — руки должны быть пустыми у следующего актёра.
    if (s.currentProp !== null) {
      s.currentProp = null;
      setAvatarProp(s.instance.root, null);
    }
  }

  /** Переключить анимацию слота (idle/walk/sit/eat/cooking…). */
  setAnim(index: number, key: string): void {
    const s = this.slots[index];
    if (!s || !s.fullClip) return;
    if (s.currentAnim === key) return;
    const def = AVATAR_ANIMATIONS[key];
    if (!def) return;
    const clip = THREE.AnimationUtils.subclip(
      s.fullClip,
      def.name,
      def.start,
      def.end + 1,
      AVATAR_FPS,
    );
    const next = s.instance.mixer.clipAction(clip);
    next.reset();
    next.setLoop(THREE.LoopRepeat, Number.POSITIVE_INFINITY);
    next.timeScale = 1 / def.delay;
    next.fadeIn(0.15);
    next.play();
    if (s.action && s.action !== next) s.action.fadeOut(0.15);
    s.action = next;
    s.currentAnim = key;
  }

  /**
   * Показать предмет в руках слота: поднос у официанта, щётку с ведром у
   * уборщика. null — пустые руки. Меши есть прямо в модели оригинала и висят на
   * костях кисти, поэтому едут вместе с анимацией.
   */
  setProp(index: number, prop: AvatarProp | null): void {
    const s = this.slots[index];
    if (!s || s.currentProp === prop) return;
    s.currentProp = prop;
    setAvatarProp(s.instance.root, prop);
  }

  /** Поворот аватара вокруг вертикали (рад), 0 = лицом к камере. */
  setFacing(index: number, angleRad: number): void {
    const s = this.slots[index];
    if (s) s.facingGroup.rotation.y = angleRad;
  }

  /** Прямоугольник ячейки слота в пикселях canvas (для PixiJS frame). */
  cellRect(index: number): { x: number; y: number; w: number; h: number } {
    return { x: index * CELL_W, y: 0, w: CELL_W, h: CELL_H };
  }

  /** Тик: продвинуть микшеры и отрендерить каждую занятую ячейку. */
  update(dtSec: number): void {
    if (this.disposed || !this.ready) return;

    // Продвигаем анимацию + синхронизируем скорость из текущего delay (live-tune).
    for (const s of this.slots) {
      if (!s.inUse) continue;
      if (s.action) {
        const def = AVATAR_ANIMATIONS[s.currentAnim];
        if (def) s.action.timeScale = 1 / def.delay;
      }
      s.instance.mixer.update(dtSec);
    }

    const r = this.renderer;
    r.setScissorTest(false);
    r.clear(); // прозрачная очистка всего стрипа (color + depth)
    r.setScissorTest(true);
    for (const target of this.slots) {
      if (!target.inUse) continue;
      // Показываем только текущий слот (все аватары стоят в начале координат).
      for (const s of this.slots) s.facingGroup.visible = s === target;
      const x = target.index * CELL_W;
      r.setViewport(x, 0, CELL_W, CELL_H);
      r.setScissor(x, 0, CELL_W, CELL_H);
      r.render(this.scene, this.camera);
    }
    // Возвращаем видимость занятым слотам (для консистентности состояния).
    for (const s of this.slots) s.facingGroup.visible = s.inUse;
  }

  dispose(): void {
    this.disposed = true;
    this.renderer.dispose();
  }
}
