/**
 * Камера зала: протяжка двигает сцену, щипок и колесо меняют масштаб.
 *
 * Зал 8×8 в изометрии — это 640×320 px при масштабе оригинала (TILE_W=80), и
 * он шире любого телефона. Раньше сцена стояла намертво: контейнер один раз
 * центрировался при старте, и всё, что не поместилось по краям, было просто
 * недостижимо. Камера двигает корневой контейнер со всеми слоями сразу, так
 * что изометрия, глубина и обратная проекция `screenToTile` продолжают
 * работать без единой правки — `stage.toLocal()` учитывает трансформацию.
 *
 * Жесты не конфликтуют с редактором: ItemLayer гасит pointerdown на предмете
 * (stopPropagation), поэтому в дизайн-режиме протяжка за мебель двигает
 * мебель, а протяжка за пол — камеру. Мы панорамируем только теми
 * указателями, чей pointerdown до нас дошёл.
 *
 * Тап по мусору и по сломанному предмету приходит из PixiJS как `pointertap`
 * уже ПОСЛЕ протяжки (палец опустился и поднялся на том же спрайте), поэтому
 * обработчики тапа спрашивают `tapSuppressed()` — иначе каждый сдвиг камеры,
 * начатый с мусора, его же и убирал бы.
 */

import type { Application, Container, FederatedPointerEvent } from 'pixi.js';

/** Дальше не отдаляем: мельче зал уже не читается. */
const MIN_SCALE = 0.4;
/** Ближе не приближаем: спрайты растровые, выше 1.6 идёт каша из пикселей. */
const MAX_SCALE = 1.6;
/** При автоподгонке не увеличиваем: спрайты нарисованы под масштаб 1:1. */
const FIT_MAX_SCALE = 1;
/** Сдвиг больше этого — жест считается протяжкой, а не тапом. */
const PAN_SLOP_PX = 8;
/** Воздух между залом и краем видимой области. */
const EDGE_MARGIN = 16;

/** Прямоугольник содержимого в координатах перемещаемого контейнера. */
export type CameraBounds = { minX: number; minY: number; maxX: number; maxY: number };

/** Сколько экрана сверху и снизу занято HUD — камера туда не целится. */
export type CameraInsets = { top: number; bottom: number };

export type CameraOptions = {
  app: Application;
  /** Контейнер со всеми слоями сцены — его и двигаем. */
  world: Container;
  /** Корень pointer-событий (обычно app.stage). */
  root: Container;
  /** Границы содержимого; функция, потому что зал может вырасти. */
  bounds: () => CameraBounds;
  insets?: () => CameraInsets;
};

export type Camera = {
  /** Вписать зал в видимую область целиком и забыть ручной масштаб. */
  fit(): void;
  /** Текущий жест оказался протяжкой — тап засчитывать не надо. */
  tapSuppressed(): boolean;
  destroy(): void;
};

type Point = { x: number; y: number };

const distance = (a: Point, b: Point): number => Math.hypot(a.x - b.x, a.y - b.y);
const midpoint = (a: Point, b: Point): Point => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });

export function attachCamera(opts: CameraOptions): Camera {
  const { app, world, root } = opts;
  const insets = opts.insets ?? ((): CameraInsets => ({ top: 0, bottom: 0 }));

  /** Активные указатели, чей pointerdown дошёл до нас (не съеден предметом). */
  const pointers = new Map<number, Point>();
  /** Пройденный путь в текущем жесте — по нему отличаем тап от протяжки. */
  let travelled = 0;
  let panned = false;
  /** Игрок сам менял масштаб — автоподгонка при resize больше не вмешивается. */
  let userZoomed = false;
  let pinchDistance = 0;
  let pinchCentre: Point | null = null;

  /** Видимая часть экрана: без полос HUD сверху и снизу. */
  function viewport(): { left: number; top: number; right: number; bottom: number } {
    const { top, bottom } = insets();
    const h = app.screen.height;
    // Страховка от абсурдных отступов на совсем низких экранах.
    const usable = Math.max(120, h - top - bottom);
    return { left: 0, top: Math.min(top, h - usable), right: app.screen.width, bottom: h - bottom };
  }

  const clampScale = (s: number): number => Math.min(MAX_SCALE, Math.max(MIN_SCALE, s));

  /**
   * Удержать содержимое у видимой области.
   *
   * По каждой оси два предела: «левый край зала не заходит внутрь экрана» и
   * «правый край не уходит за него». Пока зал шире видимой области, первый
   * предел меньше второго — получается привычный упор в край. Как только зал
   * целиком помещается, пределы меняются местами, и тот же интервал начинает
   * означать «зал ездит внутри экрана, но не вылезает». Отсюда min/max по
   * обоим значениям: одна формула на оба случая, и протяжка всегда отзывается,
   * а не залипает по центру.
   */
  function clampPosition(): void {
    const s = world.scale.x;
    const b = opts.bounds();
    const view = viewport();

    const axis = (min: number, max: number, lo: number, hi: number, pos: number): number => {
      const near = hi - max * s - EDGE_MARGIN;
      const far = lo - min * s + EDGE_MARGIN;
      return Math.min(Math.max(pos, Math.min(near, far)), Math.max(near, far));
    };

    world.position.set(
      axis(b.minX, b.maxX, view.left, view.right, world.x),
      axis(b.minY, b.maxY, view.top, view.bottom, world.y),
    );
  }

  /** Масштаб с сохранением точки под пальцем (или под курсором). */
  function zoomAt(next: number, anchor: Point): void {
    const from = world.scale.x;
    const to = clampScale(next);
    if (Math.abs(to - from) < 0.0001) return;
    const k = to / from;
    world.position.set(anchor.x - (anchor.x - world.x) * k, anchor.y - (anchor.y - world.y) * k);
    world.scale.set(to);
  }

  function fit(): void {
    // Подгонка — это и есть «камера как при старте»: ручной масштаб забываем,
    // иначе resize после неё продолжал бы уважать давно сброшенный зум.
    userZoomed = false;
    const b = opts.bounds();
    const view = viewport();
    const w = b.maxX - b.minX + EDGE_MARGIN * 2;
    const h = b.maxY - b.minY + EDGE_MARGIN * 2;
    const s = clampScale(
      Math.min((view.right - view.left) / w, (view.bottom - view.top) / h, FIT_MAX_SCALE),
    );
    world.scale.set(s);
    world.position.set(
      (view.left + view.right) / 2 - ((b.minX + b.maxX) / 2) * s,
      (view.top + view.bottom) / 2 - ((b.minY + b.maxY) / 2) * s,
    );
    clampPosition();
  }

  // ── Жесты ─────────────────────────────────────────────────────────

  const onPointerDown = (e: FederatedPointerEvent): void => {
    // Правая и средняя кнопки мыши камеру не двигают.
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    pointers.set(e.pointerId, { x: e.global.x, y: e.global.y });
    if (pointers.size === 1) {
      travelled = 0;
      // Новый жест — прошлая протяжка больше не мешает тапу.
      panned = false;
    }
    if (pointers.size === 2) {
      const [a, b] = [...pointers.values()] as [Point, Point];
      pinchDistance = distance(a, b);
      pinchCentre = midpoint(a, b);
    }
  };

  const onPointerMove = (e: FederatedPointerEvent): void => {
    const prev = pointers.get(e.pointerId);
    // Указатель не наш: жест начался на предмете и перехвачен редактором.
    if (!prev) return;
    const cur = { x: e.global.x, y: e.global.y };
    pointers.set(e.pointerId, cur);

    if (pointers.size === 1) {
      const dx = cur.x - prev.x;
      const dy = cur.y - prev.y;
      travelled += Math.hypot(dx, dy);
      // Пока палец в пределах порога — это ещё тап, камеру не дёргаем.
      if (!panned && travelled <= PAN_SLOP_PX) return;
      panned = true;
      world.position.set(world.x + dx, world.y + dy);
      clampPosition();
      return;
    }

    if (pointers.size !== 2) return;
    const [a, b] = [...pointers.values()] as [Point, Point];
    const d = distance(a, b);
    const c = midpoint(a, b);
    // Щипок: масштаб по изменению расстояния, перенос — по сдвигу середины.
    if (pinchDistance > 0 && d > 0) {
      zoomAt(world.scale.x * (d / pinchDistance), c);
      userZoomed = true;
    }
    if (pinchCentre)
      world.position.set(world.x + (c.x - pinchCentre.x), world.y + (c.y - pinchCentre.y));
    pinchDistance = d;
    pinchCentre = c;
    panned = true;
    clampPosition();
  };

  const onPointerUp = (e: FederatedPointerEvent): void => {
    pointers.delete(e.pointerId);
    if (pointers.size < 2) {
      pinchDistance = 0;
      pinchCentre = null;
    }
    // panned намеренно не сбрасываем: pointertap прилетит следующим и должен
    // увидеть, что жест был протяжкой. Сбросит его pointerdown нового жеста.
  };

  /**
   * Колесо мыши — масштаб к курсору. Свой DOM-слушатель, а не федеративный
   * `wheel` из PixiJS: тот подписан пассивно и не даёт отменить прокрутку
   * страницы под канвасом.
   */
  const canvas = app.canvas;
  const onWheel = (e: WheelEvent): void => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    // Экранные координаты PixiJS — логические пиксели, как и CSS-размер канваса.
    const anchor = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    zoomAt(world.scale.x * Math.exp(-e.deltaY * 0.0015), anchor);
    userZoomed = true;
    clampPosition();
  };

  const onResize = (): void => {
    // Если игрок сам выставил масштаб — уважаем его и только прижимаем края.
    if (userZoomed) clampPosition();
    else fit();
  };

  root.on('pointerdown', onPointerDown);
  root.on('pointermove', onPointerMove);
  root.on('pointerup', onPointerUp);
  root.on('pointerupoutside', onPointerUp);
  root.on('pointercancel', onPointerUp);
  canvas.addEventListener('wheel', onWheel, { passive: false });
  app.renderer.on('resize', onResize);

  fit();

  return {
    fit,
    tapSuppressed: () => panned,
    destroy(): void {
      root.off('pointerdown', onPointerDown);
      root.off('pointermove', onPointerMove);
      root.off('pointerup', onPointerUp);
      root.off('pointerupoutside', onPointerUp);
      root.off('pointercancel', onPointerUp);
      canvas.removeEventListener('wheel', onWheel);
      app.renderer.off('resize', onResize);
    },
  };
}
