/**
 * Экран кастомизации аватара (меши + плоские цвета).
 *
 * Кастомизация сменой МЕШЕЙ (причёска hair01-18, шляпа hat01-10, тело
 * штаны/платье) и плоскими цветами (кожа/волосы/рубашка/штаны). Текстуры
 * одежды отложены (реконструкция UV-атласа — отдельная сложная задача),
 * поэтому используем узнаваемый чибик-стиль как в зале.
 *
 * Конфигурация сохраняется в localStorage и читается через loadAvatarConfig().
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { ColladaLoader } from 'three/examples/jsm/loaders/ColladaLoader.js';
import { asset } from '../asset-url';
import { type AvatarConfig, loadAvatarConfig, saveAvatarConfig } from './avatar-config';
import { applyAvatarConfig } from './avatar-model';

// Доступные меши (присутствуют в COLLADA).
const HAIR_OPTIONS = [
  'none',
  'hair01',
  'hair02',
  'hair03',
  'hair04',
  'hair05',
  'hair06',
  'hair07',
  'hair08',
  'hair09',
  'hair10',
  'hair13',
  'hair14',
  'hair15',
  'hair17',
  'hair18',
];
const HAT_OPTIONS = [
  'none',
  'hat01',
  'hat02',
  'hat03',
  'hat04',
  'hat05',
  'hat06',
  'hat07',
  'hat08',
  'hat09',
  'hat10',
];

const SKIN_SWATCHES = [0xf2cf9b, 0xe6bd8a, 0xc98a5e, 0xa56a40, 0x7a4a2b];
const HAIR_SWATCHES = [0x1c130c, 0x5a3a22, 0x8a5a2b, 0xc9a24b, 0xe8d49b, 0xb0b0b0, 0x8a2b2b];
const CLOTH_SWATCHES = [
  0x3aa1d8, 0xd0463a, 0x37d27a, 0xf0c419, 0x9b59b6, 0xe67e22, 0x394a5f, 0xeeeeee, 0x2c3e50,
];
type Tab = 'hair' | 'hat' | 'body' | 'skin' | 'hairColor' | 'clothes';

export function AvatarCustomizer({ onClose }: { onClose?: () => void }): React.ReactElement {
  const mountRef = useRef<HTMLDivElement>(null);
  const rootRef = useRef<THREE.Object3D | null>(null);
  const [ready, setReady] = useState(false);
  const [tab, setTab] = useState<Tab>('hair');
  const [cfg, setCfg] = useState<AvatarConfig>(() => loadAvatarConfig());

  // Инициализация сцены и загрузка модели (однократно): стартовый cfg
  // читается один раз, дальше правки применяются через applyAvatarConfig.
  // biome-ignore lint/correctness/useExhaustiveDependencies: mount-only
  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    let disposed = false;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      40,
      mount.clientWidth / mount.clientHeight,
      0.01,
      10000,
    );
    scene.add(new THREE.AmbientLight(0xffffff, 0.95));
    const dir = new THREE.DirectionalLight(0xffffff, 1.1);
    dir.position.set(3, 10, 6);
    scene.add(dir);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.enablePan = false;

    let raf = 0;
    new ColladaLoader().load(asset('models/avatar.dae'), (collada) => {
      if (disposed) return;
      const root = collada.scene;
      rootRef.current = root;
      applyAvatarConfig(root, cfg);
      scene.add(root);
      frameVisible(root, camera, controls);
      setReady(true);
    });

    const onResize = (): void => {
      if (!mount) return;
      camera.aspect = mount.clientWidth / mount.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(mount.clientWidth, mount.clientHeight);
    };
    window.addEventListener('resize', onResize);

    const animate = (): void => {
      raf = requestAnimationFrame(animate);
      controls.update();
      renderer.render(scene, camera);
    };
    animate();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      controls.dispose();
      renderer.dispose();
      if (renderer.domElement.parentNode === mount) mount.removeChild(renderer.domElement);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Переприменяем конфиг к модели при каждом изменении.
  useEffect(() => {
    if (rootRef.current) applyAvatarConfig(rootRef.current, cfg);
  }, [cfg]);

  const set = (patch: Partial<AvatarConfig>): void => setCfg((c) => ({ ...c, ...patch }));

  const tabs: Array<{ id: Tab; label: string }> = useMemo(
    () => [
      { id: 'hair', label: 'Причёска' },
      { id: 'hat', label: 'Шляпа' },
      { id: 'body', label: 'Тело' },
      { id: 'skin', label: 'Кожа' },
      { id: 'hairColor', label: 'Цвет волос' },
      { id: 'clothes', label: 'Одежда' },
    ],
    [],
  );

  return (
    <div className="absolute inset-0 bg-[#10151c] flex flex-col">
      <div ref={mountRef} className="flex-1 min-h-0" />

      {/* Верхняя плашка */}
      <div className="absolute top-0 left-0 right-0 p-3 flex items-center justify-between text-xs font-mono">
        <div className="opacity-70 pointer-events-none">Restaurant Valley · кастомизация</div>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => {
              saveAvatarConfig(cfg);
              onClose?.();
            }}
            className="rounded-lg px-3 py-1.5 bg-emerald-500/20 border border-emerald-400/50 text-emerald-200 hover:bg-emerald-500/30"
          >
            Сохранить
          </button>
          {onClose && (
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg px-3 py-1.5 bg-black/40 border border-white/20 hover:bg-white/10"
            >
              ← В игру
            </button>
          )}
        </div>
      </div>

      {!ready && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="text-sm opacity-80 font-mono">Загрузка модели…</div>
        </div>
      )}

      {/* Нижняя панель кастомизации */}
      <div className="p-3 pad-bottom-safe-lg bg-black/40 backdrop-blur-md space-y-2">
        <div className="flex gap-1.5 overflow-x-auto pb-1">
          {tabs.map((t) => (
            <button
              key={t.id}
              type="button"
              onClick={() => setTab(t.id)}
              className={`shrink-0 rounded-lg px-3 py-1.5 text-xs font-semibold border transition ${
                tab === t.id
                  ? 'bg-[var(--accent,#2f9ac8)] text-white border-transparent'
                  : 'border-white/20 hover:bg-white/5'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>

        <div className="flex gap-2 overflow-x-auto pb-1 min-h-[3rem] items-center">
          {tab === 'hair' &&
            HAIR_OPTIONS.map((h) => (
              <OptionChip key={h} active={cfg.hair === h} onClick={() => set({ hair: h })}>
                {h === 'none' ? 'без волос' : h.replace('hair', '#')}
              </OptionChip>
            ))}
          {tab === 'hat' &&
            HAT_OPTIONS.map((h) => (
              <OptionChip key={h} active={cfg.hat === h} onClick={() => set({ hat: h })}>
                {h === 'none' ? 'без шляпы' : h.replace('hat', '#')}
              </OptionChip>
            ))}
          {tab === 'body' &&
            (['pants', 'dress'] as const).map((b) => (
              <OptionChip key={b} active={cfg.body === b} onClick={() => set({ body: b })}>
                {b === 'pants' ? 'штаны' : 'платье'}
              </OptionChip>
            ))}
          {tab === 'skin' &&
            SKIN_SWATCHES.map((c) => (
              <Swatch key={c} color={c} active={cfg.skin === c} onClick={() => set({ skin: c })} />
            ))}
          {tab === 'hairColor' &&
            HAIR_SWATCHES.map((c) => (
              <Swatch
                key={c}
                color={c}
                active={cfg.hairColor === c}
                onClick={() => set({ hairColor: c })}
              />
            ))}
          {tab === 'clothes' && (
            <>
              <span className="text-[10px] opacity-60 shrink-0 pr-1">верх</span>
              {CLOTH_SWATCHES.map((c) => (
                <Swatch
                  key={`s${c}`}
                  color={c}
                  active={cfg.shirtColor === c}
                  onClick={() => set({ shirtColor: c })}
                />
              ))}
              <span className="text-[10px] opacity-60 shrink-0 px-1">низ</span>
              {CLOTH_SWATCHES.map((c) => (
                <Swatch
                  key={`p${c}`}
                  color={c}
                  active={cfg.pantsColor === c}
                  onClick={() => set({ pantsColor: c })}
                />
              ))}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function OptionChip({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}): React.ReactElement {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`shrink-0 rounded-lg px-3 py-2 text-xs font-semibold border transition ${
        active ? 'bg-white/15 border-white/50' : 'border-white/15 hover:bg-white/5'
      }`}
    >
      {children}
    </button>
  );
}

function Swatch({
  color,
  active,
  onClick,
}: {
  color: number;
  active: boolean;
  onClick: () => void;
}): React.ReactElement {
  const hex = `#${color.toString(16).padStart(6, '0')}`;
  return (
    <button
      type="button"
      onClick={onClick}
      title={hex}
      style={{ backgroundColor: hex }}
      className={`shrink-0 w-9 h-9 rounded-full border-2 transition ${
        active ? 'border-white scale-110' : 'border-white/30 hover:border-white/60'
      }`}
    />
  );
}

/** Кадрирование камеры по модели (учитывает дюймы/Z-UP через bbox). */
function frameVisible(
  root: THREE.Object3D,
  camera: THREE.PerspectiveCamera,
  controls: OrbitControls,
): void {
  root.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(root);
  if (box.isEmpty()) {
    camera.position.set(0, 1, 3);
    return;
  }
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z) || 1;
  const dist = maxDim * 1.7;
  camera.position.set(center.x, center.y + size.y * 0.04, center.z + dist);
  camera.near = maxDim / 1000;
  camera.far = maxDim * 1000;
  camera.updateProjectionMatrix();
  controls.target.copy(center);
  controls.minDistance = maxDim * 0.4;
  controls.maxDistance = maxDim * 6;
  controls.update();
}
