/**
 * Конфигурация кастомизации аватара + персистентность (localStorage).
 *
 * Вынесено из AvatarCustomizer.tsx, чтобы не-React модули (например, сцена)
 * могли читать сохранённую конфигурацию без зависимости от React-компонента.
 */

export type AvatarConfig = {
  hair: string; // 'none' | 'hairNN'
  hat: string; // 'none' | 'hatNN'
  body: 'pants' | 'dress';
  skin: number;
  hairColor: number;
  shirtColor: number;
  pantsColor: number;
};

export const DEFAULT_AVATAR_CONFIG: AvatarConfig = {
  hair: 'hair02',
  hat: 'none',
  body: 'pants',
  skin: 0xf2cf9b,
  hairColor: 0x5a3a22,
  shirtColor: 0x3aa1d8,
  pantsColor: 0x394a5f,
};

const STORAGE_KEY = 'rv:avatar:v1';

export function loadAvatarConfig(): AvatarConfig {
  if (typeof window === 'undefined') return DEFAULT_AVATAR_CONFIG;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw) return { ...DEFAULT_AVATAR_CONFIG, ...(JSON.parse(raw) as Partial<AvatarConfig>) };
  } catch {
    /* ignore */
  }
  return DEFAULT_AVATAR_CONFIG;
}

export function saveAvatarConfig(cfg: AvatarConfig): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(cfg));
  } catch {
    /* ignore */
  }
}
