/**
 * Состояния и константы Customer FSM.
 *
 * Прямой порт com/playfish/games/cooking/actors/Customer.as.
 * Имена сохранены как в оригинале для трассируемости при сравнении поведения.
 *
 * Таймеры — в миллисекундах. В оригинале значения хранились в `ProtectedInt`
 * (защита от tampering на клиенте). В нашей архитектуре симуляция авторитарно
 * крутится на сервере, поэтому защита не нужна.
 */

export enum CustomerState {
  /** Идёт к стулу/предмету (общий «walking» с целью). */
  Walking = 0,
  /** Сел — думает 1с над меню перед заказом. */
  Deciding = 1,
  /** Делает заказ (фактически быстрый переход в Waiting). */
  Ordering = 2,
  /** Ждёт, когда повар поставит еду в раздачу. */
  Waiting = 3,
  /** Еда готова, ждёт официанта чтобы принёс. */
  WaitingForFood = 4,
  /** Ест блюдо (25с по умолчанию). */
  Eating = 5,
  /** Платит. */
  Paying = 6,
  /** Зол — сейчас уйдёт недовольным. */
  Angry = 7,
  /** Идёт на выход. */
  Leaving = 8,
  /** Ушёл — можно удалять. */
  Left = 9,
  /** Стоит у входа, ждёт когда освободится место. */
  WaitingToSit = 10,
  /** Пешеход — проходит мимо ресторана не заходя. */
  Pedestrian = 11,
  /** Развернулся из-за мусора. */
  TooMuchTrash = 12,
  /** На стуле, но нет чистого свободного столика. */
  NoTable = 13,
  /** Играет с интерактивным предметом (вместо обеда). */
  PlayingInteractiveItem = 14,
  /** Идёт в туалет. */
  WalkingToToilet = 15,
  /** Сидит в туалете. */
  OnToilet = 16,
  /** Стол занят грязной посудой. */
  NoCleanTable = 17,
  /** Идёт мыть руки. */
  WalkingToSink = 18,
  /** Моет руки. */
  UsingSink = 19,
  /** Идёт ко входу (только что появился). */
  WalkingToEntrance = 20,
  /** Ресторан закрыт. */
  RestaurantClosed = 21,

  /** Начальное состояние до первого тика. */
  Initial = -1,
}

export enum CustomerEmotion {
  None = -1,
  NoSeat = 0,
  Dirty = 1,
  WaitTooLong = 2,
  Decor = 3,
  NoTable = 4,
  NoCleanTable = 5,
  NoToilet = 6,
  WaitTooLongForDrink = 7,
}

/** Таймеры состояний (мс). */
export const CustomerTiming = {
  /** Время поедания одного блюда. */
  Eating: 25_000,
  /** Время оплаты после еды. */
  Paying: 2_000,
  /** Время использования интерактивного предмета. */
  InteractiveItem: 30_000,
  /** Ожидание официанта с заказом. */
  WaitingForOrder: 10_000,
  /** Ожидание свободного столика. */
  WaitingForTable: 20_000,
  /** Ожидание готового блюда (повар + официант). */
  WaitingForFood: 120_000,
  /** Ожидание свободного стула. */
  WaitingForChair: 5_000,
  /** Время в туалете. */
  Toilet: 10_000,
  /** Время мойки рук. */
  Sink: 4_000,
  /** Задержка после сидения перед заказом. */
  Decision: 1_000,
  /** Задержка после «слишком много мусора» до ухода. */
  TrashLeaveDelay: 2_000,
  /** Задержка при закрытии ресторана до ухода. */
  ClosedLeaveDelay: 2_000,
} as const;

/** Можно ли модифицировать таймер ожидания? (perks/декорации увеличивают терпение). */
export function isTimerExtendable(state: CustomerState): boolean {
  return (
    state === CustomerState.WaitingToSit ||
    state === CustomerState.NoTable ||
    state === CustomerState.NoCleanTable ||
    state === CustomerState.Waiting ||
    state === CustomerState.WaitingForFood
  );
}
