import type { engine } from '@rv/shared';
import { haptic } from '../telegram';

type Props = {
  report: engine.OfflineReport;
  /** Сколько мусора накопилось за это же время. */
  trash: number;
  onClose: () => void;
};

/** «2 ч 15 мин» — коротко, без секунд, если счёт идёт на часы. */
function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds} с`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes} мин`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest > 0 ? `${hours} ч ${rest} мин` : `${hours} ч`;
}

/**
 * Экран возвращения: сколько ресторан заработал без игрока.
 *
 * Порт GameWorld.init (:1251-1265) — при входе игра считала офлайн-гостей,
 * начисляла деньги с опытом и досыпала мусор. Смена длится ровно столько, на
 * сколько хватило сил персонала, поэтому здесь же объясняем, почему зал встал.
 */
export function WelcomeBack({ report, trash, onClose }: Props): React.ReactElement {
  const earned = report.coins > 0;

  return (
    <div className="absolute inset-0 z-20 flex items-center justify-center bg-black/50 p-4 pointer-events-auto">
      <div className="w-full max-w-xs rounded-2xl bg-[#161c24] border border-white/15 p-4 space-y-3">
        <div className="text-center space-y-0.5">
          <div className="text-sm font-semibold">Пока вас не было</div>
          <div className="text-xs opacity-60">{formatDuration(report.awaySeconds)}</div>
        </div>

        {earned ? (
          <div className="space-y-2">
            <Line label="Гостей обслужено" value={String(report.customers)} />
            <Line label="Заработано" value={`+${report.coins}`} accent="amber" />
            <Line
              label="Опыт"
              value={`+${Math.round(report.gourmetPoints * 10) / 10}`}
              accent="sky"
            />
            <Line label="Смена длилась" value={formatDuration(report.workedSeconds)} />
          </div>
        ) : (
          <div className="text-xs text-center opacity-70 py-2">
            Ресторан не работал: некому было готовить и подавать.
          </div>
        )}

        {report.ranOutOfEnergy && (
          <div className="text-[11px] leading-snug text-amber-200/80 bg-amber-400/10 border border-amber-300/25 rounded-lg p-2">
            У персонала кончились силы, и зал встал раньше вашего возвращения. Сами они не встанут —
            загляните к сотрудникам: покормите или отправьте отдыхать.
          </div>
        )}

        {report.cappedByEarnings && (
          <div className="text-[11px] leading-snug opacity-60">
            Касса заполнилась до предела — дольше копить смысла нет, заходите чаще.
          </div>
        )}

        {trash > 0 && (
          <div className="text-[11px] leading-snug opacity-70">
            В зале накопилось мусора: {trash}. Тапните по нему — за уборку платят.
          </div>
        )}

        <button
          type="button"
          onClick={() => {
            haptic('medium');
            onClose();
          }}
          className="w-full rounded-xl py-2.5 text-sm font-semibold bg-[var(--accent,#2f9ac8)] text-[var(--accent-fg,#fff)] active:brightness-90"
        >
          За работу
        </button>
      </div>
    </div>
  );
}

function Line({
  label,
  value,
  accent,
}: {
  label: string;
  value: string;
  accent?: 'amber' | 'sky';
}): React.ReactElement {
  const color =
    accent === 'amber' ? 'text-amber-200' : accent === 'sky' ? 'text-sky-200' : 'text-white/80';
  return (
    <div className="flex items-baseline justify-between gap-3 text-xs">
      <span className="opacity-60">{label}</span>
      <span className={`font-mono font-semibold ${color}`}>{value}</span>
    </div>
  );
}
