/**
 * Классификация ItemDefinition в одну из ItemCategory.
 *
 * В оригинале это решалось по флагам `type` (csv): tableItem, chairItem,
 * wallpaperItem, doorItem, floorTileItem, wallDecorationItem, wallItem.
 * Плюс по group. Здесь свёрнуто в одну функцию для удобства тестирования
 * и единого источника правды.
 */

import type { ItemCategory, ItemDefinition } from './types';

export function classifyItem(def: ItemDefinition): ItemCategory {
  const type = def.type;

  // Type-флаги имеют приоритет над group — это так и в оригинале.
  if (type.includes('doorItem')) return 'door';
  if (type.includes('floorTileItem')) return 'floor';
  if (type.includes('wallpaperItem')) return 'wallpaper';
  if (type.includes('wallDecorationItem')) return 'wall-decor';
  if (type.includes('wallItem')) return 'wall';
  if (type.includes('tableItem')) return 'furniture';
  if (type.includes('chairItem')) return 'furniture';

  // Падаем по group, если type невыразителен.
  switch (def.group) {
    case 'Chair':
    case 'Table':
      return 'furniture';
    case 'Door':
      return 'door';
    case 'Wall':
      return 'wall';
    case 'Wallpaper':
      return 'wallpaper';
    case 'Floor Tile':
      return 'floor';
    case 'Wall Decoration':
      return 'wall-decor';
    case 'Kitchen Appliance':
      return 'kitchen';
    case 'Decoration':
    case 'Outdoor Only':
      return 'decor';
    case 'Functional':
      return 'functional';
    default:
      return 'other';
  }
}

/** Стационарный предмет блокирует ходьбу по тайлу? */
export function isBlocking(category: ItemCategory): boolean {
  return (
    category === 'wall' ||
    category === 'furniture' ||
    category === 'kitchen' ||
    category === 'decor' ||
    category === 'functional' ||
    category === 'other'
  );
}

/** Предмет лежит в «напольном» слое — несколько предметов на тайле допустимо. */
export function isOverlay(category: ItemCategory): boolean {
  return category === 'floor' || category === 'wallpaper' || category === 'wall-decor';
}

/** Категория «прислоняется» к стене — крепится к ребру клетки и ставится только на стену. */
export function isWallCategory(category: ItemCategory): boolean {
  return (
    category === 'wall' ||
    category === 'door' ||
    category === 'wall-decor' ||
    category === 'wallpaper'
  );
}
